select ac_cargar_unidad($ac${"slug":"digital-1","rama":"digital","orden":1,"nivel":1,"titulo_es":"La huella de lo digital","bajada_es":"La nube no está en el cielo: son cables, edificios llenos de computadoras y millones de dispositivos. Cuánto pesa lo digital y qué hábitos importan de verdad.","objetivos_es":["Describir la infraestructura física que sostiene internet","Dimensionar el consumo de energía de centros de datos, redes y dispositivos","Explicar por qué la mayor huella de los dispositivos está en su fabricación","Reconocer los riesgos y el valor de la basura electrónica","Distinguir los hábitos digitales de mucho y de poco impacto"],"repasa":["tronco-2","tronco-3"],"requiere_tronco":1,"fuentes":["iea-datacenters","iea-streaming","ewaste-monitor","carbon-brief"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"digital-1.s1","orden":1,"tipo":"leccion","titulo_es":"Internet es física","bajada_es":"Cables submarinos, centros de datos, antenas y dispositivos: lo que hay detrás de un mensaje.","minutos":9,"pasos":[{"slug":"digital-1.s1.p1","orden":1,"grupo":"digital-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La nube tiene cables","cuerpo":["Cuando mandamos un mensaje o miramos un video, los datos viajan por una infraestructura física enorme: el dispositivo se conecta por wifi o por la red móvil a una antena o un router; de ahí, por cables de fibra óptica, llegan a centros de datos donde están guardados los contenidos. Entre continentes, casi todo el tráfico de internet viaja por cables submarinos.","Los centros de datos son edificios llenos de servidores —computadoras que funcionan todo el día— que necesitan electricidad para funcionar y para enfriarse."]},"solucion":{}},{"slug":"digital-1.s1.p2","orden":2,"grupo":"digital-1.s1.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el recorrido de un video que mirás en el celular.","items":[{"id":"i1","texto":"El video está guardado en un servidor de un centro de datos"},{"id":"i2","texto":"Viaja por cables de fibra óptica"},{"id":"i3","texto":"Llega a la antena o al router de tu casa"},{"id":"i4","texto":"Se transmite por wifi o red móvil a tu celular"},{"id":"i5","texto":"Tu celular lo muestra en la pantalla"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cinco eslabones físicos, cada uno con su consumo de energía."}},{"slug":"digital-1.s1.p3","orden":3,"grupo":"digital-1.s1.p3","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada parte de la infraestructura con lo que hace.","izquierda":[{"id":"a1","texto":"Centro de datos"},{"id":"a2","texto":"Cable submarino"},{"id":"a3","texto":"Antena de telefonía"},{"id":"a4","texto":"Router"}],"derecha":[{"id":"b1","texto":"Guarda y procesa la información"},{"id":"b2","texto":"Conecta continentes"},{"id":"b3","texto":"Conecta los celulares a la red"},{"id":"b4","texto":"Distribuye internet dentro de una casa"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"La \"nube\" es un nombre lindo para una infraestructura muy concreta."}},{"slug":"digital-1.s1.p4","orden":4,"grupo":"digital-1.s1.p4","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La nube es un espacio virtual que no usa recursos físicos.","razones":[{"id":"r1","texto":"Porque son centros de datos reales que usan energía y materiales"},{"id":"r2","texto":"Porque los datos flotan en el aire"},{"id":"r3","texto":"Porque la nube funciona con energía solar gratis siempre"}]},"solucion":{"valor":false,"explicacion":"La nube son centros de datos reales, con miles de servidores que usan electricidad, agua para enfriamiento y materiales para fabricarse.","clave":["r1"]}},{"slug":"digital-1.s1.p5","orden":5,"grupo":"digital-1.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las tres partes de la huella digital","cuerpo":["La huella de lo digital tiene tres grandes partes: los dispositivos (celulares, computadoras, televisores, consolas), las redes que transmiten los datos, y los centros de datos que los guardan y procesan.","De las tres, la que más pesa para una persona suele ser la fabricación de sus propios dispositivos, como vas a ver en esta unidad."]},"solucion":{}},{"slug":"digital-1.s1.p6","orden":6,"grupo":"digital-1.s1.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué parte de la huella digital pertenece cada cosa?","grupos":[{"id":"g1","nombre":"Dispositivos"},{"id":"g2","nombre":"Redes"},{"id":"g3","nombre":"Centros de datos"}],"items":[{"id":"i1","texto":"Tu celular"},{"id":"i2","texto":"La antena de telefonía"},{"id":"i3","texto":"Los servidores de una plataforma de video"},{"id":"i4","texto":"La notebook"},{"id":"i5","texto":"La fibra óptica del barrio"},{"id":"i6","texto":"El almacenamiento de tus fotos en la nube"},{"id":"i7","texto":"El televisor inteligente"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g1"},"explicacion":"Tres partes con impactos distintos. Saber cuál pesa más ordena las decisiones."}},{"slug":"digital-1.s1.p7","orden":7,"grupo":"digital-1.s1.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un centro de datos necesita tanta electricidad.","items":[{"id":"i1","texto":"Miles de servidores funcionan las 24 horas"},{"id":"i2","texto":"Consumen electricidad y generan mucho calor"},{"id":"i3","texto":"Hace falta enfriarlos constantemente"},{"id":"i4","texto":"El enfriamiento suma todavía más consumo"},{"id":"i5","texto":"Los servidores se apagan de noche para ahorrar"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Energía para calcular y energía para enfriar: las dos grandes cuentas de un centro de datos."}},{"slug":"digital-1.s1.p8","orden":8,"grupo":"digital-1.s1.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué recursos usa un centro de datos? Marcá todos.","opciones":[{"id":"o1","texto":"Electricidad"},{"id":"o2","texto":"Agua para refrigeración, en muchos casos"},{"id":"o3","texto":"Materiales para fabricar servidores"},{"id":"o4","texto":"Terreno para el edificio"},{"id":"o5","texto":"Ningún recurso, porque es virtual"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Lo digital tiene una base muy material, aunque no se vea."}},{"slug":"digital-1.s1.p9","orden":9,"grupo":"digital-1.s1.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué casi todo el tráfico de internet entre continentes viaja por cables submarinos y no por satélites?","opciones":[{"id":"o1","texto":"Porque transmiten muchos más datos"},{"id":"o2","texto":"Porque los satélites no pueden transmitir ningún dato"},{"id":"o3","texto":"Porque los cables no usan energía"},{"id":"o4","texto":"Porque el agua del mar acelera los datos"}]},"solucion":{"clave":["o1"],"explicacion":"La fibra óptica submarina tiene una capacidad enorme. Los satélites sirven, sobre todo, donde no llegan los cables.","por_opcion":{"o3":"Usan energía, pero transmiten enormes volúmenes con menos demora que los satélites."}}},{"slug":"digital-1.s1.p10","orden":10,"grupo":"digital-1.s1.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los datos viajan por cables de fibra óptica."},{"id":"s2","texto":"La nube no tiene impacto ambiental porque es invisible."},{"id":"s3","texto":"Los centros de datos necesitan refrigeración."},{"id":"s4","texto":"Los satélites llevan casi todo el tráfico entre continentes."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo digital no es inmaterial: tiene cables, edificios y aparatos.","por_opcion":{"s2":"Son centros de datos físicos que usan energía, agua y materiales.","s4":"Casi todo viaja por cables submarinos."}}},{"slug":"digital-1.s1.p11","orden":11,"grupo":"digital-1.s1.p11","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La nube está formada por centros de {{0}}; entre continentes, internet viaja por cables {{1}}.","banco":[{"id":"w1","texto":"datos"},{"id":"w2","texto":"submarinos"},{"id":"w3","texto":"nubes"},{"id":"w4","texto":"aéreos"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La infraestructura física de internet, en una línea."}},{"slug":"digital-1.s1.p12","orden":12,"grupo":"digital-1.s1.p12","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos eslabones según su distancia a vos, del más cercano al más lejano.","items":[{"id":"i1","texto":"Tu celular"},{"id":"i2","texto":"El router de tu casa"},{"id":"i3","texto":"La central del proveedor de internet"},{"id":"i4","texto":"El centro de datos"}],"extremos":["Más cercano","Más lejano"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada clic recorre una cadena física que puede cruzar el planeta.","valores":{"i1":"en tu mano","i2":"a pocos metros","i3":"en tu ciudad","i4":"puede estar en otro país"}}}]},{"slug":"digital-1.s2","orden":2,"tipo":"leccion","titulo_es":"Cuánta energía usa lo digital","bajada_es":"Centros de datos, redes y streaming: los números reales y los mitos.","minutos":11,"pasos":[{"slug":"digital-1.s2.p1","orden":1,"grupo":"digital-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los números globales","cuerpo":["Según la Agencia Internacional de Energía, en 2024 los centros de datos del mundo consumieron alrededor de 415 teravatios-hora de electricidad, cerca del 1,5 % de la electricidad mundial. Las redes de datos consumen una cantidad parecida. Y el consumo de los centros de datos está creciendo rápido, sobre todo por la inteligencia artificial.","Para comparar: Argentina entera consume alrededor de 140 teravatios-hora por año."],"destacado":{"valor":"≈ 1,5 %","texto":"de la electricidad mundial consumieron los centros de datos en 2024, según la Agencia Internacional de Energía."}},"solucion":{}},{"slug":"digital-1.s2.p2","orden":2,"grupo":"digital-1.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los centros de datos del mundo consumieron unos 415 TWh en 2024 y Argentina consume unos 140 TWh de electricidad por año. ¿Cuántas veces el consumo de Argentina es el de los centros de datos? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3,"tolerancia":0.1,"explicacion":"415 ÷ 140 ≈ 3 veces. Una forma de dimensionar un número enorme comparándolo con algo conocido."}},{"slug":"digital-1.s2.p2.v2","orden":2,"grupo":"digital-1.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los centros de datos del mundo consumieron unos 415 TWh en 2024 y Chile consume unos 85 TWh de electricidad por año. ¿Cuántas veces el consumo de Chile es el de los centros de datos? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":4.9,"tolerancia":0.1,"explicacion":"415 ÷ 85 ≈ 4,9 veces. Una forma de dimensionar un número enorme comparándolo con algo conocido."}},{"slug":"digital-1.s2.p2.v3","orden":2,"grupo":"digital-1.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los centros de datos del mundo consumieron unos 415 TWh en 2024 y Uruguay consume unos 12 TWh de electricidad por año. ¿Cuántas veces el consumo de Uruguay es el de los centros de datos? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":34.6,"tolerancia":0.1,"explicacion":"415 ÷ 12 ≈ 34,6 veces. Una forma de dimensionar un número enorme comparándolo con algo conocido."}},{"slug":"digital-1.s2.p3","orden":3,"grupo":"digital-1.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El streaming","cuerpo":["Hubo titulares que decían que mirar media hora de video emitía kilos de CO₂. Eran exageraciones basadas en cálculos equivocados. La Agencia Internacional de Energía estimó que una hora de video en streaming usa alrededor de 0,08 kWh en todo el recorrido —centro de datos, redes y dispositivo— y emite unos 36 gramos de CO₂ con la mezcla eléctrica promedio del mundo.","Es poco por hora, aunque, multiplicado por miles de millones de horas, suma. Y el dispositivo que se usa pesa: un televisor grande consume mucho más que un celular."]},"solucion":{}},{"slug":"digital-1.s2.p4","orden":4,"grupo":"digital-1.s2.p4","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos gramos de CO₂ emite una hora de streaming de video, según la Agencia Internacional de Energía (promedio mundial).","min":1,"max":5000,"paso":1,"unidad":"g","escala":"log"},"solucion":{"valor":36,"banda":"log","explicacion":"Alrededor de 36 gramos. Los titulares que hablaban de kilos por media hora eran exagerados."}},{"slug":"digital-1.s2.p5","orden":5,"grupo":"digital-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona mira 2 horas de video por día. Con 36 g de CO₂ por hora, ¿cuántos kg emite en un año de 365 días? Redondeá a un decimal.","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":26.3,"tolerancia":0.2,"explicacion":"2 × 36 × 365 = 26.280 g ≈ 26,3 kg por año. Comparalo con los ~ 500 kg por año de ir 12 km diarios solo en auto."}},{"slug":"digital-1.s2.p5.v2","orden":5,"grupo":"digital-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona mira 3 horas de video por día. Con 36 g de CO₂ por hora, ¿cuántos kg emite en un año de 365 días? Redondeá a un decimal.","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":39.4,"tolerancia":0.2,"explicacion":"3 × 36 × 365 = 39.420 g ≈ 39,4 kg por año. Comparalo con los ~ 500 kg por año de ir 12 km diarios solo en auto."}},{"slug":"digital-1.s2.p5.v3","orden":5,"grupo":"digital-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona mira 4 horas de video por día. Con 36 g de CO₂ por hora, ¿cuántos kg emite en un año de 365 días? Redondeá a un decimal.","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":52.6,"tolerancia":0.2,"explicacion":"4 × 36 × 365 = 52.560 g ≈ 52,6 kg por año. Comparalo con los ~ 500 kg por año de ir 12 km diarios solo en auto."}},{"slug":"digital-1.s2.p6","orden":6,"grupo":"digital-1.s2.p6","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas actividades por emisiones típicas, de más a menos.","items":[{"id":"i1","texto":"Un vuelo de 1.000 km ida y vuelta"},{"id":"i2","texto":"Un año yendo 12 km diarios solo en auto"},{"id":"i3","texto":"Un año mirando 2 horas de video por día"},{"id":"i4","texto":"Mandar un mail"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los órdenes de magnitud del tronco: lo digital suma, pero pesa mucho menos que volar o manejar.","valores":{"i1":"≈ 500 kg de CO₂e","i2":"≈ 500 kg de CO₂e","i3":"≈ 26 kg de CO₂","i4":"unos pocos gramos"}}},{"slug":"digital-1.s2.p7","orden":7,"grupo":"digital-1.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Mirar media hora de video emite varios kilos de CO₂.","razones":[{"id":"r1","texto":"Porque esos cálculos fueron corregidos: son decenas de gramos por hora"},{"id":"r2","texto":"Porque el video no usa electricidad"},{"id":"r3","texto":"Porque el video emite toneladas por minuto"}]},"solucion":{"valor":false,"explicacion":"Era un cálculo exagerado. Según la Agencia Internacional de Energía, una hora emite unos 36 gramos con la mezcla eléctrica promedio del mundo.","clave":["r1"]}},{"slug":"digital-1.s2.p8","orden":8,"grupo":"digital-1.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La inteligencia artificial","cuerpo":["Entrenar y usar grandes modelos de inteligencia artificial requiere muchísimo cálculo, y por eso mucha electricidad. La Agencia Internacional de Energía proyecta que el consumo de los centros de datos podría más que duplicarse hacia 2030, impulsado en buena parte por la inteligencia artificial.","Que ese crecimiento se cubra con energía limpia o con combustibles fósiles es una de las grandes preguntas energéticas de esta década."]},"solucion":{}},{"slug":"digital-1.s2.p9","orden":9,"grupo":"digital-1.s2.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el crecimiento de la inteligencia artificial afecta al sistema eléctrico.","items":[{"id":"i1","texto":"Se usan cada vez más modelos de inteligencia artificial"},{"id":"i2","texto":"Hacen falta más centros de datos y más cálculo"},{"id":"i3","texto":"Aumenta la demanda de electricidad"},{"id":"i4","texto":"Hay que generar más electricidad"},{"id":"i5","texto":"Las emisiones dependen de si esa electricidad es limpia"},{"id":"i6","texto":"La inteligencia artificial produce su propia energía"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La huella de la IA depende de cuánto crece y de cómo se genera su electricidad."}},{"slug":"digital-1.s2.p10","orden":10,"grupo":"digital-1.s2.p10","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué parte de la huella digital pesa más en cada caso?","grupos":[{"id":"g1","nombre":"La fabricación del dispositivo"},{"id":"g2","nombre":"La electricidad de uso"}],"items":[{"id":"i1","texto":"Un celular usado dos años"},{"id":"i2","texto":"Un televisor grande encendido muchas horas"},{"id":"i3","texto":"Una notebook nueva"},{"id":"i4","texto":"Una consola de juegos siempre encendida"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Los aparatos chicos tienen su huella en la fabricación; los grandes que están siempre encendidos, en el uso."}},{"slug":"digital-1.s2.p11","orden":11,"grupo":"digital-1.s2.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada número con lo que mide.","izquierda":[{"id":"a1","texto":"≈ 415 TWh"},{"id":"a2","texto":"≈ 140 TWh"},{"id":"a3","texto":"≈ 36 g"},{"id":"a4","texto":"≈ 1,5 %"}],"derecha":[{"id":"b1","texto":"Consumo de los centros de datos del mundo en 2024"},{"id":"b2","texto":"Consumo eléctrico anual de Argentina"},{"id":"b3","texto":"CO₂ de una hora de video en streaming"},{"id":"b4","texto":"Parte de la electricidad mundial que usan los centros de datos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro números para ubicar lo digital en su escala real."}},{"slug":"digital-1.s2.p12","orden":12,"grupo":"digital-1.s2.p12","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Mirando la misma serie una hora, ¿qué aparato hace que el consumo sea mayor?","opciones":[{"id":"o1","texto":"Un televisor grande"},{"id":"o2","texto":"Un celular"},{"id":"o3","texto":"Una tablet chica"},{"id":"o4","texto":"Un reloj inteligente"}]},"solucion":{"clave":["o1"],"explicacion":"El dispositivo pesa en el consumo del streaming: un televisor grande consume muchas veces más que un celular.","por_opcion":{"o3":"Las pantallas chicas consumen mucho menos que un televisor grande."}}},{"slug":"digital-1.s2.p13","orden":13,"grupo":"digital-1.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este titular y marcá lo exagerado o equivocado.","segmentos":[{"id":"s1","texto":"Los centros de datos usan alrededor del 1,5 % de la electricidad mundial."},{"id":"s2","texto":"Mirar una serie contamina más que un viaje en avión."},{"id":"s3","texto":"El consumo de los centros de datos crece por la inteligencia artificial."},{"id":"s4","texto":"Lo digital no tiene ningún impacto ambiental."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Ni exagerar ni ignorar: la clave es dimensionar con datos.","por_opcion":{"s2":"Un vuelo emite cientos de kilos; una hora de video, unos 36 gramos.","s4":"Tiene impacto, aunque cada actividad individual sea chica."}}},{"slug":"digital-1.s2.p14","orden":14,"grupo":"digital-1.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los centros de datos usan alrededor del {{0}} % de la electricidad mundial; una hora de video emite unos {{1}} gramos de CO₂.","banco":[{"id":"w1","texto":"1,5"},{"id":"w2","texto":"36"},{"id":"w3","texto":"15"},{"id":"w4","texto":"3.600"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos números para dimensionar lo digital sin exagerar."}}]},{"slug":"digital-1.s3","orden":3,"tipo":"leccion","titulo_es":"Dispositivos: la huella está en fabricarlos","bajada_es":"Por qué el celular que ya tenés es el más sustentable, y cuántos aparatos hay en una casa.","minutos":11,"pasos":[{"slug":"digital-1.s3.p1","orden":1,"grupo":"digital-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Muchos aparatos por casa","cuerpo":["Hoy una casa típica puede tener varios celulares, una o dos computadoras, televisores, tablets, consolas, parlantes inteligentes, relojes y routers. Cada uno se fabricó con minerales, energía y agua, y tiene su huella antes de encenderse por primera vez.","Como viste en la rama de Consumo, en celulares y notebooks la mayor parte de la huella de carbono de toda su vida está en la fabricación."]},"solucion":{}},{"slug":"digital-1.s3.p2","orden":2,"grupo":"digital-1.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa hay 4 celulares. Si fabricar cada uno emite unos 70 kg de CO₂e, ¿cuántos kg suma la fabricación de todos?","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":280,"tolerancia":5.6000000000000005,"explicacion":"4 × 70 = 280 kg CO₂e solo en fabricar los celulares. Por eso cambiarlos seguido multiplica la huella."}},{"slug":"digital-1.s3.p2.v2","orden":2,"grupo":"digital-1.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa hay 3 celulares. Si fabricar cada uno emite unos 60 kg de CO₂e, ¿cuántos kg suma la fabricación de todos?","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":180,"tolerancia":3.6,"explicacion":"3 × 60 = 180 kg CO₂e solo en fabricar los celulares. Por eso cambiarlos seguido multiplica la huella."}},{"slug":"digital-1.s3.p2.v3","orden":2,"grupo":"digital-1.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa hay 5 celulares. Si fabricar cada uno emite unos 80 kg de CO₂e, ¿cuántos kg suma la fabricación de todos?","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":400,"tolerancia":8,"explicacion":"5 × 80 = 400 kg CO₂e solo en fabricar los celulares. Por eso cambiarlos seguido multiplica la huella."}},{"slug":"digital-1.s3.p3","orden":3,"grupo":"digital-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto dura un celular","cuerpo":["Muchas personas cambian el celular cada dos o tres años, aunque podría durar más. Pasar de dos a cuatro años de uso reduce casi a la mitad la huella de fabricación por año. Cambiar la batería, usar funda y protector, y mantener el sistema actualizado ayudan a estirar su vida."]},"solucion":{}},{"slug":"digital-1.s3.p4","orden":4,"grupo":"digital-1.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular emite 70 kg de CO₂e. ¿Cuántos kg por año de uso se ahorran si se usa 4 años en lugar de 2?","unidad":"kg por año","decimales":1},"solucion":{"valor":17.5,"tolerancia":0.35000000000000003,"explicacion":"Con 2 años: 70 ÷ 2 = 35 kg por año. Con 4 años: 70 ÷ 4 = 17.5. Se ahorran 17.5 kg por año."}},{"slug":"digital-1.s3.p4.v2","orden":4,"grupo":"digital-1.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular emite 60 kg de CO₂e. ¿Cuántos kg por año de uso se ahorran si se usa 4 años en lugar de 2?","unidad":"kg por año","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"Con 2 años: 60 ÷ 2 = 30 kg por año. Con 4 años: 60 ÷ 4 = 15. Se ahorran 15 kg por año."}},{"slug":"digital-1.s3.p4.v3","orden":4,"grupo":"digital-1.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular emite 80 kg de CO₂e. ¿Cuántos kg por año de uso se ahorran si se usa 4 años en lugar de 2?","unidad":"kg por año","decimales":1},"solucion":{"valor":20,"tolerancia":0.4,"explicacion":"Con 2 años: 80 ÷ 2 = 40 kg por año. Con 4 años: 80 ÷ 4 = 20. Se ahorran 20 kg por año."}},{"slug":"digital-1.s3.p5","orden":5,"grupo":"digital-1.s3.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Comprar un celular nuevo más eficiente reduce la huella porque consume menos batería.","razones":[{"id":"r1","texto":"Porque la fabricación pesa mucho más que la carga"},{"id":"r2","texto":"Porque los celulares nuevos no se fabrican"},{"id":"r3","texto":"Porque la batería es la parte más contaminante del uso"}]},"solucion":{"valor":false,"explicacion":"El ahorro en la carga es mínimo comparado con la huella de fabricar uno nuevo. Para los celulares, lo más sustentable es usar más tiempo el que ya se tiene.","clave":["r1"]}},{"slug":"digital-1.s3.p6","orden":6,"grupo":"digital-1.s3.p6","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué alarga la vida de un dispositivo? Marcá todo.","opciones":[{"id":"o1","texto":"Funda y protector de pantalla"},{"id":"o2","texto":"Cambiar la batería cuando se gasta"},{"id":"o3","texto":"Mantener el sistema actualizado"},{"id":"o4","texto":"Liberar espacio en lugar de cambiar el aparato"},{"id":"o5","texto":"Cambiarlo cuando sale un modelo nuevo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cuidar, mantener y reparar son las mejores decisiones digitales."}},{"slug":"digital-1.s3.p7","orden":7,"grupo":"digital-1.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Segunda vida","cuerpo":["Cuando un celular o una computadora ya no sirve para quien lo tenía, muchas veces sirve para otra persona: un familiar, una escuela, una organización. También existen equipos reacondicionados, revisados y con garantía, que cuestan menos y evitan fabricar uno nuevo."]},"solucion":{}},{"slug":"digital-1.s3.p8","orden":8,"grupo":"digital-1.s3.p8","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená qué conviene hacer con un celular que ya no usás, de la mejor a la última opción.","items":[{"id":"i1","texto":"Seguir usándolo si funciona"},{"id":"i2","texto":"Dárselo a alguien que lo necesite"},{"id":"i3","texto":"Venderlo o entregarlo para reacondicionar"},{"id":"i4","texto":"Llevarlo a un punto de reciclaje de electrónicos"}],"extremos":["Mejor","Última opción"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La jerarquía de siempre: usar, reutilizar y, al final, reciclar."}},{"slug":"digital-1.s3.p9","orden":9,"grupo":"digital-1.s3.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción reduce la huella de los dispositivos de una casa o la aumenta?","grupos":[{"id":"g1","nombre":"La reduce"},{"id":"g2","nombre":"La aumenta"}],"items":[{"id":"i1","texto":"Compartir una tablet entre hermanos"},{"id":"i2","texto":"Un celular nuevo cada año para cada integrante"},{"id":"i3","texto":"Comprar una notebook reacondicionada"},{"id":"i4","texto":"Guardar celulares viejos en un cajón para siempre"},{"id":"i5","texto":"Arreglar el puerto de carga"},{"id":"i6","texto":"Tirar los aparatos rotos con la basura común"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Menos aparatos, más años de uso y un buen destino final."}},{"slug":"digital-1.s3.p10","orden":10,"grupo":"digital-1.s3.p10","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tu celular de tres años funciona bien pero la batería dura poco. ¿Qué conviene?","opciones":[{"id":"o1","texto":"Cambiar la batería"},{"id":"o2","texto":"Comprar uno nuevo del mismo modelo"},{"id":"o3","texto":"Cargarlo menos veces para cuidarlo"},{"id":"o4","texto":"Guardarlo y comprar uno nuevo"}]},"solucion":{"clave":["o1"],"explicacion":"Una batería nueva cuesta una fracción del aparato y puede darle dos o tres años más de vida.","por_opcion":{"o3":"No resuelve que la batería esté gastada."}}},{"slug":"digital-1.s3.p11","orden":11,"grupo":"digital-1.s3.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Usar el celular más años reduce su huella anual."},{"id":"s2","texto":"Guardar el celular viejo en un cajón es tan bueno como reciclarlo."},{"id":"s3","texto":"Los equipos reacondicionados evitan fabricar uno nuevo."},{"id":"s4","texto":"Cambiar la batería no vale la pena, conviene un celular nuevo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La decisión digital más importante es cuánto dura cada aparato.","por_opcion":{"s2":"En un cajón no sirve a nadie: conviene darlo, venderlo o reciclarlo.","s4":"Cambiar la batería alarga la vida útil con una fracción del impacto."}}},{"slug":"digital-1.s3.p12","orden":12,"grupo":"digital-1.s3.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En un celular, la mayor parte de la huella está en su {{0}}; usarlo el {{1}} de años reduce casi a la mitad su huella anual.","banco":[{"id":"w1","texto":"fabricación"},{"id":"w2","texto":"doble"},{"id":"w3","texto":"carga"},{"id":"w4","texto":"triple"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La idea central sobre la huella de los dispositivos."}},{"slug":"digital-1.s3.p13","orden":13,"grupo":"digital-1.s3.p13","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos años conviene usar, como mínimo, un celular para que su huella de fabricación por año sea la mitad que si se usara 2 años.","min":1,"max":10,"paso":1,"unidad":"años","escala":"lineal"},"solucion":{"valor":4,"banda":"lineal","explicacion":"Cuatro años: la huella de fabricación se reparte entre el doble de años. Y cada año más la sigue diluyendo."}}]},{"slug":"digital-1.s4","orden":4,"tipo":"leccion","titulo_es":"La basura electrónica","bajada_es":"Metales valiosos y sustancias peligrosas: qué tiene un aparato viejo y adónde tiene que ir.","minutos":11,"pasos":[{"slug":"digital-1.s4.p1","orden":1,"grupo":"digital-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El residuo que más crece","cuerpo":["Los residuos de aparatos eléctricos y electrónicos (RAEE) son todo lo que tiene enchufe o pilas y se descarta: celulares, computadoras, cargadores, electrodomésticos, juguetes con pilas. Según el Monitor Mundial de Residuos Electrónicos, en 2022 se generaron unos 62 millones de toneladas en el mundo, alrededor de 7,8 kg por persona, y solo un 22 % se recolectó y recicló de forma documentada.","Es uno de los tipos de residuos que más rápido crece."],"destacado":{"valor":"≈ 22 %","texto":"de la basura electrónica del mundo se recolectó y recicló de forma documentada en 2022."}},"solucion":{}},{"slug":"digital-1.s4.p2","orden":2,"grupo":"digital-1.s4.p2","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos kilos de basura electrónica por persona se generaron en el mundo en 2022.","min":0.1,"max":100,"paso":1,"unidad":"kg","escala":"log"},"solucion":{"valor":7.8,"banda":"log","explicacion":"Alrededor de 7,8 kg por persona, según el Monitor Mundial de Residuos Electrónicos. Mucho más en los países de altos ingresos."}},{"slug":"digital-1.s4.p3","orden":3,"grupo":"digital-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo valioso y lo peligroso","cuerpo":["Un aparato electrónico tiene metales valiosos —cobre, oro, plata, paladio— que se pueden recuperar, y también sustancias peligrosas, como plomo, mercurio, cadmio y retardantes de llama. Si se tira con la basura común o se quema, esas sustancias pueden contaminar el suelo, el agua y el aire, y dañar la salud de quienes manipulan los residuos.","Las baterías de litio, además, pueden incendiarse si se aplastan en un camión o en un relleno."]},"solucion":{}},{"slug":"digital-1.s4.p4","orden":4,"grupo":"digital-1.s4.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un material valioso para recuperar o una sustancia peligrosa?","grupos":[{"id":"g1","nombre":"Valioso"},{"id":"g2","nombre":"Peligroso"}],"items":[{"id":"i1","texto":"Cobre"},{"id":"i2","texto":"Plomo"},{"id":"i3","texto":"Oro"},{"id":"i4","texto":"Mercurio"},{"id":"i5","texto":"Plata"},{"id":"i6","texto":"Cadmio"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La basura electrónica es a la vez un tesoro y un riesgo. Todo depende de adónde va."}},{"slug":"digital-1.s4.p5","orden":5,"grupo":"digital-1.s4.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué puede pasar si una batería de litio va a la basura común.","items":[{"id":"i1","texto":"Se tira una batería de litio con la basura común"},{"id":"i2","texto":"El camión compactador la aplasta"},{"id":"i3","texto":"La batería se daña y se calienta"},{"id":"i4","texto":"Puede iniciar un incendio en el camión o en el relleno"},{"id":"i5","texto":"La batería se descarga sola y desaparece"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las baterías de litio nunca van a la basura común: tienen que ir a puntos de recolección."}},{"slug":"digital-1.s4.p6","orden":6,"grupo":"digital-1.s4.p6","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un celular viejo se puede tirar con la basura común sin problema.","razones":[{"id":"r1","texto":"Porque tiene sustancias peligrosas y metales recuperables"},{"id":"r2","texto":"Porque los celulares se descomponen en semanas"},{"id":"r3","texto":"Porque la basura común separa los celulares automáticamente"}]},"solucion":{"valor":false,"explicacion":"Tiene sustancias peligrosas y una batería que puede incendiarse, además de metales valiosos que se pierden. Tiene que ir a un punto de recolección de electrónicos.","clave":["r1"]}},{"slug":"digital-1.s4.p7","orden":7,"grupo":"digital-1.s4.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se generaron 62 millones de toneladas de basura electrónica y se recicló de forma documentada el 22 %, ¿cuántos millones de toneladas se reciclaron? Redondeá a un decimal.","unidad":"millones de toneladas","decimales":1},"solucion":{"valor":13.6,"tolerancia":0.1,"explicacion":"62 × 22 ÷ 100 ≈ 13,6 millones de toneladas. El resto, más de 48 millones, no tuvo un destino documentado."}},{"slug":"digital-1.s4.p8","orden":8,"grupo":"digital-1.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Adónde llevarla","cuerpo":["Muchos municipios tienen puntos verdes o campañas de recolección de electrónicos y pilas. Algunos comercios y fabricantes reciben aparatos viejos. Antes de entregar un celular o una computadora, conviene borrar los datos personales.","En varios lugares, cooperativas y empresas especializadas desarman los aparatos, recuperan los metales y tratan de forma segura las sustancias peligrosas."]},"solucion":{}},{"slug":"digital-1.s4.p9","orden":9,"grupo":"digital-1.s4.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para desprenderte bien de una notebook vieja.","items":[{"id":"i1","texto":"Evaluar si alguien puede seguir usándola"},{"id":"i2","texto":"Hacer una copia de tus archivos"},{"id":"i3","texto":"Borrar tus datos personales"},{"id":"i4","texto":"Entregarla para reutilizar o en un punto de recolección de electrónicos"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero reutilizar; si no se puede, reciclar bien y cuidando tus datos."}},{"slug":"digital-1.s4.p10","orden":10,"grupo":"digital-1.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué cosas son residuos electrónicos que no van a la basura común? Marcá todas.","opciones":[{"id":"o1","texto":"Cargadores viejos"},{"id":"o2","texto":"Pilas y baterías"},{"id":"o3","texto":"Auriculares rotos"},{"id":"o4","texto":"Un secador de pelo roto"},{"id":"o5","texto":"Una caja de cartón del celular"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Todo lo que tuvo enchufe o pilas es RAEE. La caja de cartón va con los reciclables de papel."}},{"slug":"digital-1.s4.p11","orden":11,"grupo":"digital-1.s4.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos destinos para un celular roto, del mejor al peor.","items":[{"id":"i1","texto":"Repararlo y seguir usándolo"},{"id":"i2","texto":"Llevarlo a un punto de recolección de electrónicos"},{"id":"i3","texto":"Guardarlo años en un cajón"},{"id":"i4","texto":"Tirarlo con la basura común"}],"extremos":["Mejor","Peor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Reparar primero; si no, reciclar bien. El cajón y la basura desperdician materiales valiosos.","valores":{"i1":"el mejor","i2":"bueno","i3":"malo","i4":"muy malo"}}},{"slug":"digital-1.s4.p12","orden":12,"grupo":"digital-1.s4.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Antes de entregar un celular para reciclar o donar, conviene borrar tus datos personales.","razones":[{"id":"r1","texto":"Porque así se protege tu información personal"},{"id":"r2","texto":"Porque los datos hacen más pesado el celular"},{"id":"r3","texto":"Porque sin borrar los datos no se puede reciclar el cobre"}]},"solucion":{"valor":true,"explicacion":"Así se protege tu información. Se hace una copia de lo que quieras conservar y se restablece el equipo de fábrica.","clave":["r1"]}},{"slug":"digital-1.s4.p13","orden":13,"grupo":"digital-1.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos y marcá los equivocados.","segmentos":[{"id":"s1","texto":"Llevá las pilas a un punto de recolección."},{"id":"s2","texto":"Quemá los cables viejos para sacar el cobre."},{"id":"s3","texto":"Borrá tus datos antes de entregar un celular."},{"id":"s4","texto":"Las baterías de litio van con la basura común."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen destino protege el ambiente, la salud de los trabajadores y tus datos.","por_opcion":{"s2":"Quemar cables libera humos tóxicos: es peligroso y contaminante.","s4":"Pueden incendiarse: van a puntos de recolección."}}},{"slug":"digital-1.s4.p14","orden":14,"grupo":"digital-1.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los residuos de aparatos con enchufe o pilas se llaman {{0}}; solo un {{1}} % de la basura electrónica del mundo se recicla de forma documentada.","banco":[{"id":"w1","texto":"RAEE"},{"id":"w2","texto":"22"},{"id":"w3","texto":"RSU"},{"id":"w4","texto":"80"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos datos clave sobre la basura electrónica."}}]},{"slug":"digital-1.s5","orden":5,"tipo":"leccion","titulo_es":"Hábitos digitales que importan","bajada_es":"Borrar mails, bajar la resolución, apagar el router o conservar el celular: qué pesa y qué casi no.","minutos":11,"pasos":[{"slug":"digital-1.s5.p1","orden":1,"grupo":"digital-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ordenar por impacto","cuerpo":["Hay muchos consejos sobre \"higiene digital\": borrar mails, no guardar fotos repetidas, bajar la calidad del video. Tienen algún efecto, pero chico comparado con otras decisiones. Lo que más pesa en la huella digital de una persona es cuántos aparatos tiene y cuánto le duran, y cuánto tiempo están encendidos los aparatos grandes, como televisores y consolas.","Como en el tronco: primero lo grande, después lo chico."]},"solucion":{}},{"slug":"digital-1.s5.p2","orden":2,"grupo":"digital-1.s5.p2","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos hábitos digitales por su efecto en la huella, de mayor a menor.","items":[{"id":"i1","texto":"Usar el celular 4 años en vez de 2"},{"id":"i2","texto":"Apagar el televisor y la consola cuando no se usan"},{"id":"i3","texto":"Mirar video en calidad estándar en vez de 4K"},{"id":"i4","texto":"Borrar mails viejos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La duración de los dispositivos pesa mucho más que la limpieza de la bandeja de entrada.","valores":{"i1":"efecto grande","i2":"efecto moderado","i3":"efecto chico","i4":"efecto muy chico"}}},{"slug":"digital-1.s5.p3","orden":3,"grupo":"digital-1.s5.p3","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Borrar todos los mails viejos es una de las acciones más efectivas para el clima.","razones":[{"id":"r1","texto":"Porque su efecto es muy chico comparado con otras acciones"},{"id":"r2","texto":"Porque los mails no se guardan en ningún lado"},{"id":"r3","texto":"Porque borrar mails aumenta las emisiones"}]},"solucion":{"valor":false,"explicacion":"Tiene un efecto muy chico. Usar los dispositivos más años o cambiar un hábito de transporte pesan muchísimo más.","clave":["r1"]}},{"slug":"digital-1.s5.p4","orden":4,"grupo":"digital-1.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El stand-by digital","cuerpo":["Televisores, decodificadores, consolas y parlantes inteligentes pueden consumir energía aunque parezcan apagados. Una consola que queda en modo de encendido rápido puede consumir bastante más que en apagado total. Como viste en la rama de Energía, el stand-by suma a lo largo del año."]},"solucion":{}},{"slug":"digital-1.s5.p5","orden":5,"grupo":"digital-1.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una consola en modo de encendido rápido consume 15 W las 20 horas del día que no se usa. ¿Cuántos kWh usa por año así? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":110,"tolerancia":1,"explicacion":"0,015 kW × 20 h × 365 ≈ 110 kWh por año, sin usarla. Apagarla del todo evita casi todo ese consumo."}},{"slug":"digital-1.s5.p5.v2","orden":5,"grupo":"digital-1.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una consola en modo de encendido rápido consume 10 W las 20 horas del día que no se usa. ¿Cuántos kWh usa por año así? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":73,"tolerancia":1,"explicacion":"0,01 kW × 20 h × 365 ≈ 73 kWh por año, sin usarla. Apagarla del todo evita casi todo ese consumo."}},{"slug":"digital-1.s5.p5.v3","orden":5,"grupo":"digital-1.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una consola en modo de encendido rápido consume 20 W las 20 horas del día que no se usa. ¿Cuántos kWh usa por año así? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":146,"tolerancia":1,"explicacion":"0,02 kW × 20 h × 365 ≈ 146 kWh por año, sin usarla. Apagarla del todo evita casi todo ese consumo."}},{"slug":"digital-1.s5.p6","orden":6,"grupo":"digital-1.s5.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este hábito tiene un efecto grande o chico sobre la huella digital?","grupos":[{"id":"g1","nombre":"Grande"},{"id":"g2","nombre":"Chico"}],"items":[{"id":"i1","texto":"Cambiar el celular cada 4 años en lugar de cada año"},{"id":"i2","texto":"Borrar fotos repetidas de la nube"},{"id":"i3","texto":"No tener un televisor en cada habitación"},{"id":"i4","texto":"Mandar menos mails de \"gracias\""},{"id":"i5","texto":"Comprar una notebook reacondicionada"},{"id":"i6","texto":"Usar el modo oscuro en el celular"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los hábitos chicos no están mal, pero no reemplazan a los grandes."}},{"slug":"digital-1.s5.p7","orden":7,"grupo":"digital-1.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo digital que ahorra","cuerpo":["Lo digital también puede ahorrar mucho: una videollamada en lugar de un vuelo de negocios, trabajar desde casa algunos días en lugar de viajar en auto, una factura electrónica en lugar de una en papel que se imprime y se transporta. En esos casos, la huella digital es muy chica comparada con lo que se evita."]},"solucion":{}},{"slug":"digital-1.s5.p8","orden":8,"grupo":"digital-1.s5.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una reunión presencial requiere un vuelo de ida y vuelta de 1.000 km por tramo (246 g por km). Una videollamada de 2 horas emite unos 100 g. ¿Cuántos kg de CO₂e se ahorran con la videollamada? Redondeá al entero.","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":492,"tolerancia":1,"explicacion":"Vuelo: 2 × 1.000 × 246 = 492.000 g. Menos 100 g de la videollamada: se ahorran unos 492 kg."}},{"slug":"digital-1.s5.p8.v2","orden":8,"grupo":"digital-1.s5.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una reunión presencial requiere un vuelo de ida y vuelta de 700 km por tramo (246 g por km). Una videollamada de 2 horas emite unos 100 g. ¿Cuántos kg de CO₂e se ahorran con la videollamada? Redondeá al entero.","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":344,"tolerancia":1,"explicacion":"Vuelo: 2 × 700 × 246 = 344.400 g. Menos 100 g de la videollamada: se ahorran unos 344 kg."}},{"slug":"digital-1.s5.p8.v3","orden":8,"grupo":"digital-1.s5.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una reunión presencial requiere un vuelo de ida y vuelta de 1.500 km por tramo (246 g por km). Una videollamada de 2 horas emite unos 100 g. ¿Cuántos kg de CO₂e se ahorran con la videollamada? Redondeá al entero.","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":738,"tolerancia":1,"explicacion":"Vuelo: 2 × 1.500 × 246 = 738.000 g. Menos 100 g de la videollamada: se ahorran unos 738 kg."}},{"slug":"digital-1.s5.p9","orden":9,"grupo":"digital-1.s5.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el trabajo remoto algunos días puede bajar emisiones.","items":[{"id":"i1","texto":"Una persona trabaja desde casa dos días por semana"},{"id":"i2","texto":"Deja de viajar en auto esos días"},{"id":"i3","texto":"Ahorra el combustible de esos viajes"},{"id":"i4","texto":"Su huella baja mucho más de lo que suma la videollamada"},{"id":"i5","texto":"La computadora de casa emite más que el auto"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Pero ojo: si trabajar desde casa implica calefaccionar toda la casa todo el día, parte del ahorro se pierde. Siempre hay que mirar el sistema completo."}},{"slug":"digital-1.s5.p10","orden":10,"grupo":"digital-1.s5.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hábitos digitales valen la pena? Marcá todos.","opciones":[{"id":"o1","texto":"Usar los dispositivos el mayor tiempo posible"},{"id":"o2","texto":"Apagar del todo televisores y consolas"},{"id":"o3","texto":"Evitar tener aparatos duplicados que no se usan"},{"id":"o4","texto":"Reemplazar viajes largos por videollamadas cuando se puede"},{"id":"o5","texto":"Comprar un parlante inteligente para cada habitación"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Menos aparatos, más años de uso, menos stand-by y viajes evitados."}},{"slug":"digital-1.s5.p11","orden":11,"grupo":"digital-1.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Mirando lo mismo durante una hora, ¿qué consume más energía?","opciones":[{"id":"o1","texto":"Un televisor de 55 pulgadas"},{"id":"o2","texto":"Un celular"},{"id":"o3","texto":"Una notebook con la pantalla al mínimo"},{"id":"o4","texto":"Un parlante chico con radio"}]},"solucion":{"clave":["o1"],"explicacion":"La pantalla grande es la que más consume. Mirar en el dispositivo más chico que sirva ahorra energía.","por_opcion":{"o3":"Consume más que un celular, pero bastante menos que un televisor grande."}}},{"slug":"digital-1.s5.p12","orden":12,"grupo":"digital-1.s5.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Usar el modo oscuro en el celular es uno de los hábitos digitales de mayor impacto.","razones":[{"id":"r1","texto":"Porque su efecto es mínimo comparado con la vida útil del aparato"},{"id":"r2","texto":"Porque el modo oscuro aumenta mucho las emisiones"},{"id":"r3","texto":"Porque el celular no usa energía"}]},"solucion":{"valor":false,"explicacion":"Puede ahorrar un poco de batería en algunas pantallas, pero su efecto es mínimo comparado con usar el celular más años.","clave":["r1"]}},{"slug":"digital-1.s5.p13","orden":13,"grupo":"digital-1.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan digital de una familia y marcá lo que casi no ayuda o empeora.","segmentos":[{"id":"s1","texto":"Vamos a usar los celulares hasta que no den más."},{"id":"s2","texto":"Vamos a borrar los mails todos los días para salvar el planeta, y cambiar los celulares cada año."},{"id":"s3","texto":"Vamos a apagar la consola del todo cuando no se usa."},{"id":"s4","texto":"Vamos a comprar un televisor más para cada cuarto."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan digital pone primero lo que más pesa.","por_opcion":{"s2":"Borrar mails casi no ayuda, y cambiar los celulares cada año aumenta mucho la huella.","s4":"Más aparatos es más huella de fabricación y de uso."}}},{"slug":"digital-1.s5.p14","orden":14,"grupo":"digital-1.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Lo que más pesa en la huella digital personal es cuánto {{0}} los dispositivos; borrar mails tiene un efecto muy {{1}}.","banco":[{"id":"w1","texto":"duran"},{"id":"w2","texto":"chico"},{"id":"w3","texto":"cuestan"},{"id":"w4","texto":"grande"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La regla para ordenar los hábitos digitales."}}]},{"slug":"digital-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: la huella de lo digital","bajada_es":"Infraestructura, energía, dispositivos, basura electrónica y hábitos, mezclados.","minutos":8,"pasos":[{"slug":"digital-1.s6.p1","orden":1,"grupo":"digital-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «La huella de lo digital». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"digital-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la casa conectada de los Romero","bajada_es":"Los Romero quieren bajar su huella digital. Con los números, ordená qué hacer primero.","minutos":10,"pasos":[{"slug":"digital-1.s7.p1","orden":1,"grupo":"digital-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La casa","cuerpo":["Los Romero son cuatro. Cada uno cambia el celular cada dos años. Tienen tres televisores, una consola que queda en modo de encendido rápido (15 W, 20 horas por día), un cajón con cinco celulares viejos y dos notebooks rotas. Miran unas 4 horas de video por día entre todos.","Supongamos que fabricar un celular emite 70 kg de CO₂e."]},"solucion":{}},{"slug":"digital-1.s7.p2","orden":2,"grupo":"digital-1.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kg de CO₂e por año suma la fabricación de los celulares, si cada uno de los cuatro cambia el suyo cada dos años?","unidad":"kg CO₂e por año","decimales":0,"contexto":"4 personas, cambian el celular cada 2 años; 70 kg de CO₂e por celular."},"solucion":{"valor":140,"tolerancia":2.8000000000000003,"explicacion":"4 celulares × 70 kg ÷ 2 años = 140 kg por año solo en fabricar celulares nuevos."}},{"slug":"digital-1.s7.p3","orden":3,"grupo":"digital-1.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Y si cada uno lo usara 4 años?","unidad":"kg CO₂e por año","decimales":0,"contexto":"Los mismos 4 celulares, usados 4 años cada uno."},"solucion":{"valor":70,"tolerancia":1.4000000000000001,"explicacion":"4 × 70 ÷ 4 = 70 kg por año: la mitad, solo con usar los celulares más tiempo."}},{"slug":"digital-1.s7.p4","orden":4,"grupo":"digital-1.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kWh por año usa la consola en modo de encendido rápido? Redondeá al entero.","unidad":"kWh","decimales":0,"contexto":"Consola: 15 W, 20 horas por día en encendido rápido."},"solucion":{"valor":110,"tolerancia":1,"explicacion":"0,015 kW × 20 h × 365 ≈ 110 kWh por año sin usarla. Apagarla del todo evita casi todo."}},{"slug":"digital-1.s7.p5","orden":5,"grupo":"digital-1.s7.p5","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas por impacto, de mayor a menor.","items":[{"id":"i1","texto":"Usar los celulares 4 años en vez de 2"},{"id":"i2","texto":"Apagar del todo la consola"},{"id":"i3","texto":"Llevar los celulares y notebooks viejos a reciclar"},{"id":"i4","texto":"Borrar los mails de todos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero la vida útil de los aparatos, después el stand-by y el destino final. Los mails, al final.","valores":{"i1":"ahorra ≈ 70 kg CO₂e por año","i2":"ahorra ≈ 110 kWh por año","i3":"evita contaminación y recupera metales","i4":"efecto muy chico"}}},{"slug":"digital-1.s7.p6","orden":6,"grupo":"digital-1.s7.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene hacer con los cinco celulares viejos del cajón?","opciones":[{"id":"o1","texto":"Donar los que funcionan y llevar el resto a reciclar"},{"id":"o2","texto":"Dejarlos en el cajón por si algún día sirven"},{"id":"o3","texto":"Tirarlos con la basura común"},{"id":"o4","texto":"Quemarlos para recuperar metales"}]},"solucion":{"clave":["o1"],"explicacion":"En un cajón no sirven a nadie. Donados o reciclados, sí.","por_opcion":{"o3":"Tienen baterías que pueden incendiarse y sustancias peligrosas."}}},{"slug":"digital-1.s7.p7","orden":7,"grupo":"digital-1.s7.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas de la familia.","grupos":[{"id":"g1","nombre":"Ayudan"},{"id":"g2","nombre":"No ayudan o empeoran"}],"items":[{"id":"i1","texto":"Cambiar la batería del celular de la abuela"},{"id":"i2","texto":"Comprar un cuarto televisor para la cocina"},{"id":"i3","texto":"Desenchufar el televisor del cuarto que casi no se usa"},{"id":"i4","texto":"Guardar los aparatos rotos en el cajón"},{"id":"i5","texto":"Llevar las notebooks rotas a un punto de RAEE"},{"id":"i6","texto":"Cambiar todos los celulares por el último modelo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Menos aparatos, más años de uso, menos stand-by y buen destino final."}},{"slug":"digital-1.s7.p8","orden":8,"grupo":"digital-1.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Los Romero escriben su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Vamos a usar los celulares al menos 4 años."},{"id":"s2","texto":"Como miramos 4 horas de video por día, es lo que más contamina en casa: vamos a dejar de mirar."},{"id":"s3","texto":"Llevamos los celulares viejos a un punto de recolección, con los datos borrados."},{"id":"s4","texto":"Dejamos la consola en encendido rápido para que arranque antes."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un plan digital eficaz empieza por lo que más pesa.","por_opcion":{"s2":"4 horas de video son unos 144 g por día: mucho menos que la fabricación de los celulares.","s4":"Consume unos 110 kWh por año sin usarse."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"digital-2","rama":"digital","orden":2,"nivel":1,"titulo_es":"Tecnología que ayuda","bajada_es":"Satélites que detectan incendios, sensores que miden el aire y apps que suman a la ciencia: lo que la tecnología hace por el ambiente, y lo que no puede hacer.","objetivos_es":["Describir cómo los satélites ayudan a vigilar bosques, incendios, agua y hielo","Explicar el valor de los sensores y los datos abiertos","Participar de proyectos de ciencia ciudadana con buenos registros","Reconocer cómo la tecnología ayuda a usar mejor la energía","Evaluar los límites de la tecnología: efecto rebote, brecha digital y tecnosolucionismo"],"repasa":["digital-1","tronco-1"],"requiere_tronco":1,"fuentes":["global-forest-watch","nasa-firms","conae","argentinat","ebird","gbif","iea-eficiencia"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"digital-2.s1","orden":1,"tipo":"leccion","titulo_es":"El planeta visto desde el espacio","bajada_es":"Satélites que detectan desmontes, incendios, glaciares que retroceden y suelos húmedos o secos.","minutos":12,"pasos":[{"slug":"digital-2.s1.p1","orden":1,"grupo":"digital-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ojos en órbita","cuerpo":["Cientos de satélites observan la Tierra todos los días. Con sus imágenes se puede ver dónde se desmontó un bosque, dónde hay un incendio activo, cómo retrocede un glaciar, cuánta agua tiene una laguna o qué tan húmedo está el suelo.","Muchos de esos datos son abiertos y gratuitos: cualquiera puede consultarlos en internet. Eso permitió que organizaciones, periodistas y vecinos vigilen lo que antes solo veían los gobiernos."]},"solucion":{}},{"slug":"digital-2.s1.p2","orden":2,"grupo":"digital-2.s1.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué se puede observar con satélites? Marcá todo.","opciones":[{"id":"o1","texto":"Desmontes de bosques"},{"id":"o2","texto":"Incendios activos"},{"id":"o3","texto":"Retroceso de glaciares"},{"id":"o4","texto":"Superficie de lagunas y humedales"},{"id":"o5","texto":"Qué especie de pájaro canta en tu plaza"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los satélites ven cambios de superficie grandes. Para las especies, hacen falta observaciones en el terreno."}},{"slug":"digital-2.s1.p3","orden":3,"grupo":"digital-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Incendios en tiempo casi real","cuerpo":["Sistemas como FIRMS, de la NASA, detectan focos de calor desde satélites y publican su ubicación en pocas horas. Brigadistas, investigadores y periodistas los usan para seguir incendios, como los de los humedales del Delta del Paraná en 2020, 2022 y 2023.","También se usan imágenes posteriores para medir cuántas hectáreas se quemaron."]},"solucion":{}},{"slug":"digital-2.s1.p4","orden":4,"grupo":"digital-2.s1.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un satélite ayuda a combatir un incendio.","items":[{"id":"i1","texto":"Un satélite detecta un foco de calor anómalo"},{"id":"i2","texto":"El sistema publica su ubicación en pocas horas"},{"id":"i3","texto":"Las brigadas ven el foco en el mapa"},{"id":"i4","texto":"Llegan antes al lugar"},{"id":"i5","texto":"Es más fácil controlar el fuego mientras es chico"},{"id":"i6","texto":"El satélite apaga el fuego desde el espacio"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Detectar temprano es clave: un incendio chico es mucho más fácil de controlar."}},{"slug":"digital-2.s1.p5","orden":5,"grupo":"digital-2.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Bosques y desmontes","cuerpo":["Plataformas como Global Forest Watch muestran, a partir de imágenes satelitales, dónde se perdió cobertura forestal año a año, y emiten alertas casi semanales de desmontes. En el Gran Chaco, uno de los lugares con mayor pérdida de bosques del mundo, estas herramientas permiten ver desmontes incluso en zonas donde la ley no los permite."]},"solucion":{}},{"slug":"digital-2.s1.p6","orden":6,"grupo":"digital-2.s1.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué permite hacer una plataforma de alertas de desmonte con imágenes satelitales?","opciones":[{"id":"o1","texto":"Ver dónde y cuándo se pierde bosque, casi en tiempo real"},{"id":"o2","texto":"Plantar árboles automáticamente desde el espacio"},{"id":"o3","texto":"Castigar a los responsables sin ninguna investigación"},{"id":"o4","texto":"Saber cuántos pájaros hay en cada árbol"}]},"solucion":{"clave":["o1"],"explicacion":"La imagen es evidencia. Transformarla en protección requiere controles, leyes y decisiones.","por_opcion":{"o3":"Las imágenes muestran el cambio; después hacen falta controles en el terreno y la ley."}}},{"slug":"digital-2.s1.p7","orden":7,"grupo":"digital-2.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Satélites argentinos","cuerpo":["Argentina tiene su propia agencia espacial, la CONAE, que desarrolló satélites de observación de la Tierra. Los satélites SAOCOM usan un radar que \"ve\" a través de las nubes y de noche, y miden la humedad del suelo: esos mapas sirven para planificar la agricultura, anticipar inundaciones y seguir sequías."]},"solucion":{}},{"slug":"digital-2.s1.p8","orden":8,"grupo":"digital-2.s1.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con lo que observa.","izquierda":[{"id":"a1","texto":"FIRMS (NASA)"},{"id":"a2","texto":"Global Forest Watch"},{"id":"a3","texto":"SAOCOM (CONAE)"},{"id":"a4","texto":"Imágenes de glaciares en distintos años"}],"derecha":[{"id":"b1","texto":"Focos de incendios activos"},{"id":"b2","texto":"Pérdida de bosques y alertas de desmonte"},{"id":"b3","texto":"Humedad del suelo con radar"},{"id":"b4","texto":"Retroceso del hielo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Distintas herramientas para distintas preguntas sobre el planeta."}},{"slug":"digital-2.s1.p9","orden":9,"grupo":"digital-2.s1.p9","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un radar satelital como el de los SAOCOM no puede observar cuando hay nubes.","razones":[{"id":"r1","texto":"Porque el radar emite su propia señal que atraviesa las nubes"},{"id":"r2","texto":"Porque los radares solo funcionan de día"},{"id":"r3","texto":"Porque las nubes reflejan el radar hacia el espacio"}]},"solucion":{"valor":false,"explicacion":"El radar emite su propia señal y la atraviesa por las nubes, de día y de noche. Por eso es muy útil en temporadas de lluvias.","clave":["r1"]}},{"slug":"digital-2.s1.p10","orden":10,"grupo":"digital-2.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un satélite muestra que se quemaron 5.000 hectáreas de humedal. Si una cancha de fútbol tiene unas 0,7 hectáreas, ¿a cuántas canchas equivale? Redondeá al entero.","unidad":"canchas","decimales":0},"solucion":{"valor":7143,"tolerancia":2,"explicacion":"5.000 ÷ 0,7 ≈ 7.143 canchas. Traducir hectáreas a algo conocido ayuda a dimensionar."}},{"slug":"digital-2.s1.p10.v2","orden":10,"grupo":"digital-2.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un satélite muestra que se quemaron 12.000 hectáreas de humedal. Si una cancha de fútbol tiene unas 0,7 hectáreas, ¿a cuántas canchas equivale? Redondeá al entero.","unidad":"canchas","decimales":0},"solucion":{"valor":17143,"tolerancia":2,"explicacion":"12.000 ÷ 0,7 ≈ 17.143 canchas. Traducir hectáreas a algo conocido ayuda a dimensionar."}},{"slug":"digital-2.s1.p10.v3","orden":10,"grupo":"digital-2.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un satélite muestra que se quemaron 800 hectáreas de humedal. Si una cancha de fútbol tiene unas 0,7 hectáreas, ¿a cuántas canchas equivale? Redondeá al entero.","unidad":"canchas","decimales":0},"solucion":{"valor":1143,"tolerancia":2,"explicacion":"800 ÷ 0,7 ≈ 1.143 canchas. Traducir hectáreas a algo conocido ayuda a dimensionar."}},{"slug":"digital-2.s1.p11","orden":11,"grupo":"digital-2.s1.p11","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta pregunta se responde bien con satélites o necesita trabajo en el terreno?","grupos":[{"id":"g1","nombre":"Satélite"},{"id":"g2","nombre":"Terreno"}],"items":[{"id":"i1","texto":"¿Cuántas hectáreas se desmontaron este año?"},{"id":"i2","texto":"¿Qué especies de ranas viven en esta laguna?"},{"id":"i3","texto":"¿Dónde hay focos de incendio ahora?"},{"id":"i4","texto":"¿Qué contaminantes tiene el agua del arroyo?"},{"id":"i5","texto":"¿Cuánto retrocedió un glaciar en diez años?"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Satélites y trabajo en el terreno se complementan: uno ve lo grande, el otro lo fino."}},{"slug":"digital-2.s1.p12","orden":12,"grupo":"digital-2.s1.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas herramientas según qué tan rápido informan un cambio, de más rápida a más lenta.","items":[{"id":"i1","texto":"Detección de focos de incendio"},{"id":"i2","texto":"Alertas de desmonte"},{"id":"i3","texto":"Mapas de pérdida de bosque"},{"id":"i4","texto":"Comparación de glaciares"}],"extremos":["Más rápida","Más lenta"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada fenómeno tiene su ritmo: un incendio se mide en horas; un glaciar, en años.","valores":{"i1":"en horas","i2":"semanales","i3":"anuales","i4":"entre años o décadas"}}},{"slug":"digital-2.s1.p13","orden":13,"grupo":"digital-2.s1.p13","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los datos de los satélites de observación de la Tierra son siempre secretos y pagos.","razones":[{"id":"r1","texto":"Porque muchos son abiertos y gratuitos"},{"id":"r2","texto":"Porque los satélites no generan datos"},{"id":"r3","texto":"Porque solo los militares pueden ver imágenes satelitales"}]},"solucion":{"valor":false,"explicacion":"Muchos son abiertos y gratuitos, como los de FIRMS o los mapas de Global Forest Watch. Eso permite que cualquiera los use para vigilar el ambiente.","clave":["r1"]}},{"slug":"digital-2.s1.p14","orden":14,"grupo":"digital-2.s1.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los satélites pueden detectar focos de incendio."},{"id":"s2","texto":"Si un satélite detecta un desmonte, el problema se resuelve solo."},{"id":"s3","texto":"Muchos datos satelitales son abiertos y gratuitos."},{"id":"s4","texto":"Con un satélite se sabe qué especies de insectos hay en un campo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los satélites son poderosos, pero no lo resuelven todo.","por_opcion":{"s2":"La imagen es evidencia; hacen falta controles y aplicar la ley.","s4":"Eso requiere observaciones en el terreno."}}},{"slug":"digital-2.s1.p15","orden":15,"grupo":"digital-2.s1.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los satélites detectan focos de {{0}} y {{1}}; los SAOCOM argentinos miden la humedad del {{2}}.","banco":[{"id":"w1","texto":"incendio"},{"id":"w2","texto":"desmontes"},{"id":"w3","texto":"suelo"},{"id":"w4","texto":"lluvia"},{"id":"w5","texto":"terremotos"},{"id":"w6","texto":"mar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres usos de los satélites para el ambiente."}}]},{"slug":"digital-2.s2","orden":2,"tipo":"leccion","titulo_es":"Sensores y datos abiertos","bajada_es":"Estaciones meteorológicas, sensores de aire y agua, y por qué los datos abiertos cambian las reglas.","minutos":11,"pasos":[{"slug":"digital-2.s2.p1","orden":1,"grupo":"digital-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Medir en todos lados","cuerpo":["Además de los satélites, hay redes de sensores en el terreno: estaciones meteorológicas que miden lluvia, temperatura y viento; sensores de calidad del aire; medidores del nivel de los ríos; boyas en el mar. Juntos permiten pronosticar el tiempo, alertar crecidas y seguir la contaminación.","Los sensores de bajo costo hicieron posible que escuelas y vecinos midan su propio aire o su propia lluvia, como viste en la rama de Aire y Suelo."]},"solucion":{}},{"slug":"digital-2.s2.p2","orden":2,"grupo":"digital-2.s2.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada sensor con lo que mide.","izquierda":[{"id":"a1","texto":"Pluviómetro"},{"id":"a2","texto":"Sensor de PM2,5"},{"id":"a3","texto":"Limnímetro"},{"id":"a4","texto":"Anemómetro"}],"derecha":[{"id":"b1","texto":"Lluvia"},{"id":"b2","texto":"Partículas finas en el aire"},{"id":"b3","texto":"Nivel del agua de un río"},{"id":"b4","texto":"Velocidad del viento"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada instrumento responde una pregunta concreta."}},{"slug":"digital-2.s2.p3","orden":3,"grupo":"digital-2.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Datos abiertos","cuerpo":["Los datos abiertos son datos que cualquiera puede consultar, descargar y usar libremente. Muchos organismos publican datos ambientales abiertos: emisiones, calidad del agua, lluvias, caudales, áreas protegidas.","En Argentina, la Ley 25.831 garantiza el derecho de acceso a la información pública ambiental. Cuando los datos son abiertos, más personas pueden analizarlos, detectar problemas y controlar a quienes toman decisiones."]},"solucion":{}},{"slug":"digital-2.s2.p4","orden":4,"grupo":"digital-2.s2.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo los datos abiertos pueden mejorar una política ambiental.","items":[{"id":"i1","texto":"Un organismo publica los datos de calidad del agua de un río"},{"id":"i2","texto":"Periodistas e investigadores los analizan"},{"id":"i3","texto":"Detectan un punto que empeora año a año"},{"id":"i4","texto":"Lo difunden y los vecinos piden explicaciones"},{"id":"i5","texto":"El organismo investiga y toma medidas"},{"id":"i6","texto":"Los datos abiertos arreglan el río automáticamente"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La transparencia multiplica los ojos que miran. Es una herramienta de control ciudadano."}},{"slug":"digital-2.s2.p5","orden":5,"grupo":"digital-2.s2.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los datos ambientales públicos solo pueden usarlos los organismos del Estado.","razones":[{"id":"r1","texto":"Porque la ley garantiza el acceso a la información ambiental"},{"id":"r2","texto":"Porque los datos ambientales son secretos por ley"},{"id":"r3","texto":"Porque solo los científicos pueden leer datos"}]},"solucion":{"valor":false,"explicacion":"La Ley 25.831 garantiza el acceso a la información pública ambiental. Los datos abiertos pueden usarlos cualquier persona, escuela u organización.","clave":["r1"]}},{"slug":"digital-2.s2.p6","orden":6,"grupo":"digital-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Calidad de los datos","cuerpo":["No todos los datos valen lo mismo. Un sensor sin calibrar, mal ubicado o sin mantenimiento puede dar números equivocados. Por eso los datos buenos vienen con información sobre cómo se midieron: dónde, cuándo, con qué instrumento y con qué precisión. Esa información se llama metadatos."]},"solucion":{}},{"slug":"digital-2.s2.p7","orden":7,"grupo":"digital-2.s2.p7","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué información debería acompañar a un conjunto de datos para confiar en él? Marcá todo.","opciones":[{"id":"o1","texto":"Dónde se midió"},{"id":"o2","texto":"Cuándo se midió"},{"id":"o3","texto":"Con qué instrumento"},{"id":"o4","texto":"Qué precisión tiene"},{"id":"o5","texto":"Quién tiene más seguidores en redes"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los metadatos permiten saber si un dato sirve para lo que se quiere usar."}},{"slug":"digital-2.s2.p8","orden":8,"grupo":"digital-2.s2.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este sensor está bien ubicado o mal ubicado?","grupos":[{"id":"g1","nombre":"Bien ubicado"},{"id":"g2","nombre":"Mal ubicado"}],"items":[{"id":"i1","texto":"Termómetro a la sombra, en un abrigo ventilado"},{"id":"i2","texto":"Termómetro al sol sobre una chapa"},{"id":"i3","texto":"Pluviómetro en un lugar abierto, lejos de árboles"},{"id":"i4","texto":"Pluviómetro debajo de un árbol"},{"id":"i5","texto":"Sensor de aire a la altura de las personas"},{"id":"i6","texto":"Sensor de aire pegado al caño de escape de un generador"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La ubicación puede arruinar la medición del mejor instrumento. Es el error sistemático de la rama de Ciencia."}},{"slug":"digital-2.s2.p9","orden":9,"grupo":"digital-2.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pluviómetro escolar registró en una semana: 12, 0, 35, 8, 0, 20, 5 mm. ¿Cuántos mm llovieron en total?","unidad":"mm","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"12 + 0 + 35 + 8 + 0 + 20 + 5 = 80 mm. Cada milímetro equivale a un litro por metro cuadrado."}},{"slug":"digital-2.s2.p9.v2","orden":9,"grupo":"digital-2.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pluviómetro escolar registró en una semana: 0, 4, 0, 60, 2, 0, 14 mm. ¿Cuántos mm llovieron en total?","unidad":"mm","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"0 + 4 + 0 + 60 + 2 + 0 + 14 = 80 mm. Cada milímetro equivale a un litro por metro cuadrado."}},{"slug":"digital-2.s2.p9.v3","orden":9,"grupo":"digital-2.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pluviómetro escolar registró en una semana: 25, 18, 0, 0, 3, 40, 9 mm. ¿Cuántos mm llovieron en total?","unidad":"mm","decimales":0},"solucion":{"valor":95,"tolerancia":1.9000000000000001,"explicacion":"25 + 18 + 0 + 0 + 3 + 40 + 9 = 95 mm. Cada milímetro equivale a un litro por metro cuadrado."}},{"slug":"digital-2.s2.p10","orden":10,"grupo":"digital-2.s2.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un municipio quiere saber si el aire de un barrio mejoró. ¿Qué es lo más importante del sensor?","opciones":[{"id":"o1","texto":"Medir siempre en el mismo lugar y con el mismo método"},{"id":"o2","texto":"Que tenga una pantalla de colores"},{"id":"o3","texto":"Moverlo cada semana a un lugar distinto"},{"id":"o4","texto":"Que lo instale la persona con más seguidores"}]},"solucion":{"clave":["o1"],"explicacion":"Para comparar en el tiempo, hay que mantener constantes el lugar y el método.","por_opcion":{"o3":"Si cambia el lugar, no se puede saber si cambió el aire o cambió la ubicación."}}},{"slug":"digital-2.s2.p11","orden":11,"grupo":"digital-2.s2.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe barrial y marcá lo problemático.","segmentos":[{"id":"s1","texto":"Instalamos un pluviómetro en la terraza, lejos de paredes."},{"id":"s2","texto":"El termómetro lo pusimos sobre la chapa del techo para que tome bien el sol."},{"id":"s3","texto":"Publicamos los datos con fecha, lugar e instrumento."},{"id":"s4","texto":"No anotamos cuándo cambiamos las pilas del sensor, no importa."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Datos buenos: bien medidos y bien documentados.","por_opcion":{"s2":"Al sol marca más que la temperatura del aire: es un error sistemático.","s4":"Los cambios en el instrumento son metadatos importantes para interpretar los datos."}}},{"slug":"digital-2.s2.p12","orden":12,"grupo":"digital-2.s2.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los datos que cualquiera puede usar se llaman datos {{0}}; la información sobre cómo se midieron se llama {{1}}.","banco":[{"id":"w1","texto":"abiertos"},{"id":"w2","texto":"metadatos"},{"id":"w3","texto":"cerrados"},{"id":"w4","texto":"rumores"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos conceptos para usar bien los datos ambientales."}},{"slug":"digital-2.s2.p13","orden":13,"grupo":"digital-2.s2.p13","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos litros de agua caen sobre un metro cuadrado con una lluvia de 20 mm.","min":1,"max":200,"paso":1,"unidad":"litros","escala":"lineal"},"solucion":{"valor":20,"banda":"lineal","explicacion":"Un milímetro de lluvia es un litro por metro cuadrado: 20 mm son 20 litros en cada metro cuadrado."}}]},{"slug":"digital-2.s3","orden":3,"tipo":"leccion","titulo_es":"Ciencia ciudadana con el celular","bajada_es":"Fotos de especies, registros de aves y reportes ambientales: cómo cualquiera puede aportar datos útiles a la ciencia.","minutos":11,"pasos":[{"slug":"digital-2.s3.p1","orden":1,"grupo":"digital-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es la ciencia ciudadana","cuerpo":["La ciencia ciudadana es la participación de personas no especialistas en investigaciones científicas: contar aves, fotografiar plantas e insectos, medir la lluvia, reportar la calidad del agua. Con millones de participantes se reúnen datos que ningún equipo científico podría juntar solo.","En Argentina, plataformas como ArgentiNat (la versión local de iNaturalist) y eBird reúnen cientos de miles de observaciones que usan investigadores y organismos de conservación. Muchas terminan en bases de datos globales como GBIF."]},"solucion":{}},{"slug":"digital-2.s3.p2","orden":2,"grupo":"digital-2.s3.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada plataforma con lo que se registra en ella.","izquierda":[{"id":"a1","texto":"ArgentiNat"},{"id":"a2","texto":"eBird"},{"id":"a3","texto":"GBIF"}],"derecha":[{"id":"b1","texto":"Fotos de cualquier ser vivo con su ubicación"},{"id":"b2","texto":"Listas de aves observadas"},{"id":"b3","texto":"Base global que reúne registros de biodiversidad"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Tres herramientas conectadas: los registros locales alimentan bases globales."}},{"slug":"digital-2.s3.p3","orden":3,"grupo":"digital-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un buen registro","cuerpo":["Para que una observación sirva a la ciencia necesita: una foto nítida (o varias, de distintos ángulos), la fecha, la ubicación precisa y, si se puede, una nota sobre el ambiente. En ArgentiNat, otras personas —incluidas especialistas— ayudan a identificar la especie; cuando varias coinciden, el registro pasa a \"grado de investigación\".","Un registro sin ubicación o con una foto borrosa casi no sirve, aunque la especie sea rara."]},"solucion":{}},{"slug":"digital-2.s3.p4","orden":4,"grupo":"digital-2.s3.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace útil un registro de ciencia ciudadana? Marcá todo.","opciones":[{"id":"o1","texto":"Foto nítida"},{"id":"o2","texto":"Fecha"},{"id":"o3","texto":"Ubicación precisa"},{"id":"o4","texto":"Nota sobre el ambiente"},{"id":"o5","texto":"Un filtro de colores en la foto"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los filtros pueden cambiar los colores y dificultar la identificación."}},{"slug":"digital-2.s3.p5","orden":5,"grupo":"digital-2.s3.p5","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para subir un buen registro a ArgentiNat.","items":[{"id":"i1","texto":"Encontrar un ser vivo sin molestarlo"},{"id":"i2","texto":"Sacar varias fotos nítidas desde distintos ángulos"},{"id":"i3","texto":"Registrar fecha y ubicación"},{"id":"i4","texto":"Subirlo con una identificación tentativa"},{"id":"i5","texto":"Esperar que la comunidad confirme la especie"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Observar sin molestar, documentar bien y dejar que la comunidad ayude a identificar."}},{"slug":"digital-2.s3.p6","orden":6,"grupo":"digital-2.s3.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una foto en tu patio puede ayudar a la conservación.","items":[{"id":"i1","texto":"Fotografiás una rana en tu patio y la subís con ubicación"},{"id":"i2","texto":"La comunidad confirma que es una especie amenazada"},{"id":"i3","texto":"El registro llega a bases de datos de biodiversidad"},{"id":"i4","texto":"Investigadores descubren que hay una población en tu zona"},{"id":"i5","texto":"Se pueden tomar medidas para proteger ese ambiente"},{"id":"i6","texto":"La foto hace que la rana deje de estar amenazada"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Muchos descubrimientos empezaron con un registro de alguien no especialista."}},{"slug":"digital-2.s3.p7","orden":7,"grupo":"digital-2.s3.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los datos de ciencia ciudadana no sirven porque no los toman especialistas.","razones":[{"id":"r1","texto":"Porque con buenos registros y verificación se usan en investigaciones"},{"id":"r2","texto":"Porque los especialistas no revisan nunca los datos"},{"id":"r3","texto":"Porque solo sirven los datos de satélites"}]},"solucion":{"valor":false,"explicacion":"Con buenos registros y verificación de la comunidad, se usan en investigaciones publicadas y en decisiones de conservación. La cantidad y la cobertura compensan muchas limitaciones.","clave":["r1"]}},{"slug":"digital-2.s3.p8","orden":8,"grupo":"digital-2.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuidar lo que se observa","cuerpo":["Observar no debe dañar: no se sacan animales de su lugar para fotografiarlos, no se acercan a nidos, no se pisotean plantas. En especies muy amenazadas o buscadas por el tráfico, las plataformas pueden ocultar la ubicación exacta para protegerlas."]},"solucion":{}},{"slug":"digital-2.s3.p9","orden":9,"grupo":"digital-2.s3.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica es correcta o incorrecta al hacer ciencia ciudadana?","grupos":[{"id":"g1","nombre":"Correcta"},{"id":"g2","nombre":"Incorrecta"}],"items":[{"id":"i1","texto":"Fotografiar un ave desde lejos con zoom"},{"id":"i2","texto":"Mover un sapo a un lugar más lindo para la foto"},{"id":"i3","texto":"Registrar una planta sin arrancarla"},{"id":"i4","texto":"Acercarse a un nido para una mejor toma"},{"id":"i5","texto":"Ocultar la ubicación de una especie buscada por traficantes"},{"id":"i6","texto":"Arrancar una flor para fotografiarla en casa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La ciencia ciudadana suma datos sin restar naturaleza."}},{"slug":"digital-2.s3.p10","orden":10,"grupo":"digital-2.s3.p10","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Encontrás un ave rara y querés registrarla. ¿Qué es lo más importante?","opciones":[{"id":"o1","texto":"Una foto nítida con fecha y ubicación, sin molestarla"},{"id":"o2","texto":"Acercarte lo más posible aunque se asuste"},{"id":"o3","texto":"Esperar a que vuelva otro día para estar seguro"},{"id":"o4","texto":"Compartirla solo en tus redes sin ubicación"}]},"solucion":{"clave":["o1"],"explicacion":"Un buen registro, hecho con respeto, es el aporte.","por_opcion":{"o3":"Registrá lo que viste ahora: un registro bien documentado ya es valioso."}}},{"slug":"digital-2.s3.p11","orden":11,"grupo":"digital-2.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un censo de aves, 500 personas hacen 20 registros cada una. ¿Cuántos registros se juntan?","unidad":"registros","decimales":0},"solucion":{"valor":10000,"tolerancia":200,"explicacion":"500 × 20 = 10.000 registros. Ningún equipo científico podría juntar tantos por su cuenta."}},{"slug":"digital-2.s3.p11.v2","orden":11,"grupo":"digital-2.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un censo de aves, 1.000 personas hacen 15 registros cada una. ¿Cuántos registros se juntan?","unidad":"registros","decimales":0},"solucion":{"valor":15000,"tolerancia":300,"explicacion":"1.000 × 15 = 15.000 registros. Ningún equipo científico podría juntar tantos por su cuenta."}},{"slug":"digital-2.s3.p11.v3","orden":11,"grupo":"digital-2.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un censo de aves, 200 personas hacen 50 registros cada una. ¿Cuántos registros se juntan?","unidad":"registros","decimales":0},"solucion":{"valor":10000,"tolerancia":200,"explicacion":"200 × 50 = 10.000 registros. Ningún equipo científico podría juntar tantos por su cuenta."}},{"slug":"digital-2.s3.p12","orden":12,"grupo":"digital-2.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo de un grupo de observadores y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Registrá fecha y ubicación en cada observación."},{"id":"s2","texto":"Si el ave está lejos, tirale una piedra cerca para que se mueva."},{"id":"s3","texto":"Dejá que la comunidad ayude con la identificación."},{"id":"s4","texto":"Si no estás seguro de la especie, no lo subas nunca."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Registros buenos y respetuosos: la base de la ciencia ciudadana.","por_opcion":{"s2":"Nunca se molesta a la fauna para una foto.","s4":"Se puede subir con una identificación tentativa: la comunidad ayuda."}}},{"slug":"digital-2.s3.p13","orden":13,"grupo":"digital-2.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La participación de personas no especialistas en investigaciones se llama ciencia {{0}}; un buen registro necesita foto, fecha y {{1}}.","banco":[{"id":"w1","texto":"ciudadana"},{"id":"w2","texto":"ubicación"},{"id":"w3","texto":"privada"},{"id":"w4","texto":"filtro"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La idea central de la lección, resumida en una línea."}}]},{"slug":"digital-2.s4","orden":4,"tipo":"leccion","titulo_es":"Energía inteligente","bajada_es":"Medidores inteligentes, termostatos, gestión de la demanda y redes que se adaptan a las renovables.","minutos":11,"pasos":[{"slug":"digital-2.s4.p1","orden":1,"grupo":"digital-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ver el consumo en tiempo real","cuerpo":["Los medidores inteligentes registran el consumo de electricidad hora por hora y lo muestran en una app o en la factura. Ver cuándo y en qué se consume ayuda a detectar derroches, como un aparato que queda encendido de noche.","Los termostatos programables apagan o bajan la calefacción cuando no hay nadie, y la encienden un rato antes de volver."]},"solucion":{}},{"slug":"digital-2.s4.p2","orden":2,"grupo":"digital-2.s4.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un medidor inteligente ayuda a ahorrar.","items":[{"id":"i1","texto":"El medidor registra el consumo hora por hora"},{"id":"i2","texto":"La familia ve un consumo alto a las 3 de la mañana"},{"id":"i3","texto":"Descubre un calefactor olvidado en una habitación"},{"id":"i4","texto":"Lo apaga y el consumo nocturno baja"},{"id":"i5","texto":"El medidor apaga solo cualquier aparato"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Ver el consumo es el primer paso para cambiarlo. Medir para entender, como en el tronco."}},{"slug":"digital-2.s4.p3","orden":3,"grupo":"digital-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La demanda y las renovables","cuerpo":["La electricidad tiene que producirse en el mismo momento en que se consume. El sol y el viento no siempre generan cuando más se necesita. Por eso, cada vez más, se busca mover el consumo a los momentos de más generación renovable: cargar un auto eléctrico o calentar agua cuando hay mucho viento o sol.","Eso se llama gestión de la demanda, y la tecnología digital —precios que cambian por hora, aparatos que se encienden solos en el mejor momento— la hace posible."]},"solucion":{}},{"slug":"digital-2.s4.p4","orden":4,"grupo":"digital-2.s4.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es la gestión de la demanda eléctrica?","opciones":[{"id":"o1","texto":"Mover consumos a los momentos en que conviene generar"},{"id":"o2","texto":"Prohibir el uso de electricidad de noche"},{"id":"o3","texto":"Producir siempre la misma cantidad de electricidad"},{"id":"o4","texto":"Cobrar lo mismo sin importar la hora"}]},"solucion":{"clave":["o1"],"explicacion":"Adaptar el consumo a la generación, sobre todo cuando hay mucho sol y viento, ayuda a integrar renovables.","por_opcion":{"o3":"La generación y el consumo cambian; la idea es acercarlos."}}},{"slug":"digital-2.s4.p5","orden":5,"grupo":"digital-2.s4.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este uso se puede mover a otro horario o no conviene moverlo?","grupos":[{"id":"g1","nombre":"Se puede mover"},{"id":"g2","nombre":"No conviene moverlo"}],"items":[{"id":"i1","texto":"Cargar un auto eléctrico"},{"id":"i2","texto":"La heladera"},{"id":"i3","texto":"Calentar agua en un termotanque eléctrico"},{"id":"i4","texto":"La luz de la cocina mientras cocinás"},{"id":"i5","texto":"Poner el lavarropas"},{"id":"i6","texto":"Un respirador médico"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los consumos flexibles son la herramienta de la gestión de la demanda."}},{"slug":"digital-2.s4.p6","orden":6,"grupo":"digital-2.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico carga 10 kWh por día. Si el kWh cuesta $150 en horario pico y $90 de madrugada, ¿cuánto se ahorra por día cargando de madrugada?","unidad":"$","decimales":0},"solucion":{"valor":600,"tolerancia":12,"explicacion":"10 × (150 − 90) = $600 por día. Los precios por horario incentivan mover el consumo."}},{"slug":"digital-2.s4.p6.v2","orden":6,"grupo":"digital-2.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico carga 15 kWh por día. Si el kWh cuesta $180 en horario pico y $100 de madrugada, ¿cuánto se ahorra por día cargando de madrugada?","unidad":"$","decimales":0},"solucion":{"valor":1200,"tolerancia":24,"explicacion":"15 × (180 − 100) = $1.200 por día. Los precios por horario incentivan mover el consumo."}},{"slug":"digital-2.s4.p6.v3","orden":6,"grupo":"digital-2.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico carga 8 kWh por día. Si el kWh cuesta $120 en horario pico y $70 de madrugada, ¿cuánto se ahorra por día cargando de madrugada?","unidad":"$","decimales":0},"solucion":{"valor":400,"tolerancia":8,"explicacion":"8 × (120 − 70) = $400 por día. Los precios por horario incentivan mover el consumo."}},{"slug":"digital-2.s4.p7","orden":7,"grupo":"digital-2.s4.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La electricidad se puede producir de sobra un día y guardarla toda en los cables para usarla después.","razones":[{"id":"r1","texto":"Porque los cables transportan pero no almacenan energía"},{"id":"r2","texto":"Porque la electricidad se guarda en los enchufes"},{"id":"r3","texto":"Porque sobra electricidad siempre"}]},"solucion":{"valor":false,"explicacion":"Los cables no guardan energía. Para almacenar hacen falta baterías, represas de bombeo u otros sistemas. Por eso importa acercar el consumo a la generación.","clave":["r1"]}},{"slug":"digital-2.s4.p8","orden":8,"grupo":"digital-2.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Edificios que se regulan solos","cuerpo":["En edificios grandes, sistemas de gestión digital controlan la iluminación, la calefacción y el aire acondicionado según la ocupación, la hora y el clima. Con sensores de presencia y de luz natural, se pueden lograr ahorros importantes sin que nadie tenga que acordarse de apagar nada."]},"solucion":{}},{"slug":"digital-2.s4.p9","orden":9,"grupo":"digital-2.s4.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué tecnologías ayudan a ahorrar energía en un edificio? Marcá todas.","opciones":[{"id":"o1","texto":"Sensores de presencia para las luces"},{"id":"o2","texto":"Termostatos programables"},{"id":"o3","texto":"Medidores inteligentes"},{"id":"o4","texto":"Sensores de luz natural"},{"id":"o5","texto":"Pantallas encendidas las 24 horas en cada pasillo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La tecnología que mide y controla puede ahorrar mucho. La que suma consumo sin sentido, no."}},{"slug":"digital-2.s4.p10","orden":10,"grupo":"digital-2.s4.p10","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada tecnología con lo que hace.","izquierda":[{"id":"a1","texto":"Medidor inteligente"},{"id":"a2","texto":"Termostato programable"},{"id":"a3","texto":"Sensor de presencia"},{"id":"a4","texto":"Precio por horario"}],"derecha":[{"id":"b1","texto":"Muestra el consumo hora por hora"},{"id":"b2","texto":"Ajusta la calefacción según el horario"},{"id":"b3","texto":"Apaga luces donde no hay nadie"},{"id":"b4","texto":"Incentiva consumir en las mejores horas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro herramientas de la energía inteligente."}},{"slug":"digital-2.s4.p11","orden":11,"grupo":"digital-2.s4.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un medidor inteligente reduce el consumo por sí solo, aunque nadie cambie nada.","razones":[{"id":"r1","texto":"Porque el ahorro depende de lo que se haga con la información"},{"id":"r2","texto":"Porque los medidores apagan toda la casa"},{"id":"r3","texto":"Porque los medidores consumen más de lo que ahorran"}]},"solucion":{"valor":false,"explicacion":"El medidor muestra la información; el ahorro aparece cuando alguien actúa con ella, o cuando se combina con aparatos que se regulan solos.","clave":["r1"]}},{"slug":"digital-2.s4.p12","orden":12,"grupo":"digital-2.s4.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Es un día de mucho viento, la red tiene energía eólica de sobra y el precio está bajo. ¿Qué conviene hacer con un termotanque eléctrico programable?","opciones":[{"id":"o1","texto":"Calentar el agua en ese momento"},{"id":"o2","texto":"Apagarlo hasta que baje el viento"},{"id":"o3","texto":"Esperar al horario pico de la noche"},{"id":"o4","texto":"Desenchufarlo para siempre"}]},"solucion":{"clave":["o1"],"explicacion":"Guardar energía como agua caliente cuando sobra renovable es gestión de la demanda en acción.","por_opcion":{"o3":"En el pico la electricidad es más cara y suele generarse con más gas."}}},{"slug":"digital-2.s4.p13","orden":13,"grupo":"digital-2.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta publicidad y marcá lo exagerado.","segmentos":[{"id":"s1","texto":"Nuestro termostato apaga la calefacción cuando no hay nadie."},{"id":"s2","texto":"Con nuestra app, tu casa no va a consumir energía nunca más."},{"id":"s3","texto":"El medidor te muestra el consumo de cada hora."},{"id":"s4","texto":"Instalar un sensor compensa tener la calefacción a 26 °C todo el día."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La tecnología es una aliada, no una varita mágica.","por_opcion":{"s2":"Puede ayudar a ahorrar, pero la casa sigue consumiendo energía.","s4":"La tecnología ayuda, pero no compensa un hábito que derrocha mucho."}}},{"slug":"digital-2.s4.p14","orden":14,"grupo":"digital-2.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Mover consumos a las horas de más generación se llama gestión de la {{0}}; los medidores {{1}} muestran el consumo por hora.","banco":[{"id":"w1","texto":"demanda"},{"id":"w2","texto":"inteligentes"},{"id":"w3","texto":"oferta"},{"id":"w4","texto":"analógicos"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas clave de la energía inteligente."}}]},{"slug":"digital-2.s5","orden":5,"tipo":"leccion","titulo_es":"Los límites de la tecnología","bajada_es":"Efecto rebote, brecha digital, privacidad y la tentación de creer que la tecnología sola lo resuelve todo.","minutos":12,"pasos":[{"slug":"digital-2.s5.p1","orden":1,"grupo":"digital-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El efecto rebote","cuerpo":["Cuando una tecnología hace algo más eficiente y más barato, a veces se usa tanto más que el ahorro se achica o desaparece. Se llama efecto rebote. Si las lámparas LED gastan poco, puede que se dejen más luces encendidas; si un auto consume menos, puede que se viaje más.","La eficiencia sigue siendo buena, pero hay que acompañarla con hábitos y reglas para que el ahorro se mantenga."]},"solucion":{}},{"slug":"digital-2.s5.p2","orden":2,"grupo":"digital-2.s5.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de un efecto rebote.","items":[{"id":"i1","texto":"Un auto nuevo consume la mitad de nafta"},{"id":"i2","texto":"Viajar en auto se vuelve más barato"},{"id":"i3","texto":"La familia viaja más kilómetros"},{"id":"i4","texto":"Parte del ahorro de nafta se pierde"},{"id":"i5","texto":"El auto eficiente obliga a viajar menos"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La eficiencia ahorra, salvo que el ahorro se \"gaste\" usando más."}},{"slug":"digital-2.s5.p3","orden":3,"grupo":"digital-2.s5.p3","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una tecnología más eficiente siempre reduce el consumo total en la misma proporción.","razones":[{"id":"r1","texto":"Porque el efecto rebote puede aumentar el uso"},{"id":"r2","texto":"Porque las tecnologías eficientes consumen más"},{"id":"r3","texto":"Porque la eficiencia no existe"}]},"solucion":{"valor":false,"explicacion":"Por el efecto rebote, parte del ahorro puede perderse si se usa más. Hace falta acompañar la eficiencia con hábitos y reglas.","clave":["r1"]}},{"slug":"digital-2.s5.p4","orden":4,"grupo":"digital-2.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Brecha digital","cuerpo":["No todas las personas tienen el mismo acceso a la tecnología: conexión, dispositivos, habilidades. Si las soluciones ambientales dependen solo de apps o de aparatos caros, pueden dejar afuera a quienes más necesitan ayuda. Una buena política ambiental piensa también en quienes no tienen acceso."]},"solucion":{}},{"slug":"digital-2.s5.p5","orden":5,"grupo":"digital-2.s5.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un municipio anuncia que las alertas de inundación solo se enviarán por una app. ¿Cuál es el problema?","opciones":[{"id":"o1","texto":"Deja afuera a quienes no tienen celular o conexión"},{"id":"o2","texto":"Las apps no pueden enviar alertas"},{"id":"o3","texto":"Ninguno: todo el mundo tiene la app"},{"id":"o4","texto":"Las inundaciones no se pueden pronosticar"}]},"solucion":{"clave":["o1"],"explicacion":"Las alertas tienen que llegar a todos: sirenas, radio, mensajes de texto y referentes barriales, además de apps.","por_opcion":{"o3":"No todos tienen celular, datos o la app instalada, y a menudo son quienes viven en zonas más expuestas."}}},{"slug":"digital-2.s5.p6","orden":6,"grupo":"digital-2.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tecnosolucionismo","cuerpo":["El tecnosolucionismo es la idea de que cualquier problema se resuelve con una tecnología nueva, sin cambiar hábitos, reglas ni sistemas. Por ejemplo, esperar que una máquina capture todo el CO₂ en lugar de dejar de emitirlo, o que una app resuelva la basura sin separar ni reducir.","La tecnología ayuda mucho, pero casi siempre funciona mejor combinada con cambios de comportamiento, de políticas y de diseño."]},"solucion":{}},{"slug":"digital-2.s5.p7","orden":7,"grupo":"digital-2.s5.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un enfoque equilibrado o tecnosolucionista?","grupos":[{"id":"g1","nombre":"Equilibrado"},{"id":"g2","nombre":"Tecnosolucionista"}],"items":[{"id":"i1","texto":"Sensores de aire más una ley que controle las emisiones"},{"id":"i2","texto":"Seguir emitiendo porque algún día se inventará algo"},{"id":"i3","texto":"Satélites para detectar desmontes más controles en el terreno"},{"id":"i4","texto":"Una app de reciclaje sin sistema de recolección"},{"id":"i5","texto":"Medidores inteligentes más hábitos de ahorro"},{"id":"i6","texto":"Plantar árboles digitales en un juego para compensar un vuelo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La tecnología potencia las soluciones; rara vez las reemplaza."}},{"slug":"digital-2.s5.p8","orden":8,"grupo":"digital-2.s5.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué riesgos tiene confiar todo a la tecnología? Marcá todos.","opciones":[{"id":"o1","texto":"Efecto rebote que se come el ahorro"},{"id":"o2","texto":"Dejar afuera a quienes no tienen acceso"},{"id":"o3","texto":"Postergar cambios necesarios esperando un invento"},{"id":"o4","texto":"Problemas de privacidad con los datos personales"},{"id":"o5","texto":"Que la tecnología funcione demasiado bien"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Reconocer los riesgos permite aprovechar la tecnología sin caer en sus trampas."}},{"slug":"digital-2.s5.p9","orden":9,"grupo":"digital-2.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Privacidad","cuerpo":["Muchas tecnologías inteligentes recolectan datos personales: cuándo estás en tu casa, cuánto consumís, por dónde te movés. Esos datos pueden ayudar a ahorrar, pero también pueden usarse para otras cosas. Conviene saber qué datos recolecta una app o un aparato, quién los usa y para qué."]},"solucion":{}},{"slug":"digital-2.s5.p10","orden":10,"grupo":"digital-2.s5.p10","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para usar una app de energía cuidando tus datos.","items":[{"id":"i1","texto":"Leer qué datos recolecta"},{"id":"i2","texto":"Revisar quién los usa y para qué"},{"id":"i3","texto":"Ajustar los permisos a lo necesario"},{"id":"i4","texto":"Usarla para detectar consumos y ahorrar"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Aprovechar la tecnología con criterio, también sobre la propia información."}},{"slug":"digital-2.s5.p11","orden":11,"grupo":"digital-2.s5.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas soluciones para bajar las emisiones de una ciudad, de la más completa a la más limitada.","items":[{"id":"i1","texto":"Transporte público eléctrico más ciclovías más reglas de estacionamiento"},{"id":"i2","texto":"Colectivos eléctricos sin cambios en la frecuencia"},{"id":"i3","texto":"Una app que calcula tu huella de transporte"},{"id":"i4","texto":"Esperar autos voladores eléctricos"}],"extremos":["Más completa","Más limitada"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las soluciones más completas combinan tecnología con cambios en el sistema.","valores":{"i1":"combina tecnología, diseño y reglas","i2":"tecnología sola, útil","i3":"informa pero no cambia opciones","i4":"tecnosolucionismo"}}},{"slug":"digital-2.s5.p12","orden":12,"grupo":"digital-2.s5.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su ejemplo.","izquierda":[{"id":"a1","texto":"Efecto rebote"},{"id":"a2","texto":"Brecha digital"},{"id":"a3","texto":"Tecnosolucionismo"},{"id":"a4","texto":"Privacidad"}],"derecha":[{"id":"b1","texto":"Con lámparas LED, se dejan más luces prendidas"},{"id":"b2","texto":"Alertas solo por app en barrios sin conexión"},{"id":"b3","texto":"Seguir emitiendo esperando un invento"},{"id":"b4","texto":"Una app que sabe cuándo no hay nadie en casa"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro límites de la tecnología que conviene reconocer en la vida real."}},{"slug":"digital-2.s5.p13","orden":13,"grupo":"digital-2.s5.p13","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia viajaba 10.000 km por año con un auto que gastaba 8 L cada 100 km. Cambia a uno que gasta 4 L cada 100 km y, como sale más barato, pasa a viajar 12.000 km. ¿Cuántos litros de nafta ahorra de verdad por año?","unidad":"litros","decimales":0},"solucion":{"valor":320,"tolerancia":6.4,"explicacion":"Antes: 10.000 × 8 ÷ 100 = 800 L. Ahora: 12.000 × 4 ÷ 100 = 480 L. Ahorra 320 L, en vez de los 400 L que ahorraría sin viajar más: eso es el efecto rebote."}},{"slug":"digital-2.s5.p13.v2","orden":13,"grupo":"digital-2.s5.p13","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia viajaba 10.000 km por año con un auto que gastaba 8 L cada 100 km. Cambia a uno que gasta 4 L cada 100 km y, como sale más barato, pasa a viajar 14.000 km. ¿Cuántos litros de nafta ahorra de verdad por año?","unidad":"litros","decimales":0},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"Antes: 10.000 × 8 ÷ 100 = 800 L. Ahora: 14.000 × 4 ÷ 100 = 560 L. Ahorra 240 L, en vez de los 400 L que ahorraría sin viajar más: eso es el efecto rebote."}},{"slug":"digital-2.s5.p13.v3","orden":13,"grupo":"digital-2.s5.p13","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia viajaba 10.000 km por año con un auto que gastaba 8 L cada 100 km. Cambia a uno que gasta 4 L cada 100 km y, como sale más barato, pasa a viajar 16.000 km. ¿Cuántos litros de nafta ahorra de verdad por año?","unidad":"litros","decimales":0},"solucion":{"valor":160,"tolerancia":3.2,"explicacion":"Antes: 10.000 × 8 ÷ 100 = 800 L. Ahora: 16.000 × 4 ÷ 100 = 640 L. Ahorra 160 L, en vez de los 400 L que ahorraría sin viajar más: eso es el efecto rebote."}},{"slug":"digital-2.s5.p14","orden":14,"grupo":"digital-2.s5.p14","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión y marcá lo cuestionable.","segmentos":[{"id":"s1","texto":"Los satélites ayudan a detectar desmontes."},{"id":"s2","texto":"Como pronto habrá máquinas que capturen el CO₂, no hace falta reducir emisiones."},{"id":"s3","texto":"Los medidores inteligentes ayudan a ver el consumo."},{"id":"s4","texto":"Si algo es más eficiente, el ahorro está garantizado aunque lo usemos más."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Aprovechar la tecnología sin delegarle todo.","por_opcion":{"s2":"Es tecnosolucionismo: esas tecnologías son caras, limitadas y no reemplazan dejar de emitir.","s4":"El efecto rebote puede comerse parte del ahorro."}}},{"slug":"digital-2.s5.p15","orden":15,"grupo":"digital-2.s5.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando la eficiencia hace que se use más y se pierde parte del ahorro, es el efecto {{0}}; creer que todo se resuelve con un invento es {{1}}.","banco":[{"id":"w1","texto":"rebote"},{"id":"w2","texto":"tecnosolucionismo"},{"id":"w3","texto":"invernadero"},{"id":"w4","texto":"reciclaje"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos límites de la tecnología que conviene recordar."}}]},{"slug":"digital-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: tecnología que ayuda","bajada_es":"Satélites, sensores, ciencia ciudadana, energía inteligente y límites, mezclados.","minutos":8,"pasos":[{"slug":"digital-2.s6.p1","orden":1,"grupo":"digital-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Tecnología que ayuda». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"digital-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el sistema de alerta de incendios","bajada_es":"Un municipio junto a un humedal quiere un sistema para detectar incendios y avisar a los vecinos. Armalo con criterio.","minutos":10,"pasos":[{"slug":"digital-2.s7.p1","orden":1,"grupo":"digital-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El municipio","cuerpo":["El municipio tiene 40.000 hectáreas de humedales donde cada año hay quemas e incendios. La mitad de los vecinos de las islas no tiene buena conexión a internet. Una empresa ofrece una app \"que resuelve todo\", con cámaras propias, por un precio alto.","Hay datos satelitales gratuitos de focos de calor, una brigada de bomberos voluntarios y radios comunitarias en la zona."]},"solucion":{}},{"slug":"digital-2.s7.p2","orden":2,"grupo":"digital-2.s7.p2","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué herramientas conviene combinar en el sistema? Marcá todas.","opciones":[{"id":"o1","texto":"Datos satelitales gratuitos de focos de calor"},{"id":"o2","texto":"La brigada de bomberos voluntarios"},{"id":"o3","texto":"Avisos por radio comunitaria"},{"id":"o4","texto":"Mensajes de texto a los vecinos"},{"id":"o5","texto":"Solo la app de la empresa, sin nada más"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un buen sistema combina detección, respuesta y comunicación que llegue a todos."}},{"slug":"digital-2.s7.p3","orden":3,"grupo":"digital-2.s7.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué problema tiene depender solo de la app de la empresa?","opciones":[{"id":"o1","texto":"Deja afuera a la mitad de los vecinos sin buena conexión"},{"id":"o2","texto":"Las apps nunca funcionan"},{"id":"o3","texto":"Que sea cara es el único problema"},{"id":"o4","texto":"Los incendios no se pueden detectar con cámaras"}]},"solucion":{"clave":["o1"],"explicacion":"Si la alerta no llega, no sirve. La brecha digital tiene consecuencias concretas.","por_opcion":{"o3":"El costo importa, pero el problema principal es que las alertas no llegarían a muchos vecinos."}}},{"slug":"digital-2.s7.p4","orden":4,"grupo":"digital-2.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el municipio tiene 40.000 hectáreas de humedal y un satélite detecta focos en un área que se quemó en un 5 %, ¿cuántas hectáreas se quemaron?","unidad":"hectáreas","decimales":0,"contexto":"40.000 ha de humedal; 5 % quemado."},"solucion":{"valor":2000,"tolerancia":40,"explicacion":"40.000 × 5 ÷ 100 = 2.000 hectáreas, casi 2.900 canchas de fútbol."}},{"slug":"digital-2.s7.p5","orden":5,"grupo":"digital-2.s7.p5","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená cómo debería funcionar el sistema ante un foco.","items":[{"id":"i1","texto":"El satélite detecta un foco de calor"},{"id":"i2","texto":"Un operador lo verifica en el mapa"},{"id":"i3","texto":"Se avisa a la brigada"},{"id":"i4","texto":"Se alerta a los vecinos por radio y mensajes de texto"},{"id":"i5","texto":"La brigada actúa y se registra lo ocurrido"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Detectar, verificar, responder, avisar y aprender."}},{"slug":"digital-2.s7.p6","orden":6,"grupo":"digital-2.s7.p6","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas del concejo.","grupos":[{"id":"g1","nombre":"Equilibrada"},{"id":"g2","nombre":"Tecnosolucionista o excluyente"}],"items":[{"id":"i1","texto":"Usar datos satelitales gratuitos y fortalecer la brigada"},{"id":"i2","texto":"Comprar la app y cerrar la radio"},{"id":"i3","texto":"Capacitar a referentes de cada isla para difundir alertas"},{"id":"i4","texto":"Esperar un satélite propio antes de hacer nada"},{"id":"i5","texto":"Publicar los datos de incendios para que cualquiera los analice"},{"id":"i6","texto":"Avisar solo por redes sociales"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Tecnología útil, personas preparadas y comunicación para todos."}},{"slug":"digital-2.s7.p7","orden":7,"grupo":"digital-2.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Con un buen sistema satelital, ya no hace falta la brigada de bomberos.","razones":[{"id":"r1","texto":"Porque detectar no es apagar: hace falta la brigada"},{"id":"r2","texto":"Porque los satélites apagan los incendios"},{"id":"r3","texto":"Porque los incendios se apagan solos si se detectan"}]},"solucion":{"valor":false,"explicacion":"El satélite detecta; la brigada apaga. La tecnología complementa el trabajo en el terreno, no lo reemplaza.","clave":["r1"]}},{"slug":"digital-2.s7.p8","orden":8,"grupo":"digital-2.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El municipio publica su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Usaremos datos satelitales gratuitos de focos de calor."},{"id":"s2","texto":"Las alertas saldrán solo por la app, porque es lo más moderno."},{"id":"s3","texto":"Fortaleceremos a la brigada de bomberos voluntarios."},{"id":"s4","texto":"Como tenemos tecnología, no hace falta controlar las quemas intencionales."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La tecnología potencia, pero no reemplaza a las personas, las reglas y la prevención.","por_opcion":{"s2":"La mitad de los vecinos no tiene buena conexión: hace falta radio y mensajes de texto.","s4":"Detectar no evita: hay que prevenir y controlar las quemas."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"digital-3","rama":"digital","orden":3,"nivel":2,"titulo_es":"Centros de datos e inteligencia artificial","bajada_es":"Servidores, refrigeración, agua y la energía de la IA: qué pasa detrás de cada consulta, qué números son reales y qué se puede exigir a quienes construyen la nube.","objetivos_es":["Describir las partes de un centro de datos y calcular su PUE","Explicar cómo se enfrían los centros de datos y por qué importa dónde se construyen","Dimensionar la energía de la IA con datos recientes y sin exageraciones","Analizar la carrera entre mejoras de eficiencia y crecimiento de la demanda","Proponer exigencias de transparencia y buenas prácticas para la infraestructura digital"],"repasa":["digital-1","digital-2","energia-3","ciencia-3"],"requiere_tronco":2,"fuentes":["iea-energia-ia","iea-datacenters","uptime-2024","google-ia-2025","carbon-brief","iea-streaming"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"digital-3.s1","orden":1,"tipo":"leccion","titulo_es":"Dentro de un centro de datos","bajada_es":"Servidores, almacenamiento, redes, refrigeración y respaldo, y el número que mide cuánta energía se pierde en el camino.","minutos":11,"pasos":[{"slug":"digital-3.s1.p1","orden":1,"grupo":"digital-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué hay adentro","cuerpo":["Un centro de datos es un edificio con miles de servidores (computadoras que funcionan todo el día), sistemas de almacenamiento y equipos de red. Pero no toda la electricidad va a las computadoras: una parte se usa para enfriarlas, para los sistemas de respaldo que evitan cortes, para convertir la energía eléctrica y para la iluminación y los edificios."]},"solucion":{}},{"slug":"digital-3.s1.p2","orden":2,"grupo":"digital-3.s1.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta parte de un centro de datos es equipo informático o infraestructura de apoyo?","grupos":[{"id":"g1","nombre":"Equipo informático"},{"id":"g2","nombre":"Infraestructura de apoyo"}],"items":[{"id":"i1","texto":"Servidores que procesan datos"},{"id":"i2","texto":"Equipos de refrigeración"},{"id":"i3","texto":"Discos de almacenamiento"},{"id":"i4","texto":"Baterías y generadores de respaldo"},{"id":"i5","texto":"Equipos de red que conectan los servidores"},{"id":"i6","texto":"Iluminación del edificio"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Toda la energía de apoyo es necesaria, pero cuanto menos haga falta, más eficiente es el centro de datos."}},{"slug":"digital-3.s1.p3","orden":3,"grupo":"digital-3.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El PUE","cuerpo":["Para medir la eficiencia de la instalación se usa el PUE (por sus siglas en inglés, efectividad en el uso de la energía): la energía total del centro de datos dividida por la energía que usan los equipos informáticos. Un PUE de 1 sería perfecto: toda la energía iría a las computadoras. Según la encuesta 2024 del Uptime Institute, el promedio de la industria es de 1,56 y lleva cinco años sin mejorar, aunque muchos centros nuevos logran 1,3 o menos."],"destacado":{"valor":"1,56","texto":"es el PUE promedio de los centros de datos según la encuesta 2024 del Uptime Institute: por cada kWh de cómputo, 0,56 kWh extra."}},"solucion":{}},{"slug":"digital-3.s1.p4","orden":4,"grupo":"digital-3.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de datos consume 15 MW en total y sus equipos informáticos 10 MW. ¿Cuál es su PUE? Redondeá a dos decimales.","unidad":"","decimales":2,"contexto":"Consumo total 15 MW; equipos informáticos 10 MW."},"solucion":{"valor":1.5,"tolerancia":0.01,"explicacion":"PUE = 15 ÷ 10 = 1,5. Cuanto más cerca de 1, menos energía se va en refrigeración y apoyo."}},{"slug":"digital-3.s1.p4.v2","orden":4,"grupo":"digital-3.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de datos consume 13 MW en total y sus equipos informáticos 10 MW. ¿Cuál es su PUE? Redondeá a dos decimales.","unidad":"","decimales":2,"contexto":"Consumo total 13 MW; equipos informáticos 10 MW."},"solucion":{"valor":1.3,"tolerancia":0.01,"explicacion":"PUE = 13 ÷ 10 = 1,3. Cuanto más cerca de 1, menos energía se va en refrigeración y apoyo."}},{"slug":"digital-3.s1.p4.v3","orden":4,"grupo":"digital-3.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de datos consume 24 MW en total y sus equipos informáticos 20 MW. ¿Cuál es su PUE? Redondeá a dos decimales.","unidad":"","decimales":2,"contexto":"Consumo total 24 MW; equipos informáticos 20 MW."},"solucion":{"valor":1.2,"tolerancia":0.01,"explicacion":"PUE = 24 ÷ 20 = 1,2. Cuanto más cerca de 1, menos energía se va en refrigeración y apoyo."}},{"slug":"digital-3.s1.p5","orden":5,"grupo":"digital-3.s1.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los servidores de un centro de datos usan 10 MW y su PUE es 1,5. ¿Cuántos MW se usan en refrigeración y apoyo? Redondeá a un decimal.","unidad":"MW","decimales":1,"contexto":"Equipos 10 MW; PUE 1.5."},"solucion":{"valor":5,"tolerancia":0.1,"explicacion":"Total: 10 × 1,5 = 15 MW. Apoyo: 15 − 10 = 5 MW."}},{"slug":"digital-3.s1.p5.v2","orden":5,"grupo":"digital-3.s1.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los servidores de un centro de datos usan 8 MW y su PUE es 1,6. ¿Cuántos MW se usan en refrigeración y apoyo? Redondeá a un decimal.","unidad":"MW","decimales":1,"contexto":"Equipos 8 MW; PUE 1.6."},"solucion":{"valor":4.8,"tolerancia":0.1,"explicacion":"Total: 8 × 1,6 = 12,8 MW. Apoyo: 12,8 − 8 = 4,8 MW."}},{"slug":"digital-3.s1.p5.v3","orden":5,"grupo":"digital-3.s1.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los servidores de un centro de datos usan 20 MW y su PUE es 1,2. ¿Cuántos MW se usan en refrigeración y apoyo? Redondeá a un decimal.","unidad":"MW","decimales":1,"contexto":"Equipos 20 MW; PUE 1.2."},"solucion":{"valor":4,"tolerancia":0.1,"explicacion":"Total: 20 × 1,2 = 24 MW. Apoyo: 24 − 20 = 4 MW."}},{"slug":"digital-3.s1.p6","orden":6,"grupo":"digital-3.s1.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un centro de datos tiene un PUE de 1,1 y otro de 1,8. ¿Qué significa?","opciones":[{"id":"o1","texto":"El primero pierde mucha menos energía en apoyo"},{"id":"o2","texto":"El segundo tiene computadoras más potentes"},{"id":"o3","texto":"El primero consume menos energía en total, seguro"},{"id":"o4","texto":"Los dos son igual de eficientes"}]},"solucion":{"clave":["o1"],"explicacion":"El PUE no dice cuánto consume un centro de datos, sino qué parte se va en cosas que no son cómputo.","por_opcion":{"o3":"Depende de cuántos servidores tenga: el PUE mide eficiencia, no tamaño."}}},{"slug":"digital-3.s1.p7","orden":7,"grupo":"digital-3.s1.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un PUE bajo significa que un centro de datos consume poca energía.","razones":[{"id":"r1","texto":"Porque el PUE mide proporción, no consumo total"},{"id":"r2","texto":"Porque el PUE mide la velocidad de internet"},{"id":"r3","texto":"Porque un PUE bajo es siempre malo"}]},"solucion":{"valor":false,"explicacion":"El PUE mide la proporción de energía que se va en apoyo, no el consumo total. Un centro enorme con PUE excelente puede consumir muchísimo.","clave":["r1"]}},{"slug":"digital-3.s1.p8","orden":8,"grupo":"digital-3.s1.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo el día, todo el año","cuerpo":["Los centros de datos funcionan las 24 horas, los 365 días. Un equipo de 10 MW que funciona un año entero consume 10 × 8.760 horas = 87.600 MWh, más lo que agregue su PUE. Por eso incluso mejoras pequeñas de eficiencia, multiplicadas por todas las horas del año, representan mucha energía."]},"solucion":{}},{"slug":"digital-3.s1.p9","orden":9,"grupo":"digital-3.s1.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los servidores de un centro de datos usan 10 MW todo el año (8.760 horas) y su PUE es 1,5. ¿Cuántos MWh consume en total por año?","unidad":"MWh","decimales":0,"contexto":"10 MW; 8.760 horas; PUE 1.5."},"solucion":{"valor":131400,"tolerancia":1,"explicacion":"10 × 8.760 × 1,5 = 131.400 MWh por año. Un hogar argentino típico usa del orden de 3 MWh por año."}},{"slug":"digital-3.s1.p9.v2","orden":9,"grupo":"digital-3.s1.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los servidores de un centro de datos usan 5 MW todo el año (8.760 horas) y su PUE es 1,3. ¿Cuántos MWh consume en total por año?","unidad":"MWh","decimales":0,"contexto":"5 MW; 8.760 horas; PUE 1.3."},"solucion":{"valor":56940,"tolerancia":1,"explicacion":"5 × 8.760 × 1,3 = 56.940 MWh por año. Un hogar argentino típico usa del orden de 3 MWh por año."}},{"slug":"digital-3.s1.p9.v3","orden":9,"grupo":"digital-3.s1.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los servidores de un centro de datos usan 20 MW todo el año (8.760 horas) y su PUE es 1,4. ¿Cuántos MWh consume en total por año?","unidad":"MWh","decimales":0,"contexto":"20 MW; 8.760 horas; PUE 1.4."},"solucion":{"valor":245280,"tolerancia":1,"explicacion":"20 × 8.760 × 1,4 = 245.280 MWh por año. Un hogar argentino típico usa del orden de 3 MWh por año."}},{"slug":"digital-3.s1.p10","orden":10,"grupo":"digital-3.s1.p10","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de la energía en un centro de datos.","items":[{"id":"i1","texto":"La electricidad llega de la red"},{"id":"i2","texto":"Se convierte y pasa por sistemas de respaldo"},{"id":"i3","texto":"Alimenta a los servidores que procesan datos"},{"id":"i4","texto":"Los servidores la transforman en calor"},{"id":"i5","texto":"La refrigeración usa más energía para sacar ese calor"},{"id":"i6","texto":"Los servidores convierten el calor en electricidad de nuevo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Toda la energía que usan las computadoras termina como calor que hay que sacar."}},{"slug":"digital-3.s1.p11","orden":11,"grupo":"digital-3.s1.p11","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos centros de datos del más eficiente al menos eficiente, según su PUE.","items":[{"id":"i1","texto":"Centro nuevo en clima frío"},{"id":"i2","texto":"Centro nuevo típico"},{"id":"i3","texto":"Promedio de la industria"},{"id":"i4","texto":"Sala de servidores vieja en una oficina"}],"extremos":["Más eficiente","Menos eficiente"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un PUE de 2 significa que por cada kWh de cómputo se gasta otro kWh en apoyo.","valores":{"i1":"PUE 1,1","i2":"PUE 1,3","i3":"PUE 1,56","i4":"PUE 2,0"}}},{"slug":"digital-3.s1.p12","orden":12,"grupo":"digital-3.s1.p12","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada término con su definición.","izquierda":[{"id":"a1","texto":"Servidor"},{"id":"a2","texto":"PUE"},{"id":"a3","texto":"Respaldo"},{"id":"a4","texto":"Refrigeración"}],"derecha":[{"id":"b1","texto":"Computadora que funciona todo el día"},{"id":"b2","texto":"Energía total dividida por la de los equipos"},{"id":"b3","texto":"Baterías y generadores que evitan cortes"},{"id":"b4","texto":"Saca el calor que generan los equipos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Vocabulario básico para hablar de centros de datos."}},{"slug":"digital-3.s1.p13","orden":13,"grupo":"digital-3.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe de una empresa y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Nuestro PUE es de 1,2, mejor que el promedio de la industria."},{"id":"s2","texto":"Con PUE 1,2, toda nuestra energía va a los servidores."},{"id":"s3","texto":"Los servidores funcionan las 24 horas."},{"id":"s4","texto":"Como nuestro PUE es bajo, nuestro consumo total es bajo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un número bien entendido evita conclusiones equivocadas.","por_opcion":{"s2":"Un 20 % extra va a refrigeración y apoyo.","s4":"El PUE no dice nada del consumo total."}}},{"slug":"digital-3.s1.p14","orden":14,"grupo":"digital-3.s1.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El número que compara la energía total con la de los equipos es el {{0}}; el promedio de la industria es de {{1}}; y toda la energía de los servidores termina como {{2}}.","banco":[{"id":"w1","texto":"PUE"},{"id":"w2","texto":"1,56"},{"id":"w3","texto":"calor"},{"id":"w4","texto":"IVA"},{"id":"w5","texto":"0,56"},{"id":"w6","texto":"luz"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para medir la eficiencia de un centro de datos."}}]},{"slug":"digital-3.s2","orden":2,"tipo":"leccion","titulo_es":"Agua, clima y lugar","bajada_es":"Cómo se enfrían los centros de datos, cuánta agua usan y por qué importa tanto dónde se construyen.","minutos":12,"pasos":[{"slug":"digital-3.s2.p1","orden":1,"grupo":"digital-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Enfriar","cuerpo":["Hay varias formas de sacar el calor. Con aire acondicionado, que usa mucha electricidad. Con enfriamiento evaporativo, que evapora agua para enfriar el aire: usa menos electricidad, pero consume agua. Con líquido que circula cerca de los chips, más eficiente para equipos muy potentes. Y, en climas fríos, con aire exterior la mayor parte del año, casi sin gasto extra.","Hay un intercambio: ahorrar electricidad puede costar agua, y ahorrar agua puede costar electricidad. Qué conviene depende del lugar."]},"solucion":{}},{"slug":"digital-3.s2.p2","orden":2,"grupo":"digital-3.s2.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada forma de enfriar con su característica.","izquierda":[{"id":"a1","texto":"Aire acondicionado"},{"id":"a2","texto":"Enfriamiento evaporativo"},{"id":"a3","texto":"Refrigeración líquida"},{"id":"a4","texto":"Aire exterior en climas fríos"}],"derecha":[{"id":"b1","texto":"Usa mucha electricidad"},{"id":"b2","texto":"Ahorra electricidad pero consume agua"},{"id":"b3","texto":"Eficiente para chips muy potentes"},{"id":"b4","texto":"Enfría casi sin gasto extra"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada método tiene su costo; ninguno es gratis en todos los lugares."}},{"slug":"digital-3.s2.p3","orden":3,"grupo":"digital-3.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El agua","cuerpo":["Un centro de datos usa agua de dos formas: directamente, para enfriar, y de forma indirecta, en las centrales que generan su electricidad (las térmicas usan agua para enfriarse). En zonas con sequía o poca agua, un centro de datos grande puede competir con el consumo de la población y del riego. Por eso importa medir y publicar cuánta agua usa, en litros por kWh, y de qué fuente la toma."]},"solucion":{}},{"slug":"digital-3.s2.p4","orden":4,"grupo":"digital-3.s2.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Uso de agua directo o indirecto?","grupos":[{"id":"g1","nombre":"Directo"},{"id":"g2","nombre":"Indirecto"}],"items":[{"id":"i1","texto":"Agua evaporada en las torres de enfriamiento"},{"id":"i2","texto":"Agua que usa la central térmica que genera su electricidad"},{"id":"i3","texto":"Agua para humidificar el aire de las salas"},{"id":"i4","texto":"Agua usada para fabricar sus chips"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Mirar solo el agua directa esconde una parte de la huella hídrica."}},{"slug":"digital-3.s2.p5","orden":5,"grupo":"digital-3.s2.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de un conflicto por el agua.","items":[{"id":"i1","texto":"Se instala un centro de datos grande en una zona seca"},{"id":"i2","texto":"Usa enfriamiento evaporativo en verano"},{"id":"i3","texto":"Su consumo de agua es máximo cuando hace más calor"},{"id":"i4","texto":"Coincide con el pico de consumo de la población y del riego"},{"id":"i5","texto":"Crece la tensión por el agua disponible"},{"id":"i6","texto":"En verano el centro de datos usa menos agua"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Lo viste con la huella hídrica: no es lo mismo un litro en una cuenca con agua que en una con sequía."}},{"slug":"digital-3.s2.p6","orden":6,"grupo":"digital-3.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dónde y cuándo","cuerpo":["La huella de un centro de datos depende mucho de dónde está. En un lugar frío puede enfriar con aire exterior; con una red eléctrica con muchas renovables, emite menos por cada kWh; con agua abundante, el enfriamiento evaporativo genera menos tensión. Además, algunas tareas que no son urgentes, como entrenar modelos o procesar copias de seguridad, pueden programarse para las horas en que hay más energía renovable disponible."]},"solucion":{}},{"slug":"digital-3.s2.p7","orden":7,"grupo":"digital-3.s2.p7","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más adecuado un lugar para un centro de datos? Marcá todo.","opciones":[{"id":"o1","texto":"Clima fresco que permita enfriar con aire exterior"},{"id":"o2","texto":"Red eléctrica con muchas renovables"},{"id":"o3","texto":"Agua disponible sin competir con la población"},{"id":"o4","texto":"Una zona con sequía crónica"},{"id":"o5","texto":"Una red eléctrica basada en carbón"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El mismo centro de datos puede tener una huella muy distinta según el lugar."}},{"slug":"digital-3.s2.p8","orden":8,"grupo":"digital-3.s2.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de datos consume 100.000 MWh por año. En una región la red emite 0,1 t de CO₂ por MWh y en otra 0,5. ¿Cuántas toneladas de CO₂ por año se evitan en la región más limpia?","unidad":"t de CO₂","decimales":0,"contexto":"100000 MWh por año; redes de 0.1 y 0.5 t/MWh."},"solucion":{"valor":40000,"tolerancia":1,"explicacion":"100.000 × (0,5 − 0,1) = 40.000 toneladas por año. La ubicación puede pesar más que muchas mejoras técnicas."}},{"slug":"digital-3.s2.p8.v2","orden":8,"grupo":"digital-3.s2.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de datos consume 50.000 MWh por año. En una región la red emite 0,05 t de CO₂ por MWh y en otra 0,4. ¿Cuántas toneladas de CO₂ por año se evitan en la región más limpia?","unidad":"t de CO₂","decimales":0,"contexto":"50000 MWh por año; redes de 0.05 y 0.4 t/MWh."},"solucion":{"valor":17500,"tolerancia":1,"explicacion":"50.000 × (0,4 − 0,05) = 17.500 toneladas por año. La ubicación puede pesar más que muchas mejoras técnicas."}},{"slug":"digital-3.s2.p8.v3","orden":8,"grupo":"digital-3.s2.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de datos consume 80.000 MWh por año. En una región la red emite 0,15 t de CO₂ por MWh y en otra 0,6. ¿Cuántas toneladas de CO₂ por año se evitan en la región más limpia?","unidad":"t de CO₂","decimales":0,"contexto":"80000 MWh por año; redes de 0.15 y 0.6 t/MWh."},"solucion":{"valor":36000,"tolerancia":1,"explicacion":"80.000 × (0,6 − 0,15) = 36.000 toneladas por año. La ubicación puede pesar más que muchas mejoras técnicas."}},{"slug":"digital-3.s2.p9","orden":9,"grupo":"digital-3.s2.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El calor que sobra","cuerpo":["Todo el calor que sacan los centros de datos se puede aprovechar en lugar de tirarlo al aire. En algunos países del norte de Europa, ese calor se usa para calentar agua y viviendas a través de redes de calefacción urbana. Aprovechar el calor residual convierte un desperdicio en un recurso."]},"solucion":{}},{"slug":"digital-3.s2.p10","orden":10,"grupo":"digital-3.s2.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El calor que producen los centros de datos no tiene ningún uso posible.","razones":[{"id":"r1","texto":"Porque puede usarse para calefacción u otros procesos"},{"id":"r2","texto":"Porque los servidores no producen calor"},{"id":"r3","texto":"Porque el calor residual es tóxico"}]},"solucion":{"valor":false,"explicacion":"Puede aprovecharse para calefacción de viviendas o procesos industriales, como ya se hace en algunas ciudades del norte de Europa.","clave":["r1"]}},{"slug":"digital-3.s2.p11","orden":11,"grupo":"digital-3.s2.p11","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Enfriar con agua evaporada siempre es peor que enfriar con aire acondicionado.","razones":[{"id":"r1","texto":"Porque el balance entre agua y electricidad depende del lugar"},{"id":"r2","texto":"Porque el aire acondicionado no usa electricidad"},{"id":"r3","texto":"Porque el enfriamiento evaporativo no usa agua"}]},"solucion":{"valor":false,"explicacion":"Depende del lugar: el evaporativo ahorra electricidad, lo que puede ser mejor donde sobra agua; donde el agua escasea, conviene otra opción.","clave":["r1"]}},{"slug":"digital-3.s2.p12","orden":12,"grupo":"digital-3.s2.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué tareas de un centro de datos se pueden mover a las horas con más energía renovable?","opciones":[{"id":"o1","texto":"Entrenar modelos o hacer copias de seguridad"},{"id":"o2","texto":"Responder una videollamada en vivo"},{"id":"o3","texto":"Procesar un pago con tarjeta en el momento"},{"id":"o4","texto":"Cargar una página web que alguien pidió"}]},"solucion":{"clave":["o1"],"explicacion":"Las tareas que no necesitan respuesta inmediata pueden esperar al momento más limpio.","por_opcion":{"o3":"Un pago necesita respuesta inmediata: no puede esperar."}}},{"slug":"digital-3.s2.p13","orden":13,"grupo":"digital-3.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta propuesta de una empresa y marcá lo que preocupa.","segmentos":[{"id":"s1","texto":"Usaremos aire exterior para enfriar la mayor parte del año."},{"id":"s2","texto":"Tomaremos agua subterránea de una cuenca en sequía sin publicar cuánta."},{"id":"s3","texto":"Contrataremos energía renovable para cubrir nuestro consumo."},{"id":"s4","texto":"El calor sobrante lo tiraremos al aire aunque haya un barrio que necesita calefacción."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un centro de datos responsable elige bien el lugar, cuida el agua y aprovecha su calor.","por_opcion":{"s2":"Compite con la población y no es transparente.","s4":"Se desperdicia un recurso que podría aprovecharse."}}},{"slug":"digital-3.s2.p14","orden":14,"grupo":"digital-3.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Enfriar evaporando agua ahorra {{0}} pero consume agua; en climas fríos se puede enfriar con aire {{1}}; y el calor que sobra se puede usar para {{2}}.","banco":[{"id":"w1","texto":"electricidad"},{"id":"w2","texto":"exterior"},{"id":"w3","texto":"calefacción"},{"id":"w4","texto":"dinero"},{"id":"w5","texto":"caliente"},{"id":"w6","texto":"iluminación"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para pensar el agua y el lugar de un centro de datos."}},{"slug":"digital-3.s2.p15","orden":15,"grupo":"digital-3.s2.p15","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos lugares del más al menos adecuado para un nuevo centro de datos grande.","items":[{"id":"i1","texto":"Clima frío, red renovable y agua abundante"},{"id":"i2","texto":"Clima templado, red renovable y agua suficiente"},{"id":"i3","texto":"Clima cálido, red con gas y agua escasa"},{"id":"i4","texto":"Clima caluroso, red a carbón y sequía crónica"}],"extremos":["Más adecuado","Menos adecuado"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Clima, energía y agua se combinan: el lugar define gran parte de la huella.","valores":{"i1":"ideal","i2":"bueno","i3":"problemático","i4":"el peor"}}}]},{"slug":"digital-3.s3","orden":3,"tipo":"leccion","titulo_es":"La energía de la IA","bajada_es":"Entrenar y usar modelos, cuánto consume una consulta y cuánto crece la demanda de los centros de datos.","minutos":11,"pasos":[{"slug":"digital-3.s3.p1","orden":1,"grupo":"digital-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Entrenar y usar","cuerpo":["Un modelo de inteligencia artificial tiene dos etapas que consumen energía. El entrenamiento, en el que el modelo aprende a partir de enormes cantidades de datos, usa miles de chips especializados durante semanas o meses. La inferencia es el uso: cada vez que alguien hace una consulta, el modelo calcula una respuesta. Una consulta consume poco, pero con miles de millones de consultas por día, el uso puede superar al entrenamiento."]},"solucion":{}},{"slug":"digital-3.s3.p2","orden":2,"grupo":"digital-3.s3.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es entrenamiento o inferencia?","grupos":[{"id":"g1","nombre":"Entrenamiento"},{"id":"g2","nombre":"Inferencia"}],"items":[{"id":"i1","texto":"El modelo aprende de grandes cantidades de datos durante semanas"},{"id":"i2","texto":"Alguien le pide un resumen a un asistente"},{"id":"i3","texto":"Se ajusta un modelo con nuevos ejemplos"},{"id":"i4","texto":"Una app traduce un texto al instante"},{"id":"i5","texto":"Se genera una imagen a partir de una descripción"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"El entrenamiento es un gasto grande y concentrado; la inferencia, uno chico multiplicado por millones de usos."}},{"slug":"digital-3.s3.p3","orden":3,"grupo":"digital-3.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto gasta una consulta","cuerpo":["Durante años circularon estimaciones muy distintas. En 2025, Google publicó mediciones de su propio servicio: la consulta de texto mediana a su asistente de IA usó 0,24 Wh de energía y 0,26 mililitros de agua, y ese consumo había bajado 33 veces en un año gracias a mejoras de software y hardware. Otras estimaciones independientes para consultas de texto dan valores del mismo orden o algo mayores; generar imágenes o video usa bastante más.","Para comparar: 0,24 Wh es lo que usa una lámpara LED de 10 W prendida algo menos de un minuto y medio."],"destacado":{"valor":"0,24 Wh","texto":"usó la consulta de texto mediana al asistente de IA de Google en 2025, según sus propias mediciones."}},"solucion":{}},{"slug":"digital-3.s3.p4","orden":4,"grupo":"digital-3.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una consulta de IA usa 0,24 Wh, ¿cuántos segundos puede estar prendida una lámpara LED de 10 W con esa energía? Redondeá al entero.","unidad":"segundos","decimales":0,"contexto":"0,24 Wh por consulta; lámpara de 10 W."},"solucion":{"valor":86,"tolerancia":1,"explicacion":"0,24 Wh ÷ 10 W = 0,024 horas × 3.600 ≈ 86 segundos. Una consulta de texto, sola, usa poca energía."}},{"slug":"digital-3.s3.p4.v2","orden":4,"grupo":"digital-3.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una consulta de IA usa 0,24 Wh, ¿cuántos segundos puede estar prendida una lámpara LED de 8 W con esa energía? Redondeá al entero.","unidad":"segundos","decimales":0,"contexto":"0,24 Wh por consulta; lámpara de 8 W."},"solucion":{"valor":108,"tolerancia":1,"explicacion":"0,24 Wh ÷ 8 W = 0,03 horas × 3.600 ≈ 108 segundos. Una consulta de texto, sola, usa poca energía."}},{"slug":"digital-3.s3.p4.v3","orden":4,"grupo":"digital-3.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una consulta de IA usa 0,24 Wh, ¿cuántos segundos puede estar prendida una lámpara LED de 12 W con esa energía? Redondeá al entero.","unidad":"segundos","decimales":0,"contexto":"0,24 Wh por consulta; lámpara de 12 W."},"solucion":{"valor":72,"tolerancia":1,"explicacion":"0,24 Wh ÷ 12 W = 0,02 horas × 3.600 ≈ 72 segundos. Una consulta de texto, sola, usa poca energía."}},{"slug":"digital-3.s3.p5","orden":5,"grupo":"digital-3.s3.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se hacen 1.000 millones de consultas de texto por día y cada una usa 0,24 Wh, ¿cuántos MWh por día son? (1 MWh = 1.000.000 Wh)","unidad":"MWh por día","decimales":0,"contexto":"1000 millones de consultas; 0,24 Wh cada una."},"solucion":{"valor":240,"tolerancia":1,"explicacion":"1.000 millones × 0,24 Wh = 240 millones de Wh = 240 MWh por día. Poco por consulta; mucho sumado."}},{"slug":"digital-3.s3.p5.v2","orden":5,"grupo":"digital-3.s3.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se hacen 500 millones de consultas de texto por día y cada una usa 0,24 Wh, ¿cuántos MWh por día son? (1 MWh = 1.000.000 Wh)","unidad":"MWh por día","decimales":0,"contexto":"500 millones de consultas; 0,24 Wh cada una."},"solucion":{"valor":120,"tolerancia":1,"explicacion":"500 millones × 0,24 Wh = 120 millones de Wh = 120 MWh por día. Poco por consulta; mucho sumado."}},{"slug":"digital-3.s3.p5.v3","orden":5,"grupo":"digital-3.s3.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se hacen 2.000 millones de consultas de texto por día y cada una usa 0,24 Wh, ¿cuántos MWh por día son? (1 MWh = 1.000.000 Wh)","unidad":"MWh por día","decimales":0,"contexto":"2000 millones de consultas; 0,24 Wh cada una."},"solucion":{"valor":480,"tolerancia":1,"explicacion":"2.000 millones × 0,24 Wh = 480 millones de Wh = 480 MWh por día. Poco por consulta; mucho sumado."}},{"slug":"digital-3.s3.p6","orden":6,"grupo":"digital-3.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La demanda crece","cuerpo":["Según la Agencia Internacional de Energía, en 2024 los centros de datos consumieron unos 415 TWh, alrededor del 1,5 % de la electricidad mundial. Estados Unidos concentró el 45 %, China el 25 % y Europa el 15 %. Con la expansión de la IA, la agencia proyecta que el consumo se duplique hasta unos 950 TWh en 2030, algo menos del 3 % de la electricidad mundial. A escala global es una parte chica, pero en algunas regiones, donde se concentran los centros de datos, el impacto sobre la red es grande."],"datos":{"tipo":"barras","titulo":"Consumo de electricidad de los centros de datos (AIE)","unidad":"TWh","filas":[{"etiqueta":"2024","valor":415},{"etiqueta":"2030 (proyección)","valor":950}],"nota":"Agencia Internacional de Energía, Energy and AI (2025)."}},"solucion":{}},{"slug":"digital-3.s3.p7","orden":7,"grupo":"digital-3.s3.p7","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las regiones según su participación en el consumo de los centros de datos en 2024, de mayor a menor.","items":[{"id":"i1","texto":"Estados Unidos"},{"id":"i2","texto":"China"},{"id":"i3","texto":"Europa"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"El consumo está muy concentrado: el impacto local puede ser grande aunque el global sea chico.","valores":{"i1":"≈ 45 %","i2":"≈ 25 %","i3":"≈ 15 %"}}},{"slug":"digital-3.s3.p8","orden":8,"grupo":"digital-3.s3.p8","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la electricidad mundial consumieron los centros de datos en 2024, según la AIE.","min":0,"max":30,"paso":0.5,"unidad":"%","escala":"lineal"},"solucion":{"valor":1.5,"banda":"lineal","explicacion":"Alrededor del 1,5 %: unos 415 TWh. Podría llegar a algo menos del 3 % en 2030."}},{"slug":"digital-3.s3.p9","orden":9,"grupo":"digital-3.s3.p9","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como una consulta de texto a una IA gasta poca energía, el crecimiento de la IA no tiene impacto en la red eléctrica.","razones":[{"id":"r1","texto":"Porque la escala y la concentración presionan las redes"},{"id":"r2","texto":"Porque cada consulta gasta más que una casa por año"},{"id":"r3","texto":"Porque la IA no usa electricidad"}]},"solucion":{"valor":false,"explicacion":"Una consulta gasta poco, pero la cantidad de usos, el entrenamiento y la concentración de centros de datos en ciertas regiones hacen que la demanda crezca rápido y presione redes locales.","clave":["r1"]}},{"slug":"digital-3.s3.p10","orden":10,"grupo":"digital-3.s3.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene desconfiar de un titular que dice \"cada pregunta a una IA gasta una botella de agua\"?","opciones":[{"id":"o1","texto":"Las mediciones recientes dan valores mucho menores"},{"id":"o2","texto":"Porque las IA no usan agua en ningún caso"},{"id":"o3","texto":"Porque los titulares siempre mienten"},{"id":"o4","texto":"Porque el agua de los centros de datos es de mar"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste con la desinformación: los números impactantes y viejos circulan mucho más que las mediciones cuidadosas.","por_opcion":{"o3":"No siempre; pero conviene chequear con datos recientes y la fuente."}}},{"slug":"digital-3.s3.p11","orden":11,"grupo":"digital-3.s3.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué la IA hace crecer el consumo de los centros de datos.","items":[{"id":"i1","texto":"Se entrenan modelos cada vez más grandes"},{"id":"i2","texto":"Millones de personas los usan todos los días"},{"id":"i3","texto":"Hacen falta más chips especializados y más servidores"},{"id":"i4","texto":"Se construyen más centros de datos"},{"id":"i5","texto":"Crece la demanda de electricidad en esas regiones"},{"id":"i6","texto":"Cada modelo nuevo usa menos servidores que el anterior"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El crecimiento combina modelos más grandes y muchos más usuarios."}},{"slug":"digital-3.s3.p12","orden":12,"grupo":"digital-3.s3.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada actividad con el orden de magnitud de su energía.","izquierda":[{"id":"a1","texto":"Una consulta de texto a una IA"},{"id":"a2","texto":"Generar una imagen o un video"},{"id":"a3","texto":"Entrenar un modelo grande"},{"id":"a4","texto":"Todos los centros de datos del mundo en 2024"}],"derecha":[{"id":"b1","texto":"Décimas de Wh"},{"id":"b2","texto":"Bastante más que un texto"},{"id":"b3","texto":"Enorme, concentrada en semanas"},{"id":"b4","texto":"Unos 415 TWh"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Poner cada número en su escala evita tanto exagerar como minimizar."}},{"slug":"digital-3.s3.p13","orden":13,"grupo":"digital-3.s3.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los centros de datos usaron cerca del 1,5 % de la electricidad mundial en 2024."},{"id":"s2","texto":"La IA ya consume más electricidad que todo el mundo junto."},{"id":"s3","texto":"El consumo por consulta bajó mucho gracias a mejoras de eficiencia."},{"id":"s4","texto":"Generar un video con IA gasta lo mismo que una consulta de texto."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Ni \"no pasa nada\" ni \"la IA se come el planeta\": los datos muestran un crecimiento real y concentrado.","por_opcion":{"s2":"Los centros de datos en total rondan el 1,5 %.","s4":"Generar imágenes o video usa bastante más energía."}}},{"slug":"digital-3.s3.p14","orden":14,"grupo":"digital-3.s3.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando un modelo aprende de los datos se llama {{0}}; cuando responde consultas, {{1}}; y en 2024 los centros de datos usaron unos {{2}} TWh.","banco":[{"id":"w1","texto":"entrenamiento"},{"id":"w2","texto":"inferencia"},{"id":"w3","texto":"415"},{"id":"w4","texto":"descanso"},{"id":"w5","texto":"deducción"},{"id":"w6","texto":"4.150"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para hablar de la energía de la IA con precisión."}}]},{"slug":"digital-3.s4","orden":4,"tipo":"leccion","titulo_es":"Eficiencia contra demanda","bajada_es":"Chips más eficientes, software más liviano y una demanda que crece más rápido: la carrera que define la huella de lo digital.","minutos":11,"pasos":[{"slug":"digital-3.s4.p1","orden":1,"grupo":"digital-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cada vez más eficiente","cuerpo":["La eficiencia de la computación mejoró muchísimo durante décadas: hoy se hace con un celular lo que antes requería una sala entera. En la IA, las mejoras siguen siendo rápidas: chips diseñados para estas tareas, modelos más chicos que responden casi igual de bien, y software que aprovecha mejor el hardware. Según Google, la energía por consulta mediana de su asistente bajó 33 veces en un año."]},"solucion":{}},{"slug":"digital-3.s4.p2","orden":2,"grupo":"digital-3.s4.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una consulta usaba 7,92 Wh y la eficiencia mejoró 33 veces, ¿cuántos Wh usa ahora? Redondeá a dos decimales.","unidad":"Wh","decimales":2,"contexto":"7.92 Wh por consulta; mejora de 33 veces."},"solucion":{"valor":0.24,"tolerancia":0.01,"explicacion":"7,92 ÷ 33 ≈ 0,24 Wh. Mejoras así son enormes, pero no garantizan que baje el consumo total."}},{"slug":"digital-3.s4.p2.v2","orden":2,"grupo":"digital-3.s4.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una consulta usaba 3 Wh y la eficiencia mejoró 10 veces, ¿cuántos Wh usa ahora? Redondeá a dos decimales.","unidad":"Wh","decimales":2,"contexto":"3 Wh por consulta; mejora de 10 veces."},"solucion":{"valor":0.3,"tolerancia":0.01,"explicacion":"3 ÷ 10 ≈ 0,3 Wh. Mejoras así son enormes, pero no garantizan que baje el consumo total."}},{"slug":"digital-3.s4.p2.v3","orden":2,"grupo":"digital-3.s4.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una consulta usaba 1,2 Wh y la eficiencia mejoró 5 veces, ¿cuántos Wh usa ahora? Redondeá a dos decimales.","unidad":"Wh","decimales":2,"contexto":"1.2 Wh por consulta; mejora de 5 veces."},"solucion":{"valor":0.24,"tolerancia":0.01,"explicacion":"1,2 ÷ 5 ≈ 0,24 Wh. Mejoras así son enormes, pero no garantizan que baje el consumo total."}},{"slug":"digital-3.s4.p3","orden":3,"grupo":"digital-3.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La paradoja","cuerpo":["En el siglo XIX, el economista William Stanley Jevons notó que las máquinas de vapor más eficientes no redujeron el uso de carbón: lo aumentaron, porque el vapor se volvió más barato y se usó para muchas más cosas. Es la paradoja de Jevons, una forma extrema del efecto rebote. Con la IA puede pasar algo parecido: si cada consulta cuesta menos, se usa en más productos y por más personas, y el consumo total puede crecer igual."]},"solucion":{}},{"slug":"digital-3.s4.p4","orden":4,"grupo":"digital-3.s4.p4","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la paradoja de Jevons aplicada a la IA.","items":[{"id":"i1","texto":"Cada consulta se vuelve mucho más eficiente"},{"id":"i2","texto":"Usar IA se vuelve más barato"},{"id":"i3","texto":"Se incorpora a muchos más productos y servicios"},{"id":"i4","texto":"La cantidad de consultas crece muchísimo"},{"id":"i5","texto":"El consumo total de energía puede aumentar"},{"id":"i6","texto":"La eficiencia garantiza que el consumo total baje"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La eficiencia es necesaria, pero sin límites ni prioridades, el consumo total puede crecer."}},{"slug":"digital-3.s4.p5","orden":5,"grupo":"digital-3.s4.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía por consulta baja 10 veces, pero la cantidad de consultas crece 20 veces. ¿Por cuánto se multiplica el consumo total? Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"Eficiencia 10 veces mejor; consultas 20 veces más."},"solucion":{"valor":2,"tolerancia":0.1,"explicacion":"20 ÷ 10 = 2. El consumo total crece: la demanda le ganó a la eficiencia."}},{"slug":"digital-3.s4.p5.v2","orden":5,"grupo":"digital-3.s4.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía por consulta baja 5 veces, pero la cantidad de consultas crece 8 veces. ¿Por cuánto se multiplica el consumo total? Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"Eficiencia 5 veces mejor; consultas 8 veces más."},"solucion":{"valor":1.6,"tolerancia":0.1,"explicacion":"8 ÷ 5 = 1,6. El consumo total crece: la demanda le ganó a la eficiencia."}},{"slug":"digital-3.s4.p5.v3","orden":5,"grupo":"digital-3.s4.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La energía por consulta baja 4 veces, pero la cantidad de consultas crece 3 veces. ¿Por cuánto se multiplica el consumo total? Redondeá a un decimal.","unidad":"veces","decimales":1,"contexto":"Eficiencia 4 veces mejor; consultas 3 veces más."},"solucion":{"valor":0.8,"tolerancia":0.1,"explicacion":"3 ÷ 4 = 0,8. El consumo total baja: la eficiencia le ganó a la demanda."}},{"slug":"digital-3.s4.p6","orden":6,"grupo":"digital-3.s4.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una mejora de eficiencia o un aumento de la demanda?","grupos":[{"id":"g1","nombre":"Mejora de eficiencia"},{"id":"g2","nombre":"Aumento de la demanda"}],"items":[{"id":"i1","texto":"Chips que hacen más cálculos por watt"},{"id":"i2","texto":"IA incorporada en cada buscador y aplicación"},{"id":"i3","texto":"Modelos más chicos con resultados parecidos"},{"id":"i4","texto":"Generación de video para publicidad masiva"},{"id":"i5","texto":"Mejor refrigeración que baja el PUE"},{"id":"i6","texto":"Millones de usuarios nuevos por mes"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La huella total depende de cuál de las dos fuerzas crezca más rápido."}},{"slug":"digital-3.s4.p7","orden":7,"grupo":"digital-3.s4.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si cada consulta a una IA es 10 veces más eficiente, el consumo total de la IA seguro baja.","razones":[{"id":"r1","texto":"Porque depende de cuánto crezca la cantidad de consultas"},{"id":"r2","texto":"Porque la eficiencia siempre aumenta el consumo"},{"id":"r3","texto":"Porque la cantidad de consultas nunca cambia"}]},"solucion":{"valor":false,"explicacion":"Solo baja si la cantidad de consultas crece menos de 10 veces. Si crece más, el consumo total aumenta: es el efecto rebote.","clave":["r1"]}},{"slug":"digital-3.s4.p8","orden":8,"grupo":"digital-3.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Usar lo justo","cuerpo":["Además de hacer cada cálculo más eficiente, se puede usar la herramienta adecuada para cada tarea: un modelo grande para una pregunta simple es como usar un camión para llevar una carta. Elegir modelos más chicos cuando alcanzan, evitar generar contenido que nadie pidió y no incorporar IA donde no aporta valor también reducen el consumo."]},"solucion":{}},{"slug":"digital-3.s4.p9","orden":9,"grupo":"digital-3.s4.p9","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué práctica reduce el consumo sin perder utilidad?","opciones":[{"id":"o1","texto":"Usar un modelo chico cuando la tarea es simple"},{"id":"o2","texto":"Usar siempre el modelo más grande por las dudas"},{"id":"o3","texto":"Generar diez versiones de todo aunque se use una"},{"id":"o4","texto":"Incorporar IA en cada botón de una aplicación"}]},"solucion":{"clave":["o1"],"explicacion":"La herramienta proporcionada a la tarea es una forma de suficiencia digital.","por_opcion":{"o3":"Multiplica el consumo sin agregar valor."}}},{"slug":"digital-3.s4.p10","orden":10,"grupo":"digital-3.s4.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su ejemplo.","izquierda":[{"id":"a1","texto":"Mejora de eficiencia"},{"id":"a2","texto":"Paradoja de Jevons"},{"id":"a3","texto":"Suficiencia digital"},{"id":"a4","texto":"Demanda creciente"}],"derecha":[{"id":"b1","texto":"Un chip que hace el doble de cálculos por watt"},{"id":"b2","texto":"Más eficiencia que termina en más consumo total"},{"id":"b3","texto":"Usar un modelo chico si alcanza"},{"id":"b4","texto":"IA incorporada en todas las aplicaciones"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro conceptos para entender la carrera entre eficiencia y demanda."}},{"slug":"digital-3.s4.p11","orden":11,"grupo":"digital-3.s4.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué puede evitar que las mejoras de eficiencia se pierdan por el rebote? Marcá todo.","opciones":[{"id":"o1","texto":"Priorizar los usos de la IA que aportan valor real"},{"id":"o2","texto":"Abastecer los centros de datos con energía renovable"},{"id":"o3","texto":"Publicar cuánta energía y agua usan los servicios"},{"id":"o4","texto":"Promover generar contenido sin límite porque es barato"},{"id":"o5","texto":"Ocultar el consumo para no alarmar"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La eficiencia sirve más cuando va acompañada de prioridades, energía limpia y transparencia."}},{"slug":"digital-3.s4.p12","orden":12,"grupo":"digital-3.s4.p12","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas veces bajó en un año la energía por consulta mediana del asistente de IA de Google, según sus mediciones de 2025.","min":1,"max":1000,"paso":1,"unidad":"veces","escala":"log"},"solucion":{"valor":33,"banda":"log","explicacion":"Unas 33 veces, por mejoras de software, hardware y del uso de los centros de datos. Una mejora enorme en muy poco tiempo."}},{"slug":"digital-3.s4.p13","orden":13,"grupo":"digital-3.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"La eficiencia por consulta mejoró mucho en poco tiempo."},{"id":"s2","texto":"Como cada consulta es más eficiente, la IA ya no es un tema energético."},{"id":"s3","texto":"Jevons observó que el carbón se usó más cuando las máquinas se volvieron eficientes."},{"id":"s4","texto":"Usar el modelo más grande para todo es lo más eficiente."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La eficiencia es una buena noticia, pero no el final de la historia.","por_opcion":{"s2":"La demanda total sigue creciendo y puede superar a la eficiencia.","s4":"Para tareas simples, un modelo chico usa mucha menos energía."}}},{"slug":"digital-3.s4.p14","orden":14,"grupo":"digital-3.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuando la eficiencia termina aumentando el consumo total se habla de la paradoja de {{0}}; usar un modelo chico cuando alcanza es suficiencia {{1}}; y el consumo total depende de la eficiencia y de la {{2}}.","banco":[{"id":"w1","texto":"Jevons"},{"id":"w2","texto":"digital"},{"id":"w3","texto":"demanda"},{"id":"w4","texto":"Newton"},{"id":"w5","texto":"analógica"},{"id":"w6","texto":"publicidad"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para leer la carrera entre eficiencia y demanda."}}]},{"slug":"digital-3.s5","orden":5,"tipo":"leccion","titulo_es":"Qué se puede exigir","bajada_es":"Transparencia, energía limpia, agua y calor: lo que empresas y gobiernos pueden hacer, y lo que conviene hacer como usuario.","minutos":14,"pasos":[{"slug":"digital-3.s5.p1","orden":1,"grupo":"digital-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Transparencia","cuerpo":["Durante años fue difícil saber cuánta energía y agua usaban los centros de datos y los servicios de IA. Eso empieza a cambiar: en la Unión Europea, los centros de datos a partir de cierto tamaño tienen que informar su consumo de energía y de agua, y algunas empresas publican mediciones por consulta. Sin datos públicos no se pueden comparar servicios, planificar redes ni evaluar promesas."]},"solucion":{}},{"slug":"digital-3.s5.p2","orden":2,"grupo":"digital-3.s5.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué datos debería publicar un centro de datos? Marcá todos.","opciones":[{"id":"o1","texto":"Su consumo anual de electricidad"},{"id":"o2","texto":"Su consumo de agua y de qué fuente"},{"id":"o3","texto":"Su PUE"},{"id":"o4","texto":"Qué parte de su energía es renovable, y en qué horas"},{"id":"o5","texto":"Nada, porque es información secreta"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La transparencia permite comparar, planificar y controlar."}},{"slug":"digital-3.s5.p3","orden":3,"grupo":"digital-3.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Energía limpia de verdad","cuerpo":["Muchas empresas dicen usar \"100 % energía renovable\" porque compran, en el año, tanta energía renovable como la que consumen. Pero de noche, cuando no hay sol, su centro de datos puede estar usando electricidad de centrales a gas o carbón. Un estándar más exigente es el de energía libre de carbono hora por hora: que en cada hora el consumo esté cubierto por fuentes limpias de la misma red."]},"solucion":{}},{"slug":"digital-3.s5.p4","orden":4,"grupo":"digital-3.s5.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué diferencia hay entre \"100 % renovable en el año\" y \"libre de carbono hora por hora\"?","opciones":[{"id":"o1","texto":"La segunda cubre con energía limpia cada hora de consumo"},{"id":"o2","texto":"Son exactamente lo mismo dicho con otras palabras"},{"id":"o3","texto":"La primera es más exigente que la segunda"},{"id":"o4","texto":"La segunda solo se aplica a los días de sol"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste con el greenwashing: una afirmación verdadera puede esconder una parte de la historia.","por_opcion":{"o3":"Es al revés: el balance anual permite usar energía fósil en algunas horas."}}},{"slug":"digital-3.s5.p5","orden":5,"grupo":"digital-3.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de datos que dice ser \"100 % renovable\" en el año funciona 8.760 horas, pero en 3.000 de ellas su red usa sobre todo gas. ¿Qué porcentaje de las horas no está cubierto por energía limpia? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"3000 horas con gas de 8760 horas del año."},"solucion":{"valor":34,"tolerancia":1,"explicacion":"3.000 ÷ 8.760 × 100 ≈ 34 %. El balance anual esconde esas horas."}},{"slug":"digital-3.s5.p5.v2","orden":5,"grupo":"digital-3.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de datos que dice ser \"100 % renovable\" en el año funciona 8.760 horas, pero en 4.000 de ellas su red usa sobre todo gas. ¿Qué porcentaje de las horas no está cubierto por energía limpia? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"4000 horas con gas de 8760 horas del año."},"solucion":{"valor":46,"tolerancia":1,"explicacion":"4.000 ÷ 8.760 × 100 ≈ 46 %. El balance anual esconde esas horas."}},{"slug":"digital-3.s5.p5.v3","orden":5,"grupo":"digital-3.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un centro de datos que dice ser \"100 % renovable\" en el año funciona 8.760 horas, pero en 2.000 de ellas su red usa sobre todo gas. ¿Qué porcentaje de las horas no está cubierto por energía limpia? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"2000 horas con gas de 8760 horas del año."},"solucion":{"valor":23,"tolerancia":1,"explicacion":"2.000 ÷ 8.760 × 100 ≈ 23 %. El balance anual esconde esas horas."}},{"slug":"digital-3.s5.p6","orden":6,"grupo":"digital-3.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que puede hacer un gobierno","cuerpo":["Los gobiernos pueden exigir que los nuevos centros de datos informen su consumo, cumplan estándares de eficiencia, no compitan por el agua en cuencas en riesgo, aporten a la expansión de la red y de las renovables, y aprovechen el calor cuando sea posible. También pueden planificar dónde conviene ubicarlos para no sobrecargar redes locales."]},"solucion":{}},{"slug":"digital-3.s5.p7","orden":7,"grupo":"digital-3.s5.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una exigencia razonable o una mala idea?","grupos":[{"id":"g1","nombre":"Exigencia razonable"},{"id":"g2","nombre":"Mala idea"}],"items":[{"id":"i1","texto":"Informar el consumo de energía y agua"},{"id":"i2","texto":"Eximir de informar para atraer inversiones"},{"id":"i3","texto":"Evitar tomar agua de cuencas en sequía"},{"id":"i4","texto":"Instalarlos donde la red ya no da abasto sin ampliarla"},{"id":"i5","texto":"Aprovechar el calor residual si hay demanda cerca"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Las reglas claras protegen a las comunidades y dan previsibilidad a las empresas."}},{"slug":"digital-3.s5.p8","orden":8,"grupo":"digital-3.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Y como usuario","cuerpo":["Como vimos en la base de la rama, la mayor parte de la huella digital de una persona está en fabricar sus dispositivos, no en sus consultas. Usar la IA con sentido —cuando aporta, con la herramienta adecuada, sin generar contenido que nadie necesita— ayuda, pero el peso grande está en las decisiones de empresas y gobiernos. Informarse y exigir transparencia también es una forma de actuar."]},"solucion":{}},{"slug":"digital-3.s5.p9","orden":9,"grupo":"digital-3.s5.p9","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas acciones de una persona por su impacto en la huella digital, de mayor a menor.","items":[{"id":"i1","texto":"Conservar el celular dos años más"},{"id":"i2","texto":"No generar videos con IA que nadie va a ver"},{"id":"i3","texto":"Usar un modelo chico para preguntas simples"},{"id":"i4","texto":"Borrar mails viejos"}],"extremos":["Mayor impacto","Menor impacto"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los dispositivos pesan más que los clics; y generar video pesa más que preguntar.","valores":{"i1":"grande","i2":"moderado","i3":"chico","i4":"casi nulo"}}},{"slug":"digital-3.s5.p10","orden":10,"grupo":"digital-3.s5.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La responsabilidad por la huella de la IA es solo de quienes la usan.","razones":[{"id":"r1","texto":"Porque las decisiones de mayor peso son de empresas y gobiernos"},{"id":"r2","texto":"Porque los usuarios no tienen ninguna influencia"},{"id":"r3","texto":"Porque la IA no tiene huella"}]},"solucion":{"valor":false,"explicacion":"Las decisiones de mayor peso —dónde construir, qué energía usar, cuánta agua tomar, qué modelos ofrecer— las toman empresas y gobiernos.","clave":["r1"]}},{"slug":"digital-3.s5.p11","orden":11,"grupo":"digital-3.s5.p11","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La IA también puede ayudar","cuerpo":["La misma tecnología puede ayudar al ambiente: mejorar los pronósticos del tiempo, detectar incendios y desmontes en imágenes satelitales, gestionar redes eléctricas con muchas renovables o encontrar fugas de agua. El desafío es orientar su uso hacia lo que aporta, y que su propia huella no crezca sin control."]},"solucion":{}},{"slug":"digital-3.s5.p12","orden":12,"grupo":"digital-3.s5.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿En qué usos la IA puede ayudar al ambiente? Marcá todos.","opciones":[{"id":"o1","texto":"Detectar desmontes en imágenes satelitales"},{"id":"o2","texto":"Mejorar pronósticos del tiempo"},{"id":"o3","texto":"Gestionar redes eléctricas con renovables"},{"id":"o4","texto":"Generar publicidad infinita para vender más"},{"id":"o5","texto":"Reemplazar la medición real de la calidad del aire"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La IA es una herramienta: su balance depende de para qué se use."}},{"slug":"digital-3.s5.p13","orden":13,"grupo":"digital-3.s5.p13","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la transparencia mejora la huella del sector.","items":[{"id":"i1","texto":"Una norma obliga a publicar consumo de energía y agua"},{"id":"i2","texto":"Se pueden comparar los centros de datos entre sí"},{"id":"i3","texto":"Comunidades y gobiernos detectan dónde hay problemas"},{"id":"i4","texto":"Se exigen mejoras donde más hacen falta"},{"id":"i5","texto":"Baja la huella de todo el sector"},{"id":"i6","texto":"Ocultar los datos obliga a mejorar más rápido"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Lo que no se mide no se puede mejorar ni exigir."}},{"slug":"digital-3.s5.p14","orden":14,"grupo":"digital-3.s5.p14","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una empresa dice ser \"100 % renovable\" porque compra certificados por todo su consumo anual. ¿Qué pregunta conviene hacer?","opciones":[{"id":"o1","texto":"¿Qué energía usa de noche y en qué red?"},{"id":"o2","texto":"¿De qué color es el logo de la empresa?"},{"id":"o3","texto":"¿Cuántos empleados tiene la empresa?"},{"id":"o4","texto":"¿Cuánto cuesta la acción de la empresa?"}]},"solucion":{"clave":["o1"],"explicacion":"El balance anual puede esconder muchas horas de energía fósil.","por_opcion":{"o3":"No dice nada sobre la energía que usa en cada hora."}}},{"slug":"digital-3.s5.p15","orden":15,"grupo":"digital-3.s5.p15","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este reclamo vecinal y marcá lo que no se sostiene.","segmentos":[{"id":"s1","texto":"Pedimos que el centro de datos publique cuánta agua usa."},{"id":"s2","texto":"Cada consulta de IA gasta más energía que una casa en un año."},{"id":"s3","texto":"Pedimos que no tome agua de la cuenca en época de sequía."},{"id":"s4","texto":"Pedimos que aproveche su calor para el hospital vecino, si es viable."}]},"solucion":{"clave":["s2"],"explicacion":"Un reclamo fuerte se apoya en datos correctos: una exageración le quita credibilidad.","por_opcion":{"s2":"Una consulta de texto usa del orden de décimas de Wh."}}},{"slug":"digital-3.s5.p16","orden":16,"grupo":"digital-3.s5.p16","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cubrir con energía limpia cada hora de consumo es ser libre de {{0}} hora por hora; exigir que se publique el consumo de agua es pedir {{1}}; y para una persona, lo que más pesa es conservar sus {{2}}.","banco":[{"id":"w1","texto":"carbono"},{"id":"w2","texto":"transparencia"},{"id":"w3","texto":"dispositivos"},{"id":"w4","texto":"azúcar"},{"id":"w5","texto":"silencio"},{"id":"w6","texto":"contraseñas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de lo que se puede exigir y hacer."}}]},{"slug":"digital-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: centros de datos e IA","bajada_es":"PUE, refrigeración, agua, energía de la IA, eficiencia y demanda, y transparencia, mezclados.","minutos":8,"pasos":[{"slug":"digital-3.s6.p1","orden":1,"grupo":"digital-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Centros de datos e inteligencia artificial». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"digital-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el centro de datos que llega al pueblo","bajada_es":"Una empresa quiere construir un centro de datos en un pueblo patagónico. Evaluá la propuesta con números y definí condiciones.","minutos":10,"pasos":[{"slug":"digital-3.s7.p1","orden":1,"grupo":"digital-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La propuesta","cuerpo":["La empresa propone un centro de datos con servidores de 20 MW y un PUE de 1,2, gracias a que el clima frío permite enfriar con aire exterior casi todo el año. Promete contratar energía eólica de la zona y usar agua solo en los días más calurosos. El pueblo tiene 15.000 habitantes y su red eléctrica local tiene poca capacidad disponible. Los hogares consumen en promedio unos 3.000 kWh por año."]},"solucion":{}},{"slug":"digital-3.s7.p2","orden":2,"grupo":"digital-3.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos MW consume el centro de datos en total, con su PUE de 1,2?","unidad":"MW","decimales":0,"contexto":"Servidores de 20 MW; PUE 1,2."},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"20 × 1,2 = 24 MW: 20 para los servidores y 4 para refrigeración y apoyo."}},{"slug":"digital-3.s7.p3","orden":3,"grupo":"digital-3.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si funciona todo el año, ¿cuántos MWh consume por año? (24 MW × 8.760 horas)","unidad":"MWh","decimales":0,"contexto":"24 MW durante 8.760 horas."},"solucion":{"valor":210240,"tolerancia":4204.8,"explicacion":"24 × 8.760 = 210.240 MWh por año, unos 210 GWh."}},{"slug":"digital-3.s7.p4","orden":4,"grupo":"digital-3.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿A cuántos hogares de 3.000 kWh por año equivale ese consumo? (1 MWh = 1.000 kWh)","unidad":"hogares","decimales":0,"contexto":"210.240 MWh por año; 3.000 kWh por hogar."},"solucion":{"valor":70080,"tolerancia":1401.6000000000001,"explicacion":"210.240 MWh = 210.240.000 kWh; ÷ 3.000 = 70.080 hogares, casi cinco veces todos los hogares posibles de un pueblo de 15.000 habitantes."}},{"slug":"digital-3.s7.p5","orden":5,"grupo":"digital-3.s7.p5","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué condiciones conviene exigir antes de aprobarlo? Marcá todas.","opciones":[{"id":"o1","texto":"Que financie la ampliación de la red sin que la paguen los vecinos"},{"id":"o2","texto":"Que publique cada año su consumo de energía y agua"},{"id":"o3","texto":"Que la energía eólica sume parques nuevos y no le quite energía limpia al pueblo"},{"id":"o4","texto":"Que evalúe aprovechar su calor para edificios públicos"},{"id":"o5","texto":"Que no informe nada para proteger su secreto comercial"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Con condiciones claras, un proyecto así puede aportar; sin ellas, puede sobrecargar la red y generar conflictos."}},{"slug":"digital-3.s7.p6","orden":6,"grupo":"digital-3.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué es importante que la energía eólica provenga de parques nuevos?","opciones":[{"id":"o1","texto":"Para no desplazar energía limpia que ya usaba la red"},{"id":"o2","texto":"Porque los parques viejos no generan electricidad"},{"id":"o3","texto":"Porque la energía eólica nueva es gratis"},{"id":"o4","texto":"Porque así el PUE baja a cero"}]},"solucion":{"clave":["o1"],"explicacion":"Si solo compra energía que ya existía, otros usuarios usan más fósil: la adicionalidad importa.","por_opcion":{"o3":"No lo es; el punto es que sume energía limpia, no que la reparta."}}},{"slug":"digital-3.s7.p7","orden":7,"grupo":"digital-3.s7.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el clima es frío y el PUE es bajo, el proyecto no tiene ningún impacto a considerar.","razones":[{"id":"r1","texto":"Porque su consumo total es enorme para la red local"},{"id":"r2","texto":"Porque el clima frío aumenta el consumo"},{"id":"r3","texto":"Porque los centros de datos no usan electricidad"}]},"solucion":{"valor":false,"explicacion":"Aunque sea eficiente, su consumo total equivale a decenas de miles de hogares y puede presionar la red local. Hay que evaluar red, energía, agua y beneficios para el pueblo.","clave":["r1"]}},{"slug":"digital-3.s7.p8","orden":8,"grupo":"digital-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El municipio redacta el acuerdo. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"La empresa informará cada año su consumo de energía y agua."},{"id":"s2","texto":"La ampliación de la red la pagarán los vecinos con sus tarifas."},{"id":"s3","texto":"La empresa evaluará usar su calor en la escuela y el hospital."},{"id":"s4","texto":"No se pedirán datos de agua porque el clima es frío."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen acuerdo protege a la comunidad y hace previsible el proyecto.","por_opcion":{"s2":"Quien genera la demanda debería financiar la ampliación.","s4":"Igual usará agua en días calurosos: hay que medir y publicar."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"digital-4","rama":"digital","orden":4,"nivel":2,"titulo_es":"De la mina al celular","bajada_es":"Litio de la Puna, cobalto del Congo, oro en los conectores: de dónde salen los materiales de nuestros aparatos, qué costos tienen y cómo recuperarlos.","objetivos_es":["Identificar los principales minerales de un celular y para qué sirven","Describir cómo se extrae litio de los salares y qué se debate sobre el agua","Explicar la consulta previa, libre e informada y el reparto de beneficios","Reconocer los riesgos de derechos humanos en cadenas de minerales como el cobalto","Evaluar la minería urbana y el reciclaje de aparatos como parte de la solución"],"repasa":["digital-1","movilidad-4","comunidad-2","consumo-3"],"requiere_tronco":2,"fuentes":["usgs-litio-2025","usgs-cobalto-2025","iea-minerales-2025","ley-24196-mineria","ley-24071-oit-169","amnistia-cobalto","ocde-diligencia-minerales","ue-minerales-conflicto","ewaste-monitor"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"digital-4.s1","orden":1,"tipo":"leccion","titulo_es":"Qué tiene un celular","bajada_es":"Decenas de elementos de la tabla periódica, cada uno con su función y su mina de origen.","minutos":11,"pasos":[{"slug":"digital-4.s1.p1","orden":1,"grupo":"digital-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una tabla periódica en el bolsillo","cuerpo":["Un celular contiene decenas de elementos químicos distintos. En la batería hay litio y, en muchos modelos, cobalto. En los circuitos, cobre. En los conectores, pequeñas cantidades de oro. En las soldaduras, estaño. En algunos componentes electrónicos, tantalio. En los parlantes y el vibrador, imanes con tierras raras como el neodimio. En la pantalla, indio y vidrio especial. Cada uno viene de minas de distintos lugares del mundo."]},"solucion":{}},{"slug":"digital-4.s1.p2","orden":2,"grupo":"digital-4.s1.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada material con su función en un celular.","izquierda":[{"id":"a1","texto":"Litio"},{"id":"a2","texto":"Cobre"},{"id":"a3","texto":"Oro"},{"id":"a4","texto":"Neodimio"},{"id":"a5","texto":"Estaño"}],"derecha":[{"id":"b1","texto":"Batería"},{"id":"b2","texto":"Circuitos y cables"},{"id":"b3","texto":"Conectores que no se oxidan"},{"id":"b4","texto":"Imanes de parlantes y vibrador"},{"id":"b5","texto":"Soldaduras"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Cada componente depende de minerales específicos: por eso fabricar un celular tiene tanta huella."}},{"slug":"digital-4.s1.p3","orden":3,"grupo":"digital-4.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La huella está en fabricar","cuerpo":["Como viste en la base de la rama, la mayor parte de la huella de un celular está en su fabricación: extraer y procesar los minerales, fabricar los chips y armarlo. Extraer los minerales implica mover grandes cantidades de roca, usar agua y energía, y a veces afectar ecosistemas y comunidades. Por eso conservar un aparato más tiempo es una de las decisiones que más pesan."]},"solucion":{}},{"slug":"digital-4.s1.p4","orden":4,"grupo":"digital-4.s1.p4","tipo":"cadena","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de un mineral desde la mina hasta el celular.","items":[{"id":"i1","texto":"Se extrae roca o salmuera de una mina"},{"id":"i2","texto":"Se concentra y se refina el mineral"},{"id":"i3","texto":"Se fabrica un componente, como una batería"},{"id":"i4","texto":"Se arma el celular en una fábrica"},{"id":"i5","texto":"Llega al negocio y a tus manos"},{"id":"i6","texto":"El celular se fabrica directamente en la mina"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una cadena larga, que suele cruzar varios países y continentes."}},{"slug":"digital-4.s1.p5","orden":5,"grupo":"digital-4.s1.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿En qué parte del celular está cada material?","grupos":[{"id":"g1","nombre":"Batería"},{"id":"g2","nombre":"Circuitos y conexiones"},{"id":"g3","nombre":"Pantalla y parlantes"}],"items":[{"id":"i1","texto":"Litio"},{"id":"i2","texto":"Cobre"},{"id":"i3","texto":"Indio"},{"id":"i4","texto":"Cobalto"},{"id":"i5","texto":"Oro"},{"id":"i6","texto":"Neodimio"},{"id":"i7","texto":"Estaño"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g2"},"explicacion":"La batería, los circuitos y la pantalla concentran los minerales más críticos."}},{"slug":"digital-4.s1.p6","orden":6,"grupo":"digital-4.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cantidades chicas, montañas de roca","cuerpo":["Un celular tiene muy poco oro: unas decenas de miligramos, del orden de lo que pesa un grano de arroz. Pero en muchas minas se obtienen pocos gramos de oro por tonelada de roca. Eso significa que, detrás de ese poquito de metal, hay toneladas de roca removida, agua, energía y residuos mineros. Lo mismo pasa, en distinta medida, con otros metales."]},"solucion":{}},{"slug":"digital-4.s1.p7","orden":7,"grupo":"digital-4.s1.p7","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una mina obtiene 5 gramos de oro por tonelada de roca, ¿cuántos kilos de roca hay que procesar para obtener los 30 miligramos de oro de un celular? Redondeá a un decimal.","unidad":"kg de roca","decimales":1,"contexto":"5 g de oro por tonelada; 30 mg de oro en el celular."},"solucion":{"valor":6,"tolerancia":0.1,"explicacion":"30 mg = 0,03 g. 0,03 ÷ 5 g/t = 0,006 t ≈ 6 kg de roca, solo por el oro de un celular. Valores de ejemplo."}},{"slug":"digital-4.s1.p7.v2","orden":7,"grupo":"digital-4.s1.p7","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una mina obtiene 2 gramos de oro por tonelada de roca, ¿cuántos kilos de roca hay que procesar para obtener los 25 miligramos de oro de un celular? Redondeá a un decimal.","unidad":"kg de roca","decimales":1,"contexto":"2 g de oro por tonelada; 25 mg de oro en el celular."},"solucion":{"valor":12.5,"tolerancia":0.1,"explicacion":"25 mg = 0,025 g. 0,025 ÷ 2 g/t = 0,013 t ≈ 12,5 kg de roca, solo por el oro de un celular. Valores de ejemplo."}},{"slug":"digital-4.s1.p7.v3","orden":7,"grupo":"digital-4.s1.p7","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una mina obtiene 4 gramos de oro por tonelada de roca, ¿cuántos kilos de roca hay que procesar para obtener los 40 miligramos de oro de un celular? Redondeá a un decimal.","unidad":"kg de roca","decimales":1,"contexto":"4 g de oro por tonelada; 40 mg de oro en el celular."},"solucion":{"valor":10,"tolerancia":0.1,"explicacion":"40 mg = 0,04 g. 0,04 ÷ 4 g/t = 0,01 t ≈ 10 kg de roca, solo por el oro de un celular. Valores de ejemplo."}},{"slug":"digital-4.s1.p8","orden":8,"grupo":"digital-4.s1.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como un celular tiene muy poca cantidad de cada metal, su extracción no tiene impacto.","razones":[{"id":"r1","texto":"Porque poco metal puede requerir mucha roca, agua y energía"},{"id":"r2","texto":"Porque los metales aparecen solos en la superficie"},{"id":"r3","texto":"Porque los celulares no tienen metales"}]},"solucion":{"valor":false,"explicacion":"Poca cantidad de metal puede requerir mucha roca, agua y energía, porque en las minas el metal está muy diluido. Y se fabrican más de mil millones de celulares por año.","clave":["r1"]}},{"slug":"digital-4.s1.p9","orden":9,"grupo":"digital-4.s1.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué impactos puede tener extraer los minerales de un celular? Marcá todos.","opciones":[{"id":"o1","texto":"Mover grandes cantidades de roca"},{"id":"o2","texto":"Usar agua en zonas donde escasea"},{"id":"o3","texto":"Afectar comunidades cercanas a las minas"},{"id":"o4","texto":"Producir oxígeno para el aire"},{"id":"o5","texto":"Crear suelos más fértiles automáticamente"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La minería tiene impactos que se pueden reducir y controlar, pero no eliminar."}},{"slug":"digital-4.s1.p10","orden":10,"grupo":"digital-4.s1.p10","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué decisión de una persona reduce más la demanda de minerales?","opciones":[{"id":"o1","texto":"Usar el mismo celular varios años más"},{"id":"o2","texto":"Comprar una funda nueva cada mes"},{"id":"o3","texto":"Cargar el celular solo de noche"},{"id":"o4","texto":"Borrar fotos viejas"}]},"solucion":{"clave":["o1"],"explicacion":"Cada año extra de uso es un aparato menos que fabricar.","por_opcion":{"o3":"Puede cuidar la batería, pero pesa poco frente a no comprar otro."}}},{"slug":"digital-4.s1.p11","orden":11,"grupo":"digital-4.s1.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Comprar un celular reacondicionado evita buena parte de la huella de fabricar uno nuevo.","razones":[{"id":"r1","texto":"Porque aprovecha un aparato que ya existe"},{"id":"r2","texto":"Porque los reacondicionados se fabrican desde cero"},{"id":"r3","texto":"Porque los celulares no tienen huella de fabricación"}]},"solucion":{"valor":true,"explicacion":"Se aprovecha un aparato que ya existe: se evita extraer y procesar la mayor parte de sus materiales, aunque la reparación y el transporte tengan algo de huella.","clave":["r1"]}},{"slug":"digital-4.s1.p12","orden":12,"grupo":"digital-4.s1.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Un celular contiene decenas de elementos químicos."},{"id":"s2","texto":"El oro de los conectores sale de reciclar hojas secas."},{"id":"s3","texto":"La batería suele tener litio."},{"id":"s4","texto":"Fabricar un celular casi no tiene huella; lo que pesa es cargarlo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Saber de dónde vienen los materiales cambia cómo vemos un aparato.","por_opcion":{"s2":"Sale de minas o de reciclar aparatos; no de hojas.","s4":"La mayor parte de la huella está en la fabricación."}}},{"slug":"digital-4.s1.p13","orden":13,"grupo":"digital-4.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La batería de un celular suele tener {{0}}; los imanes de los parlantes usan tierras raras como el {{1}}; y la mayor parte de la huella está en {{2}}.","banco":[{"id":"w1","texto":"litio"},{"id":"w2","texto":"neodimio"},{"id":"w3","texto":"fabricarlo"},{"id":"w4","texto":"plomo"},{"id":"w5","texto":"carbono"},{"id":"w6","texto":"cargarlo"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre los materiales de un celular."}},{"slug":"digital-4.s1.p14","orden":14,"grupo":"digital-4.s1.p14","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas decisiones por cuánto reducen la demanda de minerales, de más a menos.","items":[{"id":"i1","texto":"Usar el mismo celular dos años más"},{"id":"i2","texto":"Comprar un celular reacondicionado"},{"id":"i3","texto":"Reciclar el celular viejo al cambiarlo"},{"id":"i4","texto":"Cambiar el fondo de pantalla"}],"extremos":["Reduce más","Reduce menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero alargar la vida, después reutilizar, y el reciclaje al final.","valores":{"i1":"evita un aparato nuevo","i2":"evita buena parte","i3":"recupera algunos metales","i4":"nada"}}}]},{"slug":"digital-4.s2","orden":2,"tipo":"leccion","titulo_es":"El litio de la Puna","bajada_es":"Argentina en el triángulo del litio: salares, salmuera, piletas de evaporación y lo que se discute sobre el agua.","minutos":11,"pasos":[{"slug":"digital-4.s2.p1","orden":1,"grupo":"digital-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El triángulo del litio","cuerpo":["El litio es clave para las baterías de celulares, computadoras, autos eléctricos y sistemas de almacenamiento de energía. Según el Servicio Geológico de Estados Unidos, de los unos 115 millones de toneladas de recursos de litio identificados en el mundo, Argentina y Bolivia tienen unos 23 millones cada una y Chile unos 11: juntos, casi la mitad. Por eso a esa región de salares de la Puna se la llama el triángulo del litio.","En 2024, Argentina produjo unas 18.000 toneladas de litio, más del doble que en 2023, y fue el quinto productor mundial, detrás de Australia, Chile, China y Zimbabue."],"datos":{"tipo":"barras","titulo":"Producción de litio en 2024 (estimada)","unidad":"miles de toneladas","filas":[{"etiqueta":"Australia","valor":88},{"etiqueta":"Chile","valor":49},{"etiqueta":"China","valor":41},{"etiqueta":"Zimbabue","valor":22},{"etiqueta":"Argentina","valor":18}],"nota":"Servicio Geológico de EE. UU., Mineral Commodity Summaries 2025."}},"solucion":{}},{"slug":"digital-4.s2.p2","orden":2,"grupo":"digital-4.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en el mundo hay unos 115 millones de toneladas de recursos de litio y Argentina tiene 23, Bolivia 23 y Chile 11, ¿qué porcentaje tienen entre los tres? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"57 de 115 millones de toneladas."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"(23 + 23 + 11) ÷ 115 × 100 ≈ 50 %. Casi la mitad de los recursos identificados está en el triángulo del litio."}},{"slug":"digital-4.s2.p2.v2","orden":2,"grupo":"digital-4.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"De 115 millones de toneladas de recursos de litio del mundo, ¿qué porcentaje reúnen Argentina (23), Bolivia (23) y Chile (11)? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"57 de 115 millones de toneladas."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"(23 + 23 + 11) ÷ 115 × 100 ≈ 50 %. Casi la mitad de los recursos identificados está en el triángulo del litio."}},{"slug":"digital-4.s2.p2.v3","orden":2,"grupo":"digital-4.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Argentina, Bolivia y Chile suman 57 millones de toneladas de recursos de litio, sobre 115 millones en el mundo. ¿Qué porcentaje es? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"57 de 115 millones de toneladas."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"(23 + 23 + 11) ÷ 115 × 100 ≈ 50 %. Casi la mitad de los recursos identificados está en el triángulo del litio."}},{"slug":"digital-4.s2.p3","orden":3,"grupo":"digital-4.s2.p3","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos países según su producción de litio en 2024, de mayor a menor.","items":[{"id":"i1","texto":"Australia"},{"id":"i2","texto":"Chile"},{"id":"i3","texto":"China"},{"id":"i4","texto":"Argentina"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Argentina tiene muchos recursos, pero su producción todavía es menor que la de otros países.","valores":{"i1":"≈ 88.000 t","i2":"≈ 49.000 t","i3":"≈ 41.000 t","i4":"≈ 18.000 t"}}},{"slug":"digital-4.s2.p4","orden":4,"grupo":"digital-4.s2.p4","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas toneladas de litio produjo Argentina en 2024, según el USGS.","min":100,"max":1000000,"paso":1,"unidad":"t","escala":"log"},"solucion":{"valor":18000,"banda":"log","explicacion":"Unas 18.000 toneladas, más del doble que en 2023. Australia produjo unas 88.000."}},{"slug":"digital-4.s2.p5","orden":5,"grupo":"digital-4.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo se extrae de un salar","cuerpo":["En Australia, el litio se extrae de rocas duras. En los salares de la Puna, en cambio, está disuelto en una salmuera, un agua muy salada que hay bajo la costra de sal. En el método tradicional, se bombea la salmuera a grandes piletas donde el sol evapora el agua durante meses, hasta concentrar el litio, que luego se procesa en una planta. También se desarrollan métodos de extracción directa, que separan el litio sin evaporar tanta agua, pero todavía se están probando a gran escala."]},"solucion":{}},{"slug":"digital-4.s2.p6","orden":6,"grupo":"digital-4.s2.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de la extracción de litio por evaporación.","items":[{"id":"i1","texto":"Se bombea salmuera desde debajo del salar"},{"id":"i2","texto":"Se vuelca en piletas al aire libre"},{"id":"i3","texto":"El sol evapora el agua durante meses"},{"id":"i4","texto":"La salmuera concentrada va a una planta de procesamiento"},{"id":"i5","texto":"Se obtiene carbonato de litio"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El método aprovecha el sol y el clima seco de la Puna, pero implica sacar grandes volúmenes de salmuera."}},{"slug":"digital-4.s2.p7","orden":7,"grupo":"digital-4.s2.p7","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la Puna es un lugar donde conviene evaporar salmuera al sol?","opciones":[{"id":"o1","texto":"Porque es muy seca, soleada y ventosa"},{"id":"o2","texto":"Porque llueve casi todos los días del año"},{"id":"o3","texto":"Porque está al nivel del mar"},{"id":"o4","texto":"Porque allí el agua no se evapora nunca"}]},"solucion":{"clave":["o1"],"explicacion":"El clima que facilita la evaporación es el mismo que hace tan valiosa cada gota de agua dulce.","por_opcion":{"o3":"La Puna está a más de 3.000 metros de altura."}}},{"slug":"digital-4.s2.p8","orden":8,"grupo":"digital-4.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El debate sobre el agua","cuerpo":["La Puna es una de las zonas más secas del país. La salmuera que se evapora no es agua dulce, pero los salares forman parte de sistemas hidrológicos donde también hay vegas, lagunas y acuíferos de agua dulce de los que dependen comunidades, ganado y aves como los flamencos. Además, las plantas de procesamiento usan agua dulce. Hay debate sobre cuánto afecta sacar salmuera al equilibrio del agua de toda la cuenca, y muchas investigaciones y comunidades piden estudios de impacto acumulativo, que miren todos los proyectos de una misma cuenca juntos."]},"solucion":{}},{"slug":"digital-4.s2.p9","orden":9,"grupo":"digital-4.s2.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué preocupa el agua en un salar.","items":[{"id":"i1","texto":"Se extraen grandes volúmenes de salmuera del salar"},{"id":"i2","texto":"Puede cambiar el equilibrio del agua subterránea de la cuenca"},{"id":"i3","texto":"Pueden bajar niveles en vegas y lagunas de agua dulce cercanas"},{"id":"i4","texto":"Se afectan pasturas, ganado, aves y comunidades"},{"id":"i5","texto":"La salmuera extraída se convierte en agua de lluvia"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Por eso se piden estudios de toda la cuenca, antes y durante los proyectos."}},{"slug":"digital-4.s2.p10","orden":10,"grupo":"digital-4.s2.p10","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como la salmuera no es agua potable, extraerla no puede tener ningún efecto sobre el agua dulce.","razones":[{"id":"r1","texto":"Porque salmuera y agua dulce pueden estar conectadas en la cuenca"},{"id":"r2","texto":"Porque la salmuera es agua potable"},{"id":"r3","texto":"Porque en la Puna llueve muchísimo"}]},"solucion":{"valor":false,"explicacion":"Salmuera y agua dulce pueden estar conectadas en el mismo sistema de la cuenca. Por eso hacen falta estudios hidrológicos de toda la cuenca y monitoreo permanente.","clave":["r1"]}},{"slug":"digital-4.s2.p11","orden":11,"grupo":"digital-4.s2.p11","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un argumento a favor de la minería de litio o una preocupación?","grupos":[{"id":"g1","nombre":"A favor"},{"id":"g2","nombre":"Preocupación"}],"items":[{"id":"i1","texto":"Es clave para baterías de autos eléctricos y renovables"},{"id":"i2","texto":"Posible efecto sobre vegas y agua dulce de la cuenca"},{"id":"i3","texto":"Puede generar empleo y recursos para las provincias"},{"id":"i4","texto":"Falta de estudios de impacto acumulativo"},{"id":"i5","texto":"Consulta insuficiente a comunidades"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Un debate serio reconoce las dos columnas y busca condiciones para que los beneficios no se paguen con daños irreversibles."}},{"slug":"digital-4.s2.p12","orden":12,"grupo":"digital-4.s2.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Salmuera"},{"id":"a2","texto":"Pileta de evaporación"},{"id":"a3","texto":"Extracción directa"},{"id":"a4","texto":"Impacto acumulativo"}],"derecha":[{"id":"b1","texto":"Agua muy salada bajo la costra del salar"},{"id":"b2","texto":"Donde el sol concentra el litio"},{"id":"b3","texto":"Método que separa el litio sin evaporar tanta agua"},{"id":"b4","texto":"Efecto de todos los proyectos de una cuenca juntos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Vocabulario para entender el debate del litio."}},{"slug":"digital-4.s2.p13","orden":13,"grupo":"digital-4.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Argentina está entre los países con más recursos de litio del mundo."},{"id":"s2","texto":"En la Puna el litio se saca de rocas duras, como en Australia."},{"id":"s3","texto":"En 2024 Argentina más que duplicó su producción de litio."},{"id":"s4","texto":"Evaluar cada proyecto por separado alcanza para conocer el impacto en la cuenca."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un debate informado empieza por los datos correctos.","por_opcion":{"s2":"En la Puna se extrae de la salmuera de los salares.","s4":"Hacen falta estudios de impacto acumulativo de todos los proyectos."}}},{"slug":"digital-4.s2.p14","orden":14,"grupo":"digital-4.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La región de salares de Argentina, Bolivia y Chile se llama el triángulo del {{0}}; en la Puna el litio está disuelto en una {{1}}; y mirar todos los proyectos de una cuenca juntos es evaluar el impacto {{2}}.","banco":[{"id":"w1","texto":"litio"},{"id":"w2","texto":"salmuera"},{"id":"w3","texto":"acumulativo"},{"id":"w4","texto":"cobre"},{"id":"w5","texto":"arcilla"},{"id":"w6","texto":"individual"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas clave sobre el litio de la Puna."}}]},{"slug":"digital-4.s3","orden":3,"tipo":"leccion","titulo_es":"Comunidades, consulta y beneficios","bajada_es":"Quiénes viven en los territorios, qué es la consulta previa y cómo se reparten los beneficios de la minería.","minutos":11,"pasos":[{"slug":"digital-4.s3.p1","orden":1,"grupo":"digital-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los territorios tienen gente","cuerpo":["En la Puna viven comunidades indígenas y campesinas, muchas dedicadas al pastoreo, la extracción artesanal de sal y el turismo. Para ellas, el agua y el territorio son la base de su vida. Argentina aprobó en 1992, por la Ley 24.071, el Convenio 169 de la Organización Internacional del Trabajo, que reconoce el derecho de los pueblos indígenas a ser consultados antes de que se tomen decisiones que los afecten."]},"solucion":{}},{"slug":"digital-4.s3.p2","orden":2,"grupo":"digital-4.s3.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Consulta previa, libre e informada","cuerpo":["La consulta tiene que ser previa (antes de decidir, no cuando la obra ya empezó), libre (sin presiones ni amenazas), informada (con información completa, comprensible y en tiempo) y de buena fe, con procedimientos adecuados a cada pueblo. No es una reunión informativa ni una firma apurada: es un proceso de diálogo que puede cambiar el proyecto."]},"solucion":{}},{"slug":"digital-4.s3.p3","orden":3,"grupo":"digital-4.s3.p3","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada condición de la consulta con su significado.","izquierda":[{"id":"a1","texto":"Previa"},{"id":"a2","texto":"Libre"},{"id":"a3","texto":"Informada"},{"id":"a4","texto":"De buena fe"}],"derecha":[{"id":"b1","texto":"Antes de tomar la decisión"},{"id":"b2","texto":"Sin presiones ni amenazas"},{"id":"b3","texto":"Con información completa y comprensible"},{"id":"b4","texto":"Con intención real de escuchar y acordar"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Si falta cualquiera de estas condiciones, no es una verdadera consulta."}},{"slug":"digital-4.s3.p4","orden":4,"grupo":"digital-4.s3.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una empresa convoca a una comunidad a una reunión cuando la planta ya está construida. ¿Por qué no cumple con la consulta previa?","opciones":[{"id":"o1","texto":"Porque la decisión ya se había tomado"},{"id":"o2","texto":"Porque las reuniones están prohibidas"},{"id":"o3","texto":"Porque la comunidad no tiene ningún derecho"},{"id":"o4","texto":"Porque la reunión fue en la plaza"}]},"solucion":{"clave":["o1"],"explicacion":"Consultar después de decidir es informar, no consultar.","por_opcion":{"o3":"Tiene derecho a ser consultada, según el Convenio 169."}}},{"slug":"digital-4.s3.p5","orden":5,"grupo":"digital-4.s3.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una consulta adecuada o no?","grupos":[{"id":"g1","nombre":"Adecuada"},{"id":"g2","nombre":"No adecuada"}],"items":[{"id":"i1","texto":"Varias reuniones antes de aprobar el proyecto, con traducción y tiempo para deliberar"},{"id":"i2","texto":"Una reunión única cuando ya se otorgaron los permisos"},{"id":"i3","texto":"Información técnica explicada en lenguaje claro"},{"id":"i4","texto":"Firmas pedidas a cambio de regalos"},{"id":"i5","texto":"Acuerdos que modifican el proyecto según lo planteado"},{"id":"i6","texto":"Un documento técnico de 500 páginas entregado un día antes"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La calidad del proceso importa tanto como que exista."}},{"slug":"digital-4.s3.p6","orden":6,"grupo":"digital-4.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El reparto de los beneficios","cuerpo":["En Argentina, los recursos naturales pertenecen a las provincias. Por la Ley 24.196, de inversiones mineras, las provincias que adhieren no pueden cobrar regalías mayores al 3 % del valor del mineral en boca de mina. Además de las regalías, los beneficios pueden llegar como empleo local, compras a proveedores de la región, infraestructura y fondos para las comunidades. Cuánto queda en el territorio es parte central del debate."]},"solucion":{}},{"slug":"digital-4.s3.p7","orden":7,"grupo":"digital-4.s3.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una mina extrae mineral por un valor en boca de mina de 500 millones de dólares por año, ¿cuánto recibe como máximo la provincia en regalías del 3 %?","unidad":"millones de dólares","decimales":0,"contexto":"Valor en boca de mina 500 millones; regalías del 3 %."},"solucion":{"valor":15,"tolerancia":0.5,"explicacion":"500 × 0,03 = 15 millones de dólares por año, como máximo por regalías. Otros beneficios pueden llegar por empleo, proveedores e infraestructura."}},{"slug":"digital-4.s3.p7.v2","orden":7,"grupo":"digital-4.s3.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una mina extrae mineral por un valor en boca de mina de 800 millones de dólares por año, ¿cuánto recibe como máximo la provincia en regalías del 3 %?","unidad":"millones de dólares","decimales":0,"contexto":"Valor en boca de mina 800 millones; regalías del 3 %."},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"800 × 0,03 = 24 millones de dólares por año, como máximo por regalías. Otros beneficios pueden llegar por empleo, proveedores e infraestructura."}},{"slug":"digital-4.s3.p7.v3","orden":7,"grupo":"digital-4.s3.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una mina extrae mineral por un valor en boca de mina de 1.200 millones de dólares por año, ¿cuánto recibe como máximo la provincia en regalías del 3 %?","unidad":"millones de dólares","decimales":0,"contexto":"Valor en boca de mina 1200 millones; regalías del 3 %."},"solucion":{"valor":36,"tolerancia":0.72,"explicacion":"1.200 × 0,03 = 36 millones de dólares por año, como máximo por regalías. Otros beneficios pueden llegar por empleo, proveedores e infraestructura."}},{"slug":"digital-4.s3.p8","orden":8,"grupo":"digital-4.s3.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿De qué formas pueden quedar beneficios de la minería en el territorio? Marcá todas.","opciones":[{"id":"o1","texto":"Regalías para la provincia"},{"id":"o2","texto":"Empleo de personas de la zona"},{"id":"o3","texto":"Compras a proveedores locales"},{"id":"o4","texto":"Fondos o infraestructura para las comunidades"},{"id":"o5","texto":"Solo en ganancias que se van del país"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El debate no es solo si hay minería, sino cuánto valor y cuántas decisiones quedan en el territorio."}},{"slug":"digital-4.s3.p9","orden":9,"grupo":"digital-4.s3.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá un proceso justo antes de aprobar un proyecto de litio.","items":[{"id":"i1","texto":"Se hace una línea de base del agua y del ambiente de la cuenca"},{"id":"i2","texto":"Se consulta a las comunidades de forma previa, libre e informada"},{"id":"i3","texto":"Se evalúa el impacto acumulativo con otros proyectos"},{"id":"i4","texto":"Se acuerdan condiciones, monitoreo y beneficios"},{"id":"i5","texto":"Recién entonces se decide si aprobar o no"},{"id":"i6","texto":"Primero se construye y después se estudia el agua"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Estudiar, consultar y acordar antes de decidir evita conflictos y daños."}},{"slug":"digital-4.s3.p10","orden":10,"grupo":"digital-4.s3.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un proyecto genera empleo, no hace falta consultar a las comunidades indígenas.","razones":[{"id":"r1","texto":"Porque la consulta es un derecho que no se reemplaza con empleo"},{"id":"r2","texto":"Porque el empleo siempre es malo"},{"id":"r3","texto":"Porque las comunidades no viven en la Puna"}]},"solucion":{"valor":false,"explicacion":"La consulta es un derecho reconocido por el Convenio 169, que Argentina aprobó por ley. Los beneficios económicos no la reemplazan.","clave":["r1"]}},{"slug":"digital-4.s3.p11","orden":11,"grupo":"digital-4.s3.p11","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué beneficio deja más valor en el territorio a largo plazo?","opciones":[{"id":"o1","texto":"Capacitar y emplear a personas de la zona"},{"id":"o2","texto":"Regalar camisetas con el logo del proyecto"},{"id":"o3","texto":"Organizar un acto de inauguración"},{"id":"o4","texto":"Traer todo el personal de otra provincia"}]},"solucion":{"clave":["o1"],"explicacion":"La capacitación y el empleo local construyen capacidades que quedan aunque la mina cierre.","por_opcion":{"o3":"Puede ser simbólico, pero no deja capacidades en la comunidad."}}},{"slug":"digital-4.s3.p12","orden":12,"grupo":"digital-4.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Argentina aprobó el Convenio 169 de la OIT por la Ley 24.071."},{"id":"s2","texto":"La consulta puede hacerse después de otorgar todos los permisos."},{"id":"s3","texto":"Las provincias pueden cobrar regalías de hasta el 3 % en boca de mina."},{"id":"s4","texto":"Una firma a cambio de regalos es una consulta libre."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los derechos de las comunidades son parte del marco legal, no un trámite.","por_opcion":{"s2":"Tiene que ser previa a la decisión.","s4":"Si hay presiones o incentivos indebidos, no es libre."}}},{"slug":"digital-4.s3.p13","orden":13,"grupo":"digital-4.s3.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El convenio que reconoce el derecho a la consulta es el {{0}} de la OIT; la consulta debe ser previa, {{1}} e informada; y las regalías mineras provinciales tienen un tope del {{2}} %.","banco":[{"id":"w1","texto":"169"},{"id":"w2","texto":"libre"},{"id":"w3","texto":"3"},{"id":"w4","texto":"14"},{"id":"w5","texto":"rápida"},{"id":"w6","texto":"30"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves de los derechos y beneficios en la minería."}},{"slug":"digital-4.s3.p14","orden":14,"grupo":"digital-4.s3.p14","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos momentos de consulta de mejor a peor.","items":[{"id":"i1","texto":"Antes de diseñar el proyecto"},{"id":"i2","texto":"Antes de aprobar los permisos"},{"id":"i3","texto":"Con la obra en construcción"},{"id":"i4","texto":"Después de que la mina funciona"}],"extremos":["Mejor momento","Peor momento"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto antes se consulta, más puede cambiar el proyecto.","valores":{"i1":"ideal","i2":"aceptable","i3":"tardía","i4":"no es consulta"}}}]},{"slug":"digital-4.s4","orden":4,"tipo":"leccion","titulo_es":"Cobalto y minerales en conflicto","bajada_es":"Minería artesanal, trabajo infantil y conflictos armados: los riesgos en las cadenas de suministro y cómo se controlan.","minutos":12,"pasos":[{"slug":"digital-4.s4.p1","orden":1,"grupo":"digital-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El cobalto","cuerpo":["El cobalto se usa en muchas baterías de litio. Según el Servicio Geológico de EE. UU., en 2024 la República Democrática del Congo aportó alrededor del 76 % de la producción minera mundial de cobalto. Una parte se extrae en minas artesanales, a veces en condiciones muy peligrosas. En 2016, Amnistía Internacional documentó casos de trabajo infantil en esas minas, y el tema sigue bajo investigación de organizaciones y gobiernos."],"destacado":{"valor":"≈ 76 %","texto":"del cobalto extraído en el mundo en 2024 vino de la República Democrática del Congo, según el USGS."}},"solucion":{}},{"slug":"digital-4.s4.p2","orden":2,"grupo":"digital-4.s4.p2","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de la producción minera mundial de cobalto vino de la República Democrática del Congo en 2024.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":76,"banda":"lineal","explicacion":"Alrededor del 76 %, según el Servicio Geológico de EE. UU. Esa concentración vuelve muy importante lo que pasa en sus minas."}},{"slug":"digital-4.s4.p3","orden":3,"grupo":"digital-4.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Minerales en conflicto","cuerpo":["En algunas regiones, la extracción de estaño, tantalio, tungsteno y oro ha financiado a grupos armados. Por eso se los llama minerales en conflicto. La OCDE elaboró una guía de debida diligencia para que las empresas identifiquen y reduzcan esos riesgos en sus cadenas de suministro, y la Unión Europea exige desde 2021 que los importadores de esos minerales la apliquen."]},"solucion":{}},{"slug":"digital-4.s4.p4","orden":4,"grupo":"digital-4.s4.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es uno de los minerales en conflicto (conocidos como 3TG)?","grupos":[{"id":"g1","nombre":"Mineral en conflicto"},{"id":"g2","nombre":"No está en esa lista"}],"items":[{"id":"i1","texto":"Estaño"},{"id":"i2","texto":"Litio"},{"id":"i3","texto":"Tantalio"},{"id":"i4","texto":"Cobre"},{"id":"i5","texto":"Tungsteno"},{"id":"i6","texto":"Hierro"},{"id":"i7","texto":"Oro"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1"},"explicacion":"La lista incluye estaño, tantalio, tungsteno y oro; otros minerales tienen sus propios riesgos."}},{"slug":"digital-4.s4.p5","orden":5,"grupo":"digital-4.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Debida diligencia","cuerpo":["La debida diligencia es el proceso por el cual una empresa averigua de dónde vienen sus materiales, identifica riesgos de violaciones de derechos humanos o de financiamiento de conflictos, toma medidas para reducirlos y publica lo que hace. No significa abandonar una región —eso puede dejar sin ingresos a comunidades enteras—, sino mejorar las condiciones y la trazabilidad."]},"solucion":{}},{"slug":"digital-4.s4.p6","orden":6,"grupo":"digital-4.s4.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de la debida diligencia en una cadena de minerales.","items":[{"id":"i1","texto":"Rastrear de dónde vienen los materiales"},{"id":"i2","texto":"Identificar riesgos en cada eslabón"},{"id":"i3","texto":"Tomar medidas para reducirlos"},{"id":"i4","texto":"Verificar con auditorías independientes"},{"id":"i5","texto":"Informar públicamente los resultados"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Conocer, actuar, verificar e informar: una cadena responsable se construye paso a paso."}},{"slug":"digital-4.s4.p7","orden":7,"grupo":"digital-4.s4.p7","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una empresa descubre trabajo infantil en una mina que le vende cobalto. ¿Qué respuesta recomienda la debida diligencia?","opciones":[{"id":"o1","texto":"Actuar para eliminarlo y mejorar las condiciones"},{"id":"o2","texto":"Ocultar la información para no afectar su imagen"},{"id":"o3","texto":"Dejar de comprar sin más y olvidarse del tema"},{"id":"o4","texto":"Comprar más barato a esa misma mina"}]},"solucion":{"clave":["o1"],"explicacion":"La salida responsable busca mejorar las condiciones, no esconder el problema ni desentenderse.","por_opcion":{"o3":"Puede empujar a las familias a peores condiciones; la guía propone actuar para mejorar."}}},{"slug":"digital-4.s4.p8","orden":8,"grupo":"digital-4.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la producción mundial de cobalto fue de 290 mil toneladas y el 76 % vino de la República Democrática del Congo, ¿cuántas miles de toneladas son? Redondeá al entero.","unidad":"miles de toneladas","decimales":0,"contexto":"290 mil toneladas; 76 % de un país."},"solucion":{"valor":220,"tolerancia":1,"explicacion":"290 × 76 % ≈ 220 mil toneladas. Una concentración así hace que las condiciones de un país afecten a toda la cadena mundial."}},{"slug":"digital-4.s4.p8.v2","orden":8,"grupo":"digital-4.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la producción mundial de cobalto fue de 290 mil toneladas y el 70 % vino de la República Democrática del Congo, ¿cuántas miles de toneladas son? Redondeá al entero.","unidad":"miles de toneladas","decimales":0,"contexto":"290 mil toneladas; 70 % de un país."},"solucion":{"valor":203,"tolerancia":1,"explicacion":"290 × 70 % ≈ 203 mil toneladas. Una concentración así hace que las condiciones de un país afecten a toda la cadena mundial."}},{"slug":"digital-4.s4.p8.v3","orden":8,"grupo":"digital-4.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la producción mundial de cobalto fue de 240 mil toneladas y el 76 % vino de la República Democrática del Congo, ¿cuántas miles de toneladas son? Redondeá al entero.","unidad":"miles de toneladas","decimales":0,"contexto":"240 mil toneladas; 76 % de un país."},"solucion":{"valor":182,"tolerancia":1,"explicacion":"240 × 76 % ≈ 182 mil toneladas. Una concentración así hace que las condiciones de un país afecten a toda la cadena mundial."}},{"slug":"digital-4.s4.p9","orden":9,"grupo":"digital-4.s4.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué abandonar de golpe una región minera con problemas puede no ser la mejor respuesta de una empresa?","opciones":[{"id":"o1","texto":"Puede dejar sin ingresos a familias que dependen de la mina"},{"id":"o2","texto":"Porque las empresas nunca pueden cambiar de proveedor"},{"id":"o3","texto":"Porque así los problemas se resuelven solos"},{"id":"o4","texto":"Porque la ley prohíbe dejar de comprar"}]},"solucion":{"clave":["o1"],"explicacion":"La debida diligencia busca mejorar las condiciones con la gente que vive de esa actividad, no desentenderse.","por_opcion":{"o3":"Irse no resuelve nada; puede empeorar la situación de la gente."}}},{"slug":"digital-4.s4.p10","orden":10,"grupo":"digital-4.s4.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Baterías sin cobalto","cuerpo":["La tecnología también ayuda: una parte creciente de las baterías, como las de litio-hierro-fosfato (LFP), no usa cobalto ni níquel. Son algo más pesadas por la energía que guardan, pero más baratas y durables, y se usan cada vez más en autos eléctricos y en almacenamiento de energía. Cambiar la química de las baterías es otra forma de reducir riesgos."]},"solucion":{}},{"slug":"digital-4.s4.p11","orden":11,"grupo":"digital-4.s4.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Todas las baterías de litio necesitan cobalto.","razo