ico de las vegas."},{"id":"s4","texto":"No se pedirá plan de cierre porque la mina durará muchos años."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una buena decisión pública combina información, derechos y condiciones exigibles.","por_opcion":{"s2":"Tiene que ser previa a la decisión.","s4":"El plan de cierre y su garantía se definen desde el principio."}}}]}]}$ac$::jsonb);
